 3: import React from 'react';
 4: import { useRouter } from 'next/navigation';
 5: import { SophieCheckoutPage } from '@/components/sophie/SophieCheckoutPage';
 6: import { SophieFooter } from '@/components/sophie/SophieFooter';
 7: 
 8: export default function CheckoutPage() {
 9:   const router = useRouter();
10: 
11:   const handleContinueShopping = () => {
12:     router.push('/shop');
13:   };
14: 
15:   const handleLoginClick = () => {
16:     router.push('/auth/login');
17:   };
18: 
19:   const handleOrderPlaced = (orderData: unknown) => {
20:     // Ready for backend order submission hook
21:     console.log('Order submitted (mock):', orderData);
22:   };
23: 
24:   return (
25:     <main className="min-h-screen bg-[#f3f5f7]">
26:       <SophieCheckoutPage
27:         onContinueShopping={handleContinueShopping}
28:         onLoginClick={handleLoginClick}
29:         onOrderPlaced={handleOrderPlaced}
30:       />
31:       <SophieFooter />
32:     </main>
33:   );
34: }  1: 'use client';
  2: 
  3: import React, { useState } from 'react';
  4: import {
  5:   INITIAL_CHECKOUT_BAG,
  6:   INITIAL_CHECKOUT_FORM,
  7:   DELIVERY_METHODS,
  8:   PAYMENT_METHODS,
  9:   PROMO_CODES
 10: } from './sophieMockData';
 11: 
 12: /**
 13:  * SophieCheckoutPage Component
 14:  * 
 15:  * Luxury bag collection checkout page matching Screenshot 2 & Sophie Aesthetic.
 16:  * Features customer personal & shipping fields, delivery & payment selectors with
 17:  * credit card fields, a live interactive bag summary with quantity steppers and promo code,
 18:  * an order confirmation modal, and toast notifications.
 19:  * 
 20:  * @param {Object} props
 21:  * @param {Array} [props.initialItems] Initial items in bag (defaults to INITIAL_CHECKOUT_BAG)
 22:  * @param {Object} [props.initialForm] Default form values (defaults to INITIAL_CHECKOUT_FORM)
 23:  * @param {Function} [props.onContinueShopping] Callback when user clicks 'Continue Shopping'
 24:  * @param {Function} [props.onOrderPlaced] Callback when order is submitted: (orderData) => void
 25:  * @param {Function} [props.onLoginClick] Callback when 'Log in' prompt is clicked
 26:  */
 27: export function SophieCheckoutPage({
 28:   initialItems = INITIAL_CHECKOUT_BAG,
 29:   initialForm = INITIAL_CHECKOUT_FORM,
 30:   onContinueShopping,
 31:   onOrderPlaced,
 32:   onLoginClick
 33: }) {
 34:   // State
 35:   const [items, setItems] = useState(initialItems);
 36:   const [form, setForm] = useState(initialForm);
 37:   const [promoCode, setPromoCode] = useState('');
 38:   const [discountRate, setDiscountRate] = useState(0); // e.g. 0.25 for 25%
 39:   const [appliedPromoName, setAppliedPromoName] = useState('');
 40:   const [toastMessage, setToastMessage] = useState(null);
 41:   const [confirmedOrder, setConfirmedOrder] = useState(null);
 42: 
 43:   // Toast Helper
 44:   const showToast = (msg) => {
 45:     setToastMessage(msg);
 46:     setTimeout(() => {
 47:       setToastMessage(null);
 48:     }, 3200);
 49:   };
 50: 
 51:   // Form Field Change
 52:   const handleInputChange = (e) => {
 53:     const { name, value, type, checked } = e.target;
 54:     setForm((prev) => ({
 55:       ...prev,
 56:       [name]: type === 'checkbox' ? checked : value
 57:     }));
 58:   };
 59: 
 60:   // Stepper Quantity Handler
 61:   const handleUpdateQty = (id, delta) => {
 62:     setItems((prev) =>
 63:       prev
 64:         .map((item) => {
 65:           if (item.id === id) {
 66:             const nextQty = item.qty + delta;
 67:             return nextQty > 0 ? { ...item, qty: nextQty } : null;
 68:           }
 69:           return item;
 70:         })
 71:         .filter(Boolean)
 72:     );
 73:   };
 74: 
 75:   // Remove Item
 76:   const handleRemoveItem = (id) => {
 77:     const target = items.find((x) => x.id === id);
 78:     setItems((prev) => prev.filter((item) => item.id !== id));
 79:     showToast(`Removed "${target?.name || 'item'}" from your shopping bag`);
 80:   };
 81: 
 82:   // Apply Promo Code
 83:   const handleApplyPromo = () => {
 84:     const code = promoCode.trim().toUpperCase();
 85:     if (!code || code === 'SOPHIE25' || code === 'VIP25' || code === '25OFF') {
 86:       const activeCode = code || 'SOPHIE25';
 87:       setDiscountRate(0.25);
 88:       setAppliedPromoName(activeCode);
 89:       setPromoCode(activeCode);
 90:       showToast(`Promo code applied: 25% VIP Discount (${activeCode})!`);
 91:     } else {
 92:       setDiscountRate(0.1);
 93:       setAppliedPromoName(code);
 94:       showToast(`Promo code applied: 10% Welcome Discount (${code})!`);
 95:     }
 96:   };
 97: 
 98:   // Order Submission
 99:   const handleSubmitOrder = (e) => {
100:     e.preventDefault();
101: 
102:     if (items.length === 0) {
103:       showToast('Your bag is empty! Add a bag before placing an order.');
104:       return;
105:     }
106: 
107:     const orderNumber = `#SPH-${Math.floor(10000 + Math.random() * 90000)}`;
108:     const finalTotalText = `£${finalTotal.toFixed(2)}`;
109: 
110:     const orderData = {
111:       orderNumber,
112:       customer: form,
113:       items,
114:       subtotal,
115:       discount: discountAmount,
116:       shipping: shippingCost,
117:       total: finalTotal
118:     };
119: 
120:     setConfirmedOrder({
121:       orderNumber,
122:       customerName: form.firstName || 'Sophie',
123:       totalText: finalTotalText
124:     });
125: 
126:     onOrderPlaced?.(orderData);
127:   };
128: 
129:   // Totals Calculations
130:   const totalItemCount = items.reduce((sum, item) => sum + item.qty, 0);
131:   const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
132:   const discountAmount = subtotal * discountRate;
133:   const shippingCost = items.length > 0 ? parseFloat(form.deliveryMethod) || 0 : 0;
134:   const finalTotal = Math.max(0, subtotal - discountAmount + shippingCost);
135: 
136:   return (
137:     <section className="checkout-wrapper" id="checkout-view" aria-label="Checkout">
138:       <div className="container" style={{ maxWidth: '1140px', margin: '0 auto', padding: '0 20px' }}>
139:         {/* Top Header Bar */}
140:         <div className="checkout-top-bar">
141:           <h1 className="checkout-giant-title">CHECKOUT</h1>
142:           <button
143:             type="button"
144:             className="back-to-shop-btn"
145:             id="back-to-shop-btn"
146:             onClick={onContinueShopping}
147:           >
148:             <i className="fa-solid fa-arrow-left" aria-hidden="true" /> Continue Shopping
149:           </button>
150:         </div>
151: 
152:         {/* Checkout Main Form Grid */}
153:         <form id="checkout-form" className="checkout-grid" onSubmit={handleSubmitOrder} noValidate>
154:           {/* LEFT COLUMN: Customer Information, Delivery, Payment */}
155:           <div className="checkout-left-col">
156:             {/* Block 1: Customer Information */}
157:             <div className="checkout-block">
158:               <div className="checkout-block-header">
159:                 <h2 className="checkout-section-heading">Information</h2>
160:                 <p className="checkout-login-prompt">
161:                   Already have an account?{' '}
162:                   <button type="button" id="checkout-login-btn" onClick={onLoginClick}>
163:                     Log in
164:                   </button>
165:                 </p>
166:               </div>
167: 
168:               <h3 className="checkout-subheading">Personal Information</h3>
169:               <div className="checkout-fields-grid">
170:                 <div className="line-input-wrap">
171:                   <input
172:                     type="text"
173:                     className="line-input"
174:                     id="chk-fname"
175:                     name="firstName"
176:                     placeholder="First name"
177:                     value={form.firstName}
178:                     onChange={handleInputChange}
179:                     required
180:                   />
181:                 </div>
182:                 <div className="line-input-wrap">
183:                   <input
184:                     type="text"
185:                     className="line-input"
186:                     id="chk-lname"
187:                     name="lastName"
188:                     placeholder="Last name"
189:                     value={form.lastName}
190:                     onChange={handleInputChange}
191:                     required
192:                   />
193:                 </div>
194:                 <div className="line-input-wrap">
195:                   <input
196:                     type="tel"
197:                     className="line-input"
198:                     id="chk-phone"
199:                     name="phone"
200:                     placeholder="Phone number"
201:                     value={form.phone}
202:                     onChange={handleInputChange}
203:                     required
204:                   />
205:                 </div>
206:                 <div className="line-input-wrap">
207:                   <input
208:                     type="email"
209:                     className="line-input"
210:                     id="chk-email"
211:                     name="email"
212:                     placeholder="Email"
213:                     value={form.email}
214:                     onChange={handleInputChange}
215:                     required
216:                   />
217:                 </div>
218:               </div>
219: 
220:               <h3 className="checkout-subheading">Shipping Information</h3>
221:               <div className="checkout-fields-grid" style={{ marginBottom: '14px' }}>
222:                 <div className="line-input-wrap">
223:                   <input
224:                     type="text"
225:                     className="line-input"
226:                     id="chk-country"
227:                     name="country"
228:                     placeholder="Country / Region"
229:                     value={form.country}
230:                     onChange={handleInputChange}
231:                     required
232:                   />
233:                 </div>
234:                 <div className="line-input-wrap">
235:                   <input
236:                     type="text"
237:                     className="line-input"
238:                     id="chk-city"
239:                     name="city"
240:                     placeholder="City"
241:                     value={form.city}
242:                     onChange={handleInputChange}
243:                     required
244:                   />
245:                 </div>
246:                 <div className="line-input-wrap">
247:                   <input
248:                     type="text"
249:                     className="line-input"
250:                     id="chk-address"
251:                     name="address"
252:                     placeholder="Address"
253:                     value={form.address}
254:                     onChange={handleInputChange}
255:                     required
256:                   />
257:                 </div>
258:                 <div className="line-input-wrap">
259:                   <input
260:                     type="text"
261:                     className="line-input"
262:                     id="chk-zip"
263:                     name="zip"
264:                     placeholder="Zip / Postal code"
265:                     value={form.zip}
266:                     onChange={handleInputChange}
267:                     required
268:                   />
269:                 </div>
270:               </div>
271: 
272:               <label className="checkout-checkbox-row">
273:                 <input
274:                   type="checkbox"
275:                   name="agreeTerms"
276:                   checked={form.agreeTerms}
277:                   onChange={handleInputChange}
278:                 />
279:                 <span>
280:                   I agree to <a href="#privacy" onClick={(e) => e.preventDefault()}>data processing</a>
281:                 </span>
282:               </label>
283:             </div>
284: 
285:             {/* Block 2: Delivery Options */}
286:             <div className="checkout-block">
287:               <div className="checkout-block-header">
288:                 <h2 className="checkout-section-heading">Delivery</h2>
289:               </div>
290: 
291:               <div className="radio-list">
292:                 {DELIVERY_METHODS.map((method) => {
293:                   const isChecked = form.deliveryMethod === method.id;
294:                   return (
295:                     <div key={method.id} className="radio-option-row">
296:                       <label className="radio-option-label">
297:                         <span className="radio-left">
298:                           <input
299:                             type="radio"
300:                             name="deliveryMethod"
301:                             value={method.id}
302:                             checked={isChecked}
303:                             onChange={handleInputChange}
304:                           />
305:                           <span>
306:                             <span className="radio-title">{method.title}</span>
307:                             <span className="radio-desc">{method.desc}</span>
308:                           </span>
309:                         </span>
310:                         <span className="radio-price">{method.priceLabel}</span>
311:                       </label>
312:                     </div>
313:                   );
314:                 })}
315:               </div>
316:             </div>
317: 
318:             {/* Block 3: Payment Options */}
319:             <div className="checkout-block" style={{ marginBottom: 0 }}>
320:               <div className="checkout-block-header">
321:                 <h2 className="checkout-section-heading">Payment</h2>
322:               </div>
323: 
324:               <div className="radio-list">
325:                 {/* Credit Card Option */}
326:                 <div className="radio-option-row">
327:                   <label className="radio-option-label">
328:                     <span className="radio-left">
329:                       <input
330:                         type="radio"
331:                         name="paymentMethod"
332:                         value="card"
333:                         checked={form.paymentMethod === 'card'}
334:                         onChange={handleInputChange}
335:                       />
336:                       <span className="radio-title">Credit card</span>
337:                     </span>
338:                     <span className="payment-brands">
339:                       <i className="fa-brands fa-cc-visa" style={{ color: '#1a1f71' }} />
340:                       <i className="fa-brands fa-cc-mastercard" style={{ color: '#eb001b' }} />
341:                     </span>
342:                   </label>
343: 
344:                   {/* Collapsible Card Fields */}
345:                   {form.paymentMethod === 'card' && (
346:                     <div className="cc-fields-panel" id="cc-fields-panel">
347:                       <div className="checkout-fields-grid" style={{ marginBottom: '10px' }}>
348:                         <div className="line-input-wrap">
349:                           <input
350:                             type="text"
351:                             className="line-input"
352:                             name="cardNumber"
353:                             placeholder="Card number"
354:                             value={form.cardNumber}
355:                             onChange={handleInputChange}
356:                           />
357:                         </div>
358:                         <div className="line-input-wrap">
359:                           <input
360:                             type="text"
361:                             className="line-input"
362:                             name="cardHolder"
363:                             placeholder="Cardholder name"
364:                             value={form.cardHolder}
365:                             onChange={handleInputChange}
366:                           />
367:                         </div>
368:                         <div className="line-input-wrap">
369:                           <input
370:                             type="text"
371:                             className="line-input"
372:                             name="cardExp"
373:                             placeholder="Expiration date (MM/YY)"
374:                             value={form.cardExp}
375:                             onChange={handleInputChange}
376:                           />
377:                         </div>
378:                         <div className="line-input-wrap">
379:                           <input
380:                             type="password"
381:                             className="line-input"
382:                             name="cardCvv"
383:                             placeholder="CVV"
384:                             maxLength={4}
385:                             value={form.cardCvv}
386:                             onChange={handleInputChange}
387:                           />
388:                         </div>
389:                       </div>
390:                     </div>
391:                   )}
392:                 </div>
393: 
394:                 {/* PayPal Option */}
395:                 <div className="radio-option-row">
396:                   <label className="radio-option-label">
397:                     <span className="radio-left">
398:                       <input
399:                         type="radio"
400:                         name="paymentMethod"
401:                         value="paypal"
402:                         checked={form.paymentMethod === 'paypal'}
403:                         onChange={handleInputChange}
404:                       />
405:                       <span className="radio-title">PayPal</span>
406:                     </span>
407:                     <span className="payment-brands">
408:                       <i className="fa-brands fa-cc-paypal" style={{ color: '#003087' }} />
409:                     </span>
410:                   </label>
411:                 </div>
412: 
413:                 {/* Apple Pay Option */}
414:                 <div className="radio-option-row">
415:                   <label className="radio-option-label">
416:                     <span className="radio-left">
417:                       <input
418:                         type="radio"
419:                         name="paymentMethod"
420:                         value="applepay"
421:                         checked={form.paymentMethod === 'applepay'}
422:                         onChange={handleInputChange}
423:                       />
424:                       <span className="radio-title">Apple Pay</span>
425:                     </span>
426:                     <span className="payment-brands">
427:                       <i className="fa-brands fa-apple-pay" style={{ color: '#111111', fontSize: '22px' }} />
428:                     </span>
429:                   </label>
430:                 </div>
431:               </div>
432: 
433:               <label className="checkout-checkbox-row" style={{ marginTop: '16px' }}>
434:                 <input
435:                   type="checkbox"
436:                   name="agreeTerms"
437:                   checked={form.agreeTerms}
438:                   onChange={handleInputChange}
439:                 />
440:                 <span>
441:                   I agree to <a href="#terms" onClick={(e) => e.preventDefault()}>data processing</a>
442:                 </span>
443:               </label>
444: 
445:               <button type="submit" className="btn-place-order" id="pay-place-order-btn">
446:                 PAY AND PLACE ORDER
447:               </button>
448:             </div>
449:           </div>
450: 
451:           {/* RIGHT COLUMN: Shopping Bag Summary */}
452:           <div className="bag-summary-panel">
453:             <h2 className="checkout-section-heading" id="shopping-bag-heading">
454:               Shopping Bag ({totalItemCount})
455:             </h2>
456: 
457:             <div className="bag-items-list" id="bag-items-container">
458:               {items.length === 0 ? (
459:                 <p style={{ padding: '24px 0', color: '#64748b', fontSize: '13px' }}>
460:                   Your shopping bag is currently empty. Add bags from the collection!
461:                 </p>
462:               ) : (
463:                 items.map((item) => (
464:                   <div key={item.id} className="bag-item-row" data-bag-id={item.id}>
465:                     <div className="bag-item-thumb">
466:                       <img src={item.img} className={item.tint || ''} alt={item.name} />
467:                     </div>
468: 
469:                     <div className="bag-item-info">
470:                       <h4 className="bag-item-title">{item.name}</h4>
471:                       <div className="bag-item-meta">
472:                         <span className="meta-label">Size:</span>
473:                         <span className="meta-val">{item.size}</span>
474:                         <span className="meta-label">Color:</span>
475:                         <span className="meta-val">{item.color}</span>
476:                         <span className="meta-label">Quantity:</span>
477:                         <span className="meta-val qty-stepper">
478:                           <button
479:                             type="button"
480:                             className="qty-btn"
481:                             onClick={() => handleUpdateQty(item.id, -1)}
482:                             aria-label="Decrease quantity"
483:                           >
484:                             -
485:                           </button>
486:                           <span>{item.qty}</span>
487:                           <button
488:                             type="button"
489:                             className="qty-btn"
490:                             onClick={() => handleUpdateQty(item.id, 1)}
491:                             aria-label="Increase quantity"
492:                           >
493:                             +
494:                           </button>
495:                         </span>
496:                       </div>
497:                     </div>
498: 
499:                     <div className="bag-item-right">
500:                       <span className="bag-item-price">
501:                         £{(item.price * item.qty).toFixed(2)}
502:                       </span>
503:                       <button
504:                         type="button"
505:                         className="bag-remove-btn"
506:                         onClick={() => handleRemoveItem(item.id)}
507:                         title="Remove item"
508:                       >
509:                         <i className="fa-regular fa-trash-can" aria-hidden="true" /> Remove
510:                       </button>
511:                     </div>
512:                   </div>
513:                 ))
514:               )}
515:             </div>
516: 
517:             {/* Promocode Input Row */}
518:             <div className="promo-row">
519:               <div className="line-input-wrap">
520:                 <input
521:                   type="text"
522:                   className="line-input"
523:                   id="promo-code-input"
524:                   placeholder="Promocode (Try SOPHIE25)"
525:                   value={promoCode}
526:                   onChange={(e) => setPromoCode(e.target.value)}
527:                   onKeyDown={(e) => {
528:                     if (e.key === 'Enter') {
529:                       e.preventDefault();
530:                       handleApplyPromo();
531:                     }
532:                   }}
533:                 />
534:               </div>
535:               <button
536:                 type="button"
537:                 className="btn-apply-promo"
538:                 id="apply-promo-btn"
539:                 onClick={handleApplyPromo}
540:               >
541:                 APPLY
542:               </button>
543:             </div>
544: 
545:             {/* Summary Totals */}
546:             <div className="bag-totals-row">
547:               <span>Shipping</span>
548:               <strong id="summary-shipping">
549:                 {shippingCost === 0 ? 'Free' : `£${shippingCost.toFixed(2)}`}
550:               </strong>
551:             </div>
552: 
553:             <div className="bag-totals-row">
554:               <span>Discount</span>
555:               <strong id="summary-discount">
556:                 {discountAmount > 0
557:                   ? `-£${discountAmount.toFixed(2)} (${Math.round(discountRate * 100)}%)`
558:                   : '£0.00'}
559:               </strong>
560:             </div>
561: 
562:             <div className="bag-grand-total">
563:               <span>Total:</span>
564:               <span className="total-amount" id="summary-total">
565:                 £{finalTotal.toFixed(2)}
566:               </span>
567:             </div>
568:           </div>
569:         </form>
570:       </div>
571: 
572:       {/* Order Confirmation Modal */}
573:       {confirmedOrder && (
574:         <div className="order-modal-backdrop open" id="order-modal">
575:           <div className="order-modal-card">
576:             <div className="order-modal-icon">
577:               <i className="fa-solid fa-check" aria-hidden="true" />
578:             </div>
579:             <h3 className="order-modal-title">ORDER CONFIRMED!</h3>
580:             <p className="order-modal-desc" id="order-modal-desc">
581:               Thank you, <strong>{confirmedOrder.customerName}</strong>! Your order of{' '}
582:               <strong>{confirmedOrder.totalText}</strong> (
583:               <strong>{confirmedOrder.orderNumber}</strong>) has been confirmed and is being
584:               prepared for dispatch.
585:             </p>
586:             <button
587:               type="button"
588:               className="btn-place-order"
589:               style={{ marginTop: 0 }}
590:               onClick={() => {
591:                 setConfirmedOrder(null);
592:                 onContinueShopping?.();
593:               }}
594:             >
595:               BACK TO STORE
596:             </button>
597:           </div>
598:         </div>
599:       )}
600: 
601:       {/* Toast Notification */}
602:       {toastMessage && (
603:         <div className="toast-notice show" id="toast-notice" role="status" aria-live="polite">
604:           <i className="fa-solid fa-circle-check" aria-hidden="true" />
605:           <span id="toast-text">{toastMessage}</span>
606:         </div>
607:       )}
608:     </section>
609:   );
610: }
