612: export default SophieCheckoutPage;  1: 'use client';
  2: 
  3: import React, { useState, useEffect, useRef } from 'react';
  4: import { MEGA_DEPARTMENTS } from './sophieMockData';
  5: 
  6: /**
  7:  * SophieMegaDropdown Component
  8:  * 
  9:  * Luxury department store mega menu for Shop & Categories, inspired by Longacres.
 10:  * Features 6 department tabs, 3 columns of categorized collections, a highlighted
 11:  * spotlight deal with quick "Add to cart", and a customer guarantee footer bar.
 12:  * 
 13:  * @param {Object} props
 14:  * @param {boolean} [props.isOpen] Controlled open state
 15:  * @param {Function} [props.onClose] Callback to close mega menu
 16:  * @param {string} [props.defaultDept='handbags'] Initial active department
 17:  * @param {Function} [props.onSelectCategory] Callback when a category link is clicked: (categoryName) => void
 18:  * @param {Function} [props.onAddToCart] Callback when spotlight item is added to cart: (product) => void
 19:  * @param {Function} [props.onGoToCheckout] Callback to navigate to checkout
 20:  * @param {Object} [props.departments] Departments data override (defaults to MEGA_DEPARTMENTS)
 21:  * @param {string} [props.className] Additional CSS class
 22:  */
 23: export function SophieMegaDropdown({
 24:   isOpen = false,
 25:   onClose,
 26:   defaultDept = 'handbags',
 27:   onSelectCategory,
 28:   onAddToCart,
 29:   onGoToCheckout,
 30:   departments = MEGA_DEPARTMENTS,
 31:   className = ''
 32: }) {
 33:   const [activeDeptKey, setActiveDeptKey] = useState(defaultDept);
 34:   const menuRef = useRef(null);
 35: 
 36:   // Sync active dept when defaultDept changes
 37:   useEffect(() => {
 38:     if (defaultDept && departments[defaultDept]) {
 39:       setActiveDeptKey(defaultDept);
 40:     }
 41:   }, [defaultDept, departments]);
 42: 
 43:   // Handle ESC key to close
 44:   useEffect(() => {
 45:     function handleKeyDown(e) {
 46:       if (e.key === 'Escape' && isOpen) {
 47:         onClose?.();
 48:       }
 49:     }
 50:     window.addEventListener('keydown', handleKeyDown);
 51:     return () => window.removeEventListener('keydown', handleKeyDown);
 52:   }, [isOpen, onClose]);
 53: 
 54:   const activeDept = departments[activeDeptKey] || departments.handbags;
 55: 
 56:   const handleTabChange = (deptKey) => {
 57:     setActiveDeptKey(deptKey);
 58:   };
 59: 
 60:   const handleCategoryClick = (e, catName) => {
 61:     e.preventDefault();
 62:     onClose?.();
 63:     if (onSelectCategory) {
 64:       onSelectCategory(catName);
 65:     }
 66:   };
 67: 
 68:   const handleAddToCart = (e) => {
 69:     e.stopPropagation();
 70:     if (onAddToCart && activeDept.spotlight) {
 71:       onAddToCart({
 72:         id: `spotlight-${activeDeptKey}`,
 73:         name: activeDept.spotlight.title,
 74:         price: activeDept.spotlight.numericPrice,
 75:         img: activeDept.spotlight.img,
 76:         tint: activeDept.spotlight.tint,
 77:         size: 'M',
 78:         color: 'Signature Edition',
 79:         qty: 1
 80:       });
 81:     }
 82:   };
 83: 
 84:   const handleProceedCheckout = (e) => {
 85:     e.preventDefault();
 86:     onClose?.();
 87:     if (onGoToCheckout) {
 88:       onGoToCheckout();
 89:     }
 90:   };
 91: 
 92:   // Helper to render link columns
 93:   const renderColumn = (colGroups = [], colIndex) => {
 94:     return (
 95:       <div key={`col-${colIndex}`} className="mega-col" id={`mega-col-${colIndex}`}>
 96:         {colGroups.map((group, gIdx) => (
 97:           <div key={`group-${gIdx}`} className="mega-group">
 98:             <h4 className="mega-group-title">{group.title}</h4>
 99:             <ul className="mega-group-list">
100:               {group.links.map((link, lIdx) => {
101:                 const isObj = typeof link === 'object' && link !== null;
102:                 const label = isObj ? link.label : link;
103:                 const tag = isObj ? link.tag : null;
104:                 const isHot = isObj ? link.hot : false;
105: 
106:                 return (
107:                   <li key={`link-${lIdx}`}>
108:                     <a
109:                       href="#catalog"
110:                       className="mega-link"
111:                       onClick={(e) => handleCategoryClick(e, label)}
112:                       data-category={label}
113:                     >
114:                       {label}
115:                       {tag && (
116:                         <span className={`mega-link-tag ${isHot ? 'hot' : ''}`}>
117:                           {tag}
118:                         </span>
119:                       )}
120:                     </a>
121:                   </li>
122:                 );
123:               })}
124:             </ul>
125:           </div>
126:         ))}
127:       </div>
128:     );
129:   };
130: 
131:   return (
132:     <div
133:       ref={menuRef}
134:       className={`mega-dropdown-wrapper ${isOpen ? 'is-open' : ''} ${className}`}
135:       id="mega-dropdown"
136:       role="region"
137:       aria-label="Bag Store Mega Menu"
138:     >
139:       <div className="mega-dropdown-card">
140:         {/* Department Tabs Bar */}
141:         <div className="mega-dept-bar">
142:           <div className="mega-dept-tabs" role="tablist">
143:             {Object.keys(departments).map((deptKey) => {
144:               const dept = departments[deptKey];
145:               const isActive = activeDeptKey === deptKey;
146:               const isOffer = dept.isOffer || deptKey === 'offers';
147: 
148:               return (
149:                 <button
150:                   key={deptKey}
151:                   type="button"
152:                   role="tab"
153:                   aria-selected={isActive}
154:                   className={`mega-dept-tab ${isActive ? 'active' : ''} ${
155:                     isOffer ? 'offers-tab' : ''
156:                   }`}
157:                   onClick={() => handleTabChange(deptKey)}
158:                   onMouseEnter={() => handleTabChange(deptKey)}
159:                   data-dept-tab={deptKey}
160:                 >
161:                   {dept.name}
162:                 </button>
163:               );
164:             })}
165:           </div>
166: 
167:           <button
168:             type="button"
169:             className="mega-close-btn"
170:             id="mega-close-btn"
171:             onClick={onClose}
172:             aria-label="Close mega menu"
173:             title="Close menu"
174:           >
175:             <i className="fa-solid fa-xmark" aria-hidden="true" />
176:           </button>
177:         </div>
178: 
179:         {/* Mega Menu Body: 3 Columns of Categories + 1 Spotlight Offer Card */}
180:         <div className="mega-body" id="mega-body-content">
181:           {renderColumn(activeDept.col1, 1)}
182:           {renderColumn(activeDept.col2, 2)}
183:           {renderColumn(activeDept.col3, 3)}
184: 
185:           {/* Column 4: Spotlight Special Offer Product */}
186:           {activeDept.spotlight && (
187:             <div className="mega-spotlight" id="mega-spotlight-card">
188:               <div className="mega-spotlight-img-wrap">
189:                 <span className="mega-special-badge" id="spotlight-badge">
190:                   {activeDept.spotlight.badge || 'SPECIAL OFFER'}
191:                 </span>
192:                 <img
193:                   id="spotlight-img"
194:                   src={activeDept.spotlight.img}
195:                   className={activeDept.spotlight.tint || ''}
196:                   alt={activeDept.spotlight.title}
197:                 />
198:               </div>
199: 
200:               <h5 className="mega-spotlight-title" id="spotlight-title">
201:                 {activeDept.spotlight.title}
202:               </h5>
203: 
204:               <div className="mega-spotlight-price">
205:                 <span id="spotlight-price">{activeDept.spotlight.price}</span>
206:                 {activeDept.spotlight.oldPrice && (
207:                   <span className="old-price" id="spotlight-old-price">
208:                     {activeDept.spotlight.oldPrice}
209:                   </span>
210:                 )}
211:               </div>
212: 
213:               <button
214:                 type="button"
215:                 className="mega-add-cart-btn"
216:                 id="mega-add-cart-btn"
217:                 onClick={handleAddToCart}
218:                 data-product={activeDept.spotlight.title}
219:                 data-price={activeDept.spotlight.numericPrice}
220:               >
221:                 <i className="fa-solid fa-cart-shopping" aria-hidden="true" /> Add to cart
222:               </button>
223:             </div>
224:           )}
225:         </div>
226: 
227:         {/* Mega Footer Guarantee Bar */}
228:         <div className="mega-footer">
229:           <div className="mega-footer-perks">
230:             <span>
231:               <i className="fa-solid fa-truck-fast" aria-hidden="true" /> Free UK Delivery over £50
232:             </span>
233:             <span>
234:               <i className="fa-solid fa-shield-heart" aria-hidden="true" /> 2-Year Leather Warranty
235:             </span>
236:             <span>
237:               <i className="fa-solid fa-rotate-left" aria-hidden="true" /> 30-Day Easy Returns
238:             </span>
239:           </div>
240: 
241:           <button
242:             type="button"
243:             className="mega-footer-cta"
244:             id="mega-goto-checkout"
245:             onClick={handleProceedCheckout}
246:           >
247:             Proceed to Checkout <i className="fa-solid fa-arrow-right" aria-hidden="true" />
248:           </button>
249:         </div>
250:       </div>
251:     </div>
252:   );
253: }
