  6: /**
  7:  * SophieProfileDropdown Component
  8:  * 
  9:  * Replaces the header settings icon with a luxury avatar and dropdown card
 10:  * featuring a 25% off promotional corner ribbon, subscription highlight, and account links.
 11:  * 
 12:  * @param {Object} props
 13:  * @param {Object} [props.user] User data override (defaults to INITIAL_PROFILE_USER)
 14:  * @param {Function} [props.onSelectAction] Callback when an item is clicked: (actionId) => void
 15:  * @param {Function} [props.onApplyPromo] Callback when 25% off ribbon is clicked: (promoCode) => void
 16:  * @param {string} [props.className] Additional CSS class
 17:  */
 18: export function SophieProfileDropdown({
 19:   user = INITIAL_PROFILE_USER,
 20:   onSelectAction,
 21:   onApplyPromo,
 22:   className = ''
 23: }) {
 24:   const [isOpen, setIsOpen] = useState(false);
 25:   const containerRef = useRef(null);
 26: 
 27:   // Close when clicking outside
 28:   useEffect(() => {
 29:     function handleClickOutside(event) {
 30:       if (containerRef.current && !containerRef.current.contains(event.target)) {
 31:         setIsOpen(false);
 32:       }
 33:     }
 34: 
 35:     function handleKeyDown(event) {
 36:       if (event.key === 'Escape') {
 37:         setIsOpen(false);
 38:       }
 39:     }
 40: 
 41:     if (isOpen) {
 42:       document.addEventListener('mousedown', handleClickOutside);
 43:       document.addEventListener('keydown', handleKeyDown);
 44:     }
 45:     return () => {
 46:       document.removeEventListener('mousedown', handleClickOutside);
 47:       document.removeEventListener('keydown', handleKeyDown);
 48:     };
 49:   }, [isOpen]);
 50: 
 51:   const handleToggle = (e) => {
 52:     e.stopPropagation();
 53:     setIsOpen((prev) => !prev);
 54:   };
 55: 
 56:   const handleRibbonClick = (e) => {
 57:     e.stopPropagation();
 58:     setIsOpen(false);
 59:     if (onApplyPromo) {
 60:       onApplyPromo(user.promoCode || 'SOPHIE25');
 61:     } else if (onSelectAction) {
 62:       onSelectAction('ribbon');
 63:     }
 64:   };
 65: 
 66:   const handleItemClick = (item) => {
 67:     setIsOpen(false);
 68:     if (onSelectAction) {
 69:       onSelectAction(item.id);
 70:     }
 71:   };
 72: 
 73:   return (
 74:     <div
 75:       ref={containerRef}
 76:       className={`profile-menu-wrap ${isOpen ? 'is-open' : ''} ${className}`}
 77:       id="profile-menu-wrap"
 78:     >
 79:       {/* Avatar Button Trigger */}
 80:       <button
 81:         type="button"
 82:         className="profile-avatar-btn"
 83:         id="profile-trigger-btn"
 84:         onClick={handleToggle}
 85:         aria-label="User Profile Menu"
 86:         aria-expanded={isOpen}
 87:         title={`${user.name} (${user.role})`}
 88:       >
 89:         <span className="profile-avatar-inner">
 90:           {user.avatar ? (
 91:             <img src={user.avatar} alt={user.name} />
 92:           ) : (
 93:             <span className="text-white text-xs font-semibold">
 94:               {user.name.charAt(0)}
 95:             </span>
 96:           )}
 97:         </span>
 98:       </button>
 99: 
100:       {/* Floating Profile Card */}
101:       <div
102:         className="profile-dropdown-card"
103:         id="profile-dropdown"
104:         role="menu"
105:         aria-label="Profile Menu"
106:       >
107:         {/* Diagonal 25% Off Ribbon */}
108:         {user.ribbonText && (
109:           <div className="profile-ribbon-wrap">
110:             <button
111:               type="button"
112:               className="profile-ribbon"
113:               id="profile-ribbon-btn"
114:               onClick={handleRibbonClick}
115:               title={`Click to apply ${user.ribbonText} promo code!`}
116:             >
117:               {user.ribbonText}
118:             </button>
119:           </div>
120:         )}
121: 
122:         {/* Menu Items List */}
123:         <div className="profile-menu-list">
124:           {user.menuItems?.map((item) => {
125:             if (item.type === 'divider') {
126:               return <div key={item.id} className="profile-menu-divider" />;
127:             }
128: 
129:             const itemClasses = [
130:               'profile-menu-item',
131:               item.highlighted ? 'highlighted' : '',
132:               item.isSignOut ? 'sign-out' : ''
133:             ]
134:               .filter(Boolean)
135:               .join(' ');
136: 
137:             return (
138:               <button
139:                 key={item.id}
140:                 type="button"
141:                 className={itemClasses}
142:                 onClick={() => handleItemClick(item)}
143:                 role="menuitem"
144:               >
145:                 <i className={item.icon} aria-hidden="true" />
146:                 <span>{item.label}</span>
147:               </button>
148:             );
149:           })}
150:         </div>
151:       </div>
152:     </div>
153:   );
154: }
