156: export default SophieProfileDropdown; 1: import type { StoreCategory, StoreProduct, StoreProductCard, StoreCatalogFilters } from '@alfarid/api-client';
 2: import { formatStorePrice } from '@alfarid/utils';
 3: 
 4: export const pick = (en?: string | null, ar?: string | null) => en?.trim() || ar?.trim() || '';
 5: const toNum = (v: unknown) => (v === null || v === undefined || v === '' ? null : Number.isFinite(Number(v)) ? Number(v) : null);
 6: 
 7: export interface CatalogCardVM {
 8:   id: number; slug: string; name: string; categoryLabel: string;
 9:   price: number | null; priceLabel: string; oldPriceLabel?: string;
10:   badge?: string; badgeType: 'badge' | 'badge sale';
11:   img: string | null; inStock: boolean; defaultVariantId?: number;
12:   colors: Array<{ label: string; hex: string | null }>;
13: }
14: 
15: export function toCardVM(c: StoreProductCard): CatalogCardVM {
16:   const price = toNum(c.price); const old = toNum(c.old_price);
17:   let badge: string | undefined; let badgeType: CatalogCardVM['badgeType'] = 'badge';
18:   if (!c.in_stock) { badge = 'SOLD OUT'; badgeType = 'badge sale'; }
19:   else if (c.discount_percentage) { badge = `-${Math.round(c.discount_percentage)}%`; badgeType = 'badge sale'; }
20:   else if (c.badge_en || c.badge_ar) { badge = pick(c.badge_en, c.badge_ar).toUpperCase(); }
21:   else if (c.is_new) { badge = 'NEW'; }
22:   return {
23:     id: c.id, slug: c.slug, name: pick(c.name_en, c.name_ar),
24:     categoryLabel: pick(c.category?.name_en, c.category?.name_ar),
25:     price, priceLabel: price !== null ? formatStorePrice(price) : 'Unavailable',
26:     oldPriceLabel: old !== null && price !== null && old > price ? formatStorePrice(old) : undefined,
27:     badge, badgeType, img: c.image, inStock: c.in_stock,
28:     defaultVariantId: c.default_variant_id ?? undefined,
29:     colors: (c.colors ?? []).map((x) => ({ label: pick(x.name_en, x.name_ar), hex: x.hex })),
30:   };
31: }
32: 
33: export interface VariantVM {
34:   id: number; sku: string; colorKey: string; colorLabel: string; hex: string | null;
35:   sizeLabel: string | null; price: number | null; oldPrice: number | null; inStock: boolean;
36:   images: Array<{ url: string; thumb: string | null }>;
37:   maxQty: number;
38: }
39: export interface ProductDetailVM {
40:   id: number; slug: string; name: string; categoryLabel: string; categorySlug: string | null;
41:   desc: string; material: string; warrantyMonths: number | null;
42:   images: Array<{ url: string; thumb: string | null }>;
43:   colors: Array<{ key: string; label: string; hex: string | null }>;
44:   sizes: string[]; variants: VariantVM[]; fallbackPrice: number | null;
45: }
46: 
47: const sizeOf = (size: string | null, cap: string | null) =>
48:   size && cap ? `${size} (${cap})` : size || cap || null;
49: 
50: export function toDetailVM(p: StoreProduct): ProductDetailVM {
51:   const variants: VariantVM[] = p.variants.map((v) => ({
52:     id: v.id, sku: v.sku,
53:     colorKey: (pick(v.color_name_en, v.color_name_ar) || v.color_hex || 'default').toLowerCase(),
54:     colorLabel: pick(v.color_name_en, v.color_name_ar) || 'Default', hex: v.color_hex,
55:     sizeLabel: sizeOf(v.size, v.capacity), price: toNum(v.price), oldPrice: toNum(v.old_price),
56:     inStock: v.in_stock, maxQty: Math.max(0, Math.floor(v.max_qty ?? 0)), images: v.images.map((i) => ({ url: i.url, thumb: i.thumb })),
57:   }));
58:   const colors = [...new Map(variants.map((v) => [v.colorKey, { key: v.colorKey, label: v.colorLabel, hex: v.hex }])).values()];
59:   const sizes = [...new Set(variants.map((v) => v.sizeLabel).filter((s): s is string => !!s))];
60:   const images = p.images.length ? p.images : p.image ? [{ id: 0, url: p.image, thumb: p.image }] : [];
61:   return {
62:     id: p.id, slug: p.slug, name: pick(p.name_en, p.name_ar),
63:     categoryLabel: pick(p.category?.name_en, p.category?.name_ar), categorySlug: p.category?.slug ?? null,
64:     desc: pick(p.description_en, p.description_ar), material: pick(p.material_en, p.material_ar),
65:     warrantyMonths: p.warranty_months,
66:     images: images.map((i) => ({ url: i.url, thumb: i.thumb })),
67:     colors, sizes, variants, fallbackPrice: toNum(p.price),
68:   };
69: }
