71: /** اختيار الـ variant: تطابق اللون والمقاس، وإلا أول variant متاح من نفس اللون، وإلا أول variant */
72: export function resolveVariant(vm: ProductDetailVM, colorKey: string | null, size: string | null): VariantVM | null {
73:   const sameColor = vm.variants.filter((v) => !colorKey || v.colorKey === colorKey);
74:   return sameColor.find((v) => (!size || v.sizeLabel === size))
75:       ?? sameColor.find((v) => v.inStock) ?? sameColor[0] ?? vm.variants[0] ?? null;
76: }
