78: export function priceRangeLabel(r: StoreCatalogFilters['price_ranges'][number]) {
79:   if (r.min === null && r.max !== null) return `Under ${formatStorePrice(Math.ceil(r.max))}`;
80:   if (r.max === null && r.min !== null) return `${formatStorePrice(Math.floor(r.min))} & Above`;
81:   return `${formatStorePrice(r.min ?? 0)} – ${formatStorePrice(r.max ?? 0)}`;
82: }
83: 
84: export function findCategory(tree: StoreCategory[] | undefined, slug: string | null): { node: StoreCategory; path: StoreCategory[] } | null {
85:   if (!tree || !slug) return null;
86:   const walk = (nodes: StoreCategory[], path: StoreCategory[]): ReturnType<typeof findCategory> => {
87:     for (const n of nodes) {
88:       if (n.slug === slug) return { node: n, path: [...path, n] };
89:       const r = walk(n.children ?? [], [...path, n]); if (r) return r;
90:     }
91:     return null;
92:   };
93:   return walk(tree, []);
