 4: /** Opaque per-session cache identity; contains no token and has no hash collisions. */
 5: export function viewerKey(token: string | null): string {
 6:   if (token !== previousToken) {
 7:     previousToken = token;
 8:     previousKey = token ? `viewer:${crypto.randomUUID()}` : 'guest';
 9:   }
10:   return previousKey;
