 367: export function SophieProfileDropdown({
 368:   user = SOPHIE_MOCK_DATA.profile,
 369:   onSelectAction,
 370:   onApplyPromo,
 371:   className = ''
 372: }) {
 373:   const [isOpen, setIsOpen] = useState(false);
 374:   const containerRef = useRef(null);
 375: 
 376:   useEffect(() => {
 377:     function handleClickOutside(event) {
 378:       if (containerRef.current && !containerRef.current.contains(event.target)) {
 379:         setIsOpen(false);
 380:       }
 381:     }
 382:     function handleKeyDown(event) {
 383:       if (event.key === 'Escape') setIsOpen(false);
 384:     }
 385:     if (isOpen) {
 386:       document.addEventListener('mousedown', handleClickOutside);
 387:       document.addEventListener('keydown', handleKeyDown);
 388:     }
 389:     return () => {
 390:       document.removeEventListener('mousedown', handleClickOutside);
 391:       document.removeEventListener('keydown', handleKeyDown);
 392:     };
 393:   }, [isOpen]);
 394: 
 395:   const handleToggle = (e) => {
 396:     e.stopPropagation();
 397:     setIsOpen((prev) => !prev);
 398:   };
 399: 
 400:   const handleRibbonClick = (e) => {
 401:     e.stopPropagation();
 402:     setIsOpen(false);
 403:     onApplyPromo?.(user.promoCode || 'SOPHIE25');
 404:   };
 405: 
 406:   const handleItemClick = (item) => {
 407:     setIsOpen(false);
 408:     onSelectAction?.(item.id);
 409:   };
 410: 
 411:   return (
 412:     <div
 413:       ref={containerRef}
 414:       className={`profile-menu-wrap ${isOpen ? 'is-open' : ''} ${className}`}
 415:       id="profile-menu-wrap"
 416:     >
 417:       <button
 418:         type="button"
 419:         className="profile-avatar-btn"
 420:         onClick={handleToggle}
 421:         aria-label="User Profile Menu"
 422:         aria-expanded={isOpen}
 423:         title={`${user.name} (${user.role})`}
 424:       >
 425:         <span className="profile-avatar-inner">
 426:           {user.avatar ? (
 427:             <img src={user.avatar} alt={user.name} />
 428:           ) : (
 429:             <span className="text-white text-xs font-semibold">{user.name.charAt(0)}</span>
 430:           )}
 431:         </span>
 432:       </button>
 433: 
 434:       <div className="profile-dropdown-card" role="menu" aria-label="Profile Menu">
 435:         {user.ribbonText && (
 436:           <div className="profile-ribbon-wrap">
 437:             <button
 438:               type="button"
 439:               className="profile-ribbon"
 440:               onClick={handleRibbonClick}
 441:               title={`Click to apply ${user.ribbonText} promo!`}
 442:             >
 443:               {user.ribbonText}
 444:             </button>
 445:           </div>
 446:         )}
 447: 
 448:         <div className="profile-menu-list">
 449:           {user.menuItems?.map((item) => {
 450:             if (item.type === 'divider') {
 451:               return <div key={item.id} className="profile-menu-divider" />;
 452:             }
 453:             const itemClass = `profile-menu-item ${item.highlighted ? 'highlighted' : ''} ${
 454:               item.isSignOut ? 'sign-out' : ''
 455:             }`;
 456:             return (
 457:               <button
 458:                 key={item.id}
 459:                 type="button"
 460:                 className={itemClass}
 461:                 onClick={() => handleItemClick(item)}
 462:                 role="menuitem"
 463:               >
 464:                 <i className={item.icon} aria-hidden="true" />
 465:                 <span>{item.label}</span>
 466:               </button>
 467:             );
 468:           })}
 469:         </div>
 470:       </div>
 471:     </div>
 472:   );
 473: }
