 478: 
 479: export function SophieMegaDropdown({
 480:   isOpen = false,
 481:   onClose,
 482:   defaultDept = 'handbags',
 483:   onSelectCategory,
 484:   onAddToCart,
 485:   onGoToCheckout,
 486:   departments = SOPHIE_MOCK_DATA.departments,
 487:   className = ''
 488: }) {
 489:   const [activeDeptKey, setActiveDeptKey] = useState(defaultDept);
 490:   const menuRef = useRef(null);
 491: 
 492:   useEffect(() => {
 493:     if (defaultDept && departments[defaultDept]) {
 494:       setActiveDeptKey(defaultDept);
 495:     }
 496:   }, [defaultDept, departments]);
 497: 
 498:   useEffect(() => {
 499:     function handleKeyDown(e) {
 500:       if (e.key === 'Escape' && isOpen) onClose?.();
 501:     }
 502:     window.addEventListener('keydown', handleKeyDown);
 503:     return () => window.removeEventListener('keydown', handleKeyDown);
 504:   }, [isOpen, onClose]);
 505: 
 506:   const activeDept = departments[activeDeptKey] || departments.handbags;
 507: 
 508:   const renderCol = (colGroups, colIndex) => (
 509:     <div key={`col-${colIndex}`} className="mega-col">
 510:       {colGroups?.map((group, gIdx) => (
 511:         <div key={`group-${gIdx}`} className="mega-group">
 512:           <h4 className="mega-group-title">{group.title}</h4>
 513:           <ul className="mega-group-list">
 514:             {group.links?.map((link, lIdx) => {
 515:               const isObj = typeof link === 'object' && link !== null;
 516:               const label = isObj ? link.label : link;
 517:               const tag = isObj ? link.tag : null;
 518:               const isHot = isObj ? link.hot : false;
 519:               return (
 520:                 <li key={`link-${lIdx}`}>
 521:                   <a
 522:                     href="#catalog"
 523:                     className="mega-link"
 524:                     onClick={(e) => {
 525:                       e.preventDefault();
 526:                       onClose?.();
 527:                       onSelectCategory?.(label);
 528:                     }}
 529:                   >
 530:                     {label}
 531:                     {tag && <span className={`mega-link-tag ${isHot ? 'hot' : ''}`}>{tag}</span>}
 532:                   </a>
 533:                 </li>
 534:               );
 535:             })}
 536:           </ul>
 537:         </div>
 538:       ))}
 539:     </div>
 540:   );
 541: 
 542:   return (
 543:     <div
 544:       ref={menuRef}
 545:       className={`mega-dropdown-wrapper ${isOpen ? 'is-open' : ''} ${className}`}
 546:       role="region"
 547:       aria-label="Bag Store Mega Menu"
 548:     >
 549:       <div className="mega-dropdown-card">
 550:         {/* Department Tabs Bar */}
 551:         <div className="mega-dept-bar">
 552:           <div className="mega-dept-tabs" role="tablist">
 553:             {Object.keys(departments).map((deptKey) => {
 554:               const dept = departments[deptKey];
 555:               const isActive = activeDeptKey === deptKey;
 556:               const isOffer = dept.isOffer || deptKey === 'offers';
 557:               return (
 558:                 <button
 559:                   key={deptKey}
 560:                   type="button"
 561:                   role="tab"
 562:                   aria-selected={isActive}
 563:                   className={`mega-dept-tab ${isActive ? 'active' : ''} ${isOffer ? 'offers-tab' : ''}`}
 564:                   onClick={() => setActiveDeptKey(deptKey)}
 565:                   onMouseEnter={() => setActiveDeptKey(deptKey)}
 566:                 >
 567:                   {dept.name}
 568:                 </button>
 569:               );
 570:             })}
 571:           </div>
 572: 
 573:           <button
 574:             type="button"
 575:             className="mega-close-btn"
 576:             onClick={onClose}
 577:             aria-label="Close menu"
 578:           >
 579:             <i className="fa-solid fa-xmark" aria-hidden="true" />
 580:           </button>
 581:         </div>
 582: 
 583:         {/* Mega Menu Body */}
 584:         <div className="mega-body">
 585:           {renderCol(activeDept.col1, 1)}
 586:           {renderCol(activeDept.col2, 2)}
 587:           {renderCol(activeDept.col3, 3)}
 588: 
 589:           {/* Spotlight Offer Card */}
 590:           {activeDept.spotlight && (
 591:             <div className="mega-spotlight">
 592:               <div className="mega-spotlight-img-wrap">
 593:                 <span className="mega-special-badge">{activeDept.spotlight.badge}</span>
 594:                 <img
 595:                   src={activeDept.spotlight.img}
 596:                   className={activeDept.spotlight.tint || ''}
 597:                   alt={activeDept.spotlight.title}
 598:                 />
 599:               </div>
 600: 
 601:               <h5 className="mega-spotlight-title">{activeDept.spotlight.title}</h5>
 602: 
 603:               <div className="mega-spotlight-price">
 604:                 <span>{activeDept.spotlight.price}</span>
 605:                 {activeDept.spotlight.oldPrice && (
 606:                   <span className="old-price">{activeDept.spotlight.oldPrice}</span>
 607:                 )}
 608:               </div>
 609: 
 610:               <button
 611:                 type="button"
 612:                 className="mega-add-cart-btn"
 613:                 onClick={() => {
 614:                   onAddToCart?.({
 615:                     id: `spotlight-${activeDeptKey}`,
 616:                     name: activeDept.spotlight.title,
 617:                     price: activeDept.spotlight.numericPrice,
 618:                     img: activeDept.spotlight.img,
 619:                     tint: activeDept.spotlight.tint,
 620:                     size: 'M',
 621:                     color: 'Signature Edition',
 622:                     qty: 1
 623:                   });
 624:                 }}
 625:               >
 626:                 <i className="fa-solid fa-cart-shopping" aria-hidden="true" /> Add to cart
 627:               </button>
 628:             </div>
 629:           )}
 630:         </div>
 631: 
 632:         {/* Footer Perks & Proceed CTA */}
 633:         <div className="mega-footer">
 634:           <div className="mega-footer-perks">
 635:             <span><i className="fa-solid fa-truck-fast" aria-hidden="true" /> Free UK Delivery over £50</span>
 636:             <span><i className="fa-solid fa-shield-heart" aria-hidden="true" /> 2-Year Leather Warranty</span>
 637:             <span><i className="fa-solid fa-rotate-left" aria-hidden="true" /> 30-Day Easy Returns</span>
 638:           </div>
 639: 
 640:           <button
 641:             type="button"
 642:             className="mega-footer-cta"
 643:             onClick={(e) => {
 644:               e.preventDefault();
 645:               onClose?.();
 646:               onGoToCheckout?.();
 647:             }}
 648:           >
 649:             Proceed to Checkout <i className="fa-solid fa-arrow-right" aria-hidden="true" />
 650:           </button>
 651:         </div>
 652:       </div>
 653:     </div>
 654:   );
 655: }
