 659: // ==========================================================================
 660: 
 661: export function SophieCheckoutPage({
 662:   initialItems = SOPHIE_MOCK_DATA.initialBag,
 663:   initialForm = SOPHIE_MOCK_DATA.initialForm,
 664:   onContinueShopping,
 665:   onOrderPlaced,
 666:   onLoginClick
 667: }) {
 668:   const [items, setItems] = useState(initialItems);
 669:   const [form, setForm] = useState(initialForm);
 670:   const [promoCode, setPromoCode] = useState('');
 671:   const [discountRate, setDiscountRate] = useState(0);
 672:   const [toastMessage, setToastMessage] = useState(null);
 673:   const [confirmedOrder, setConfirmedOrder] = useState(null);
 674: 
 675:   const showToast = (msg) => {
 676:     setToastMessage(msg);
 677:     setTimeout(() => setToastMessage(null), 3200);
 678:   };
 679: 
 680:   const handleInputChange = (e) => {
 681:     const { name, value, type, checked } = e.target;
 682:     setForm((prev) => ({
 683:       ...prev,
 684:       [name]: type === 'checkbox' ? checked : value
 685:     }));
 686:   };
 687: 
 688:   const handleUpdateQty = (id, delta) => {
 689:     setItems((prev) =>
 690:       prev
 691:         .map((item) => {
 692:           if (item.id === id) {
 693:             const nextQty = item.qty + delta;
 694:             return nextQty > 0 ? { ...item, qty: nextQty } : null;
 695:           }
 696:           return item;
 697:         })
 698:         .filter(Boolean)
 699:     );
 700:   };
 701: 
 702:   const handleRemoveItem = (id) => {
 703:     const target = items.find((x) => x.id === id);
 704:     setItems((prev) => prev.filter((item) => item.id !== id));
 705:     showToast(`Removed "${target?.name || 'item'}" from your bag`);
 706:   };
 707: 
 708:   const handleApplyPromo = () => {
 709:     const code = promoCode.trim().toUpperCase();
 710:     if (!code || code === 'SOPHIE25' || code === 'VIP25' || code === '25OFF') {
 711:       const activeCode = code || 'SOPHIE25';
 712:       setDiscountRate(0.25);
 713:       setPromoCode(activeCode);
 714:       showToast(`Promo code applied: 25% VIP Discount (${activeCode})!`);
 715:     } else {
 716:       setDiscountRate(0.1);
 717:       showToast(`Promo code applied: 10% Welcome Discount (${code})!`);
 718:     }
 719:   };
 720: 
 721:   const handleSubmitOrder = (e) => {
 722:     e.preventDefault();
 723:     if (items.length === 0) {
 724:       showToast('Your shopping bag is empty! Add bags before placing an order.');
 725:       return;
 726:     }
 727:     const orderNumber = `#SPH-${Math.floor(10000 + Math.random() * 90000)}`;
 728:     const totalText = `£${finalTotal.toFixed(2)}`;
 729:     const orderData = { orderNumber, customer: form, items, total: finalTotal };
 730: 
 731:     setConfirmedOrder({
 732:       orderNumber,
 733:       customerName: form.firstName || 'Sophie',
 734:       totalText
 735:     });
 736:     onOrderPlaced?.(orderData);
 737:   };
 738: 
 739:   const totalItemCount = items.reduce((sum, item) => sum + item.qty, 0);
 740:   const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
 741:   const discountAmount = subtotal * discountRate;
 742:   const shippingCost = items.length > 0 ? parseFloat(form.deliveryMethod) || 0 : 0;
 743:   const finalTotal = Math.max(0, subtotal - discountAmount + shippingCost);
 744: 
 745:   return (
 746:     <section className="checkout-wrapper" id="checkout-view" aria-label="Checkout">
 747:       <div className="container" style={{ maxWidth: '1140px', margin: '0 auto', padding: '0 20px' }}>
 748:         <div className="checkout-top-bar">
 749:           <h1 className="checkout-giant-title">CHECKOUT</h1>
 750:           <button
 751:             type="button"
 752:             className="back-to-shop-btn"
 753:             onClick={onContinueShopping}
 754:           >
 755:             <i className="fa-solid fa-arrow-left" aria-hidden="true" /> Continue Shopping
 756:           </button>
 757:         </div>
 758: 
 759:         <form id="checkout-form" className="checkout-grid" onSubmit={handleSubmitOrder} noValidate>
 760:           {/* LEFT: Customer Info, Delivery, Payment */}
 761:           <div className="checkout-left-col">
 762:             {/* Information Block */}
 763:             <div className="checkout-block">
 764:               <div className="checkout-block-header">
 765:                 <h2 className="checkout-section-heading">Information</h2>
 766:                 <p className="checkout-login-prompt">
 767:                   Already have an account?{' '}
 768:                   <button type="button" onClick={onLoginClick}>Log in</button>
 769:                 </p>
 770:               </div>
 771: 
