1042:                 <p style={{ padding: '24px 0', color: '#64748b', fontSize: '13px' }}>
1043:                   Your shopping bag is currently empty.
1044:                 </p>
1045:               ) : (
1046:                 items.map((item) => (
1047:                   <div key={item.id} className="bag-item-row">
1048:                     <div className="bag-item-thumb">
1049:                       <img src={item.img} className={item.tint || ''} alt={item.name} />
1050:                     </div>
1051: 
1052:                     <div className="bag-item-info">
1053:                       <h4 className="bag-item-title">{item.name}</h4>
1054:                       <div className="bag-item-meta">
1055:                         <span className="meta-label">Size:</span>
1056:                         <span className="meta-val">{item.size}</span>
1057:                         <span className="meta-label">Color:</span>
1058:                         <span className="meta-val">{item.color}</span>
1059:                         <span className="meta-label">Quantity:</span>
1060:                         <span className="meta-val qty-stepper">
1061:                           <button
1062:                             type="button"
1063:                             className="qty-btn"
1064:                             onClick={() => handleUpdateQty(item.id, -1)}
1065:                           >
1066:                             -
1067:                           </button>
1068:                           <span>{item.qty}</span>
1069:                           <button
1070:                             type="button"
1071:                             className="qty-btn"
1072:                             onClick={() => handleUpdateQty(item.id, 1)}
1073:                           >
1074:                             +
1075:                           </button>
1076:                         </span>
1077:                       </div>
1078:                     </div>
1079: 
1080:                     <div className="bag-item-right">
1081:                       <span className="bag-item-price">
1082:                         £{(item.price * item.qty).toFixed(2)}
1083:                       </span>
1084:                       <button
1085:                         type="button"
1086:                         className="bag-remove-btn"
1087:                         onClick={() => handleRemoveItem(item.id)}
1088:                       >
1089:                         <i className="fa-regular fa-trash-can" aria-hidden="true" /> Remove
1090:                       </button>
1091:                     </div>
1092:                   </div>
1093:                 ))
1094:               )}
1095:             </div>
1096: 
1097:             {/* Promocode */}
1098:             <div className="promo-row">
1099:               <div className="line-input-wrap">
1100:                 <input
1101:                   type="text"
1102:                   className="line-input"
1103:                   placeholder="Promocode (Try SOPHIE25)"
1104:                   value={promoCode}
1105:                   onChange={(e) => setPromoCode(e.target.value)}
1106:                 />
1107:               </div>
1108:               <button
1109:                 type="button"
1110:                 className="btn-apply-promo"
1111:                 onClick={handleApplyPromo}
1112:               >
1113:                 APPLY
1114:               </button>
1115:             </div>
1116: 
1117:             {/* Summary Totals */}
1118:             <div className="bag-totals-row">
1119:               <span>Shipping</span>
1120:               <strong>{shippingCost === 0 ? 'Free' : `£${shippingCost.toFixed(2)}`}</strong>
1121:             </div>
1122: 
1123:             <div className="bag-totals-row">
1124:               <span>Discount</span>
1125:               <strong>
1126:                 {discountAmount > 0
1127:                   ? `-£${discountAmount.toFixed(2)} (${Math.round(discountRate * 100)}%)`
1128:                   : '£0.00'}
1129:               </strong>
1130:             </div>
1131: 
1132:             <div className="bag-grand-total">
1133:               <span>Total:</span>
1134:               <span className="total-amount">£{finalTotal.toFixed(2)}</span>
1135:             </div>
1136:           </div>
1137:         </form>
1138:       </div>
1139: 
1140:       {/* Confirmation Modal */}
1141:       {confirmedOrder && (
1142:         <div className="order-modal-backdrop open">
1143:           <div className="order-modal-card">
1144:             <div className="order-modal-icon">
1145:               <i className="fa-solid fa-check" aria-hidden="true" />
1146:             </div>
1147:             <h3 className="order-modal-title">ORDER CONFIRMED!</h3>
1148:             <p className="order-modal-desc">
1149:               Thank you, <strong>{confirmedOrder.customerName}</strong>! Your order of{' '}
1150:               <strong>{confirmedOrder.totalText}</strong> (
1151:               <strong>{confirmedOrder.orderNumber}</strong>) has been confirmed and is being prepared.
1152:             </p>
1153:             <button
1154:               type="button"
1155:               className="btn-place-order"
1156:               style={{ marginTop: 0 }}
1157:               onClick={() => {
1158:                 setConfirmedOrder(null);
1159:                 onContinueShopping?.();
1160:               }}
1161:             >
1162:               BACK TO STORE
1163:             </button>
1164:           </div>
1165:         </div>
1166:       )}
1167: 
1168:       {/* Toast Notice */}
1169:       {toastMessage && (
1170:         <div className="toast-notice show" role="status">
1171:           <i className="fa-solid fa-circle-check" aria-hidden="true" />
1172:           <span>{toastMessage}</span>
1173:         </div>
1174:       )}
1175:     </section>
1176:   );
1177: }
