 5: namespace App\Models;
 6: 
 7: use Database\Factories\CartFactory;
 8: use Illuminate\Database\Eloquent\Factories\HasFactory;
 9: use Illuminate\Database\Eloquent\Model;
10: use Illuminate\Database\Eloquent\Relations\BelongsTo;
11: use Illuminate\Database\Eloquent\Relations\HasMany;
12: use Illuminate\Support\Str;
13: 
14: /**
15:  * سلة تسوق: للزائر عبر cart_token أو للعميل المسجل عبر customer_id.
16:  * عند تسجيل دخول الزائر تُدمج سلة الزائر في سلة حسابه (CartService — مرحلة السلة).
17:  */
18: class Cart extends Model
19: {
20:     /** @use HasFactory<CartFactory> */
21:     use HasFactory;
22: 
23:     protected $fillable = [
24:         'cart_token',
25:         'customer_id',
26:         'coupon_id',
27:     ];
28: 
29:     protected static function booted(): void
30:     {
31:         static::creating(function (Cart $cart): void {
32:             $cart->cart_token ??= (string) Str::uuid();
33:         });
34:     }
35: 
36:     /** @return HasMany<CartItem, $this> */
