48:             'ends_at' => 'datetime',
49:             'is_active' => 'boolean',
50:         ];
51:     }
52: 
53:     /** @return HasMany<CouponUsage, $this> */
54:     public function usages(): HasMany
55:     {
56:         return $this->hasMany(CouponUsage::class);
57:     }
58: 
59:     public function isRedeemableNow(): bool
60:     {
61:         if (! $this->is_active) {
62:             return false;
63:         }
64:         if ($this->starts_at !== null && $this->starts_at->isFuture()) {
65:             return false;
66:         }
67:         if ($this->ends_at !== null && $this->ends_at->isPast()) {
68:             return false;
69:         }
70: 
71:         return $this->usage_limit === null || $this->used_count < $this->usage_limit;
72:     }
