 49:       // F22: سلة عميل — جلسة الزائر تُمسح حتى لا تُرسل لاحقًا ولا يرثها
 50:       // زائر تالٍ على جهاز مشترك.
 51:       clearGuestCartSession();
 52:     }
 53:     set({
 54:       items: cart.items.map(item => ({ id: item.id, productId: item.product_id, variantId: item.product_variant_id,
 55:         name: item.product_name || item.sku || 'Product', price: item.unit_price,
 56:         // L7: the backend ceiling (min of sellable stock and the identity
 57:         // line cap); fall back to available for older responses.
 58:         quantity: Number(item.qty), available: Number(item.max_qty ?? item.available) })),
 59:       serverTotal: Number(cart.totals.total),
 60:     });
 61:   };
 62:   const run = (operation: () => Promise<StoreCart>, mutation: boolean): Promise<boolean> => {
 63:     const owner = identity();
 64:     if (get().identity !== owner) set({ items: [], serverTotal: 0, identity: owner, error: null });
 65:     const execute = async (): Promise<boolean> => {
 66:       if (owner !== identity()) return false;
 67:       set({ busy: mutation, loading: !mutation, error: null });
 68:       try {
 69:         const cart = await operation();
 70:         if (owner !== identity()) return false;
 71:         apply(cart);
 72:         if (mutation) {
 73:           try { localStorage.setItem('cart_updated_at', `${Date.now()}:${Math.random()}`); } catch { /* Cross-tab sync is optional when storage is blocked. */ }
 74:         }
 75:         return true;
 76:       } catch (error) {
 77:         if (owner === identity()) {
 78:           const message = (error as { response?: { data?: { message?: string } } }).response?.data?.message;
 79:           set({ error: message || 'We could not update your cart. Please try again.' });
 80:         }
 81:         return false;
 82:       } finally {
 83:         set({ busy: false, loading: false });
 84:       }
 85:     };
 86:     const task = queue.then(async (): Promise<boolean> => {
 87:       if (typeof navigator !== 'undefined' && navigator.locks) return Boolean(await navigator.locks.request('alfarid-store-cart', execute));
 88:       return execute();
 89:     });
 90:     queue = task.catch(() => {});
 91:     return task;
 92:   };
 93:   return {
 94:     items: [], busy: false, loading: false, error: null, serverTotal: 0, identity: 'guest',
 95:     loadCart: () => run(() => cartEndpoints.get(session()), false),
 96:     addItem: (variantId, quantity) => {
 97:       const qty = quantity ?? 1;
 98:       if (!Number.isInteger(qty) || qty < 1) return Promise.resolve(false);
 99:       return run(() => cartEndpoints.add(variantId, qty, session()), true);
100:     },
101:     removeItem: (id) => run(() => cartEndpoints.remove(id, session()), true),
102:     updateQuantity: (id, qty) => {
103:       if (!Number.isInteger(qty) || qty < 0) return Promise.resolve(false);
104:       const item = get().items.find((item) => item.id === id);
105:       if (qty > 0 && item && qty > item.available) return Promise.resolve(false);
106:       return run(() => cartEndpoints.update(id, qty, session()), true);
107:     },
108:     clearCart: () => run(() => cartEndpoints.clear(session()), true),
109:     total: () => get().serverTotal,
110:   };
111: });
