22: /** مصادقة المتجر القطاعي: تسجيل فوري معتمد، دخول، خروج، واستعادة كلمة المرور. */
23: class AuthController extends Controller
24: {
25:     public function __construct(
26:         private readonly CustomerAuthService $auth,
27:         private readonly CartService $carts,
28:     ) {}
29: 
30:     public function register(RegisterRequest $request): JsonResponse
31:     {
32:         [$customer, $token] = DB::transaction(function () use ($request): array {
33:             $customer = $this->auth->registerRetail($request->validated());
34: 
35:             return [$customer, $this->auth->issueToken($customer, 'store-token')];
36:         });
37: 
38:         // حساب جديد = دخول فوري: تُدمج سلة الزائر إن وُجدت
39:         $this->carts->mergeGuestCart($customer, $request->header('X-Cart-Session'));
40: 
41:         return CustomerResource::make($customer)
42:             ->additional(['message' => 'تم إنشاء حسابك بنجاح', 'token' => $token])
43:             ->response()
44:             ->setStatusCode(201);
45:     }
46: 
47:     public function login(LoginRequest $request): CustomerResource
48:     {
49:         $customer = $this->auth->login($request->validated()['login'], $request->validated()['password']);
50:         $token = $this->auth->issueToken($customer, 'store-token');
51: 
52:         // دمج سلة الزائر (إن وُجدت بهيدر الجلسة) في سلة الحساب تلقائيًا
53:         $this->carts->mergeGuestCart($customer, $request->header('X-Cart-Session'));
54: 
55:         return CustomerResource::make($customer)
56:             ->additional(['message' => 'تم تسجيل الدخول بنجاح', 'token' => $token]);
57:     }
58: 
59:     /** خروج: حذف التوكن الحالي فقط (بقية الجلسات على أجهزة أخرى تظل فعالة). */
60:     public function logout(Request $request): JsonResponse
61:     {
62:         $request->user()->currentAccessToken()->delete();
63: 
64:         return response()->json(['message' => 'تم تسجيل الخروج بنجاح']);
65:     }
66: 
67:     public function forgotPassword(ForgotPasswordRequest $request): JsonResponse
68:     {
69:         $this->auth->forgotPassword($request->validated()['email'] ?? null, $request->validated()['phone'] ?? null);
70: 
71:         return response()->json(['message' => 'لو الحساب موجود، أرسلنا رمز الاستعادة إليه.']);
72:     }
73: 
74:     public function resetPassword(ResetPasswordRequest $request): JsonResponse
75:     {
76:         $this->auth->resetPassword($request->validated());
77: 
78:         return response()->json(['message' => 'تم تغيير كلمة المرور؛ سجل الدخول من جديد.']);
79:     }
80: 
81:     public function sendPhoneVerification(PhoneVerificationRequest $request): JsonResponse
82:     {
83:         SendCustomerPhoneVerification::dispatch($request->validated()['phone'])
84:             ->onConnection(config('auth.customer_password_reset.connection', 'database'));
85: 
86:         return response()->json(['message' => 'لو الرقم متاح للتسجيل، سيتم إرسال رمز التحقق إليه.']);
87:     }
88: 
89:     public function verifyPhone(PhoneVerificationRequest $request): JsonResponse
90:     {
91:         $data = $request->validated();
92:         $proof = app(CustomerPhoneVerificationService::class)->verify($data['phone'], $data['code']);
93: 
94:         return response()->json(['phone_verification_token' => $proof, 'expires_in' => 600]);
95:     }
