16: /** تصفح منتجات المتجر: قائمة بفلاتر، وصفحة منتج بالـ slug، ومنتجات مشابهة. كله عام. */
17: class ProductController extends Controller
18: {
19:     public function __construct(private readonly StoreCatalogService $catalog) {}
20: 
21:     public function index(ProductFilterRequest $request): AnonymousResourceCollection
22:     {
23:         $filters = $request->validated();
24:         $total = in_array($filters['sort'] ?? null, ['price_asc', 'price_desc'], true)
25:             && ! isset($filters['price_min']) && ! isset($filters['price_max'])
26:             ? fn () => $this->catalog->applyFilters($this->catalog->publishedQuery(), [...$filters, 'sort' => 'newest'])
27:                 ->reorder()->count('products.id') : null;
28:         $products = $this->catalog->applyFilters($this->catalog->publishedQuery(), $request->validated())
29:             ->paginate((int) ($filters['per_page'] ?? 20), total: $total)->withQueryString();
30: 
31:         return StoreProductCardResource::collection($products);
32:     }
33: 
34:     public function show(string $slug): StoreProductResource
35:     {
36:         $product = $this->catalog->publishedQuery()
37:             ->where('products.slug', $slug)
38:             ->firstOrFail();
39: 
40:         $resource = new StoreProductResource($product);
41: 
42:         return $resource;
43:     }
44: 
45:     public function showcase(Request $request): JsonResponse
46:     {
47:         $ids = $this->catalog->showcaseIds();
48:         $loaded = $this->catalog->publishedQuery()->whereIn('products.id', $ids)->get()->keyBy('id');
49:         $products = collect($ids)->map(fn ($id) => $loaded->get($id))->filter()->values();
50: 
51:         return response()->json(['data' => $products->map(function ($p) use ($request) {
52:             $resource = new StoreProductResource($p);
53: 
54:             return $resource->resolve($request);
55:         })->values()]);
56:     }
57: 
58:     public function similar(string $slug): JsonResponse
59:     {
60:         $product = $this->catalog->publishedQuery()
61:             ->withoutEagerLoads()
62:             // F19: similar() only matches on category_id — brand links are
63:             // legacy (brand_id is always null), so don't select the column.
64:             ->select(['products.id', 'products.category_id'])
65:             ->where('products.slug', $slug)
66:             ->firstOrFail();
67: 
68:         return response()->json([
69:             'data' => StoreProductCardResource::collection($this->catalog->similar($product))->resolve(),
70:         ]);
71:     }
72: } 1: <?php
