181:     } else if (response?.status === 429) {
182:       const seconds = response.headers?.['retry-after'] ?? '60';
183:       setFormError(text(`محاولات كثيرة، حاول بعد ${seconds} ثانية.`, `Too many attempts. Try again in ${seconds}s.`));
184:     } else {
