 22: use App\Services\Auth\UnifiedAuthService;
 23: use App\Services\CartService;
 24: use App\Services\CustomerAuthService;
 25: use Illuminate\Contracts\Cache\LockTimeoutException;
 26: use Illuminate\Http\JsonResponse;
 27: use Illuminate\Http\Request;
 28: use Illuminate\Http\Response;
 29: use Illuminate\Support\Facades\DB;
 30: 
 31: class UnifiedAuthController extends Controller
 32: {
 33:     public function __construct(
 34:         private readonly UnifiedAuthService $auth,
 35:         private readonly LoginDestinationResolver $destinations,
 36:         private readonly StaffHandoffService $handoff,
 37:         private readonly CustomerAuthService $customerAuth,
 38:         private readonly CartService $carts,
 39:     ) {}
 40: 
 41:     public function login(UnifiedLoginRequest $request): JsonResponse
 42:     {
 43:         $data = $request->validated();
 44:         $actor = $this->auth->attempt($data['login'], $data['password']);
 45:         $redirect = $this->destinations->resolve($actor, $data['redirect'] ?? null);
 46: 
 47:         if ($actor instanceof User) {
 48:             return $this->respond('staff', $redirect, null, $this->handoff->issue($actor),
 49:                 ['id' => $actor->id, 'name' => $actor->name], 'active');
 50:         }
 51: 
 52:         if ($actor instanceof SupplierUser) {
 53:             $actor->load('supplier');
 54: 
 55:             return $this->respond('supplier', $redirect, $this->issueSupplierToken($actor), null,
 56:                 SupplierUserResource::make($actor)->resolve($request), 'active');
 57:         }
 58: 
 59:         /** @var Customer $actor */
 60:         $token = $this->customerAuth->issueToken($actor, $actor->type === CustomerType::Retail ? 'store-token' : 'wholesale-token');
 61:         // M10: الدمج best-effort بعد إصدار التوكن — فشله لا يُفشل الدخول ولا
 62:         // يُيتّم التوكن؛ يُبلغ الفرونت بالنتيجة ليحتفظ بـ cart_session عند الفشل.
 63:         $cartMerged = true;
 64:         try {
 65:             $this->carts->mergeGuestCart($actor, $request->header('X-Cart-Session'));
 66:         } catch (\Throwable $exception) {
 67:             report($exception);
 68:             $cartMerged = false;
 69:         }
 70: 
 71:         return $this->respond('customer', $redirect, $token, null,
 72:             CustomerResource::make($actor)->resolve($request), $actor->status->value,
 73:             $actor->type->value, $cartMerged);
 74:     }
 75: 
 76:     public function exchange(HandoffExchangeRequest $request): JsonResponse
 77:     {
 78:         // L3: الكود المستهلك يُعامل كغير صالح (401)، أما أعطال البنية
 79:         // (قاعدة/كاش) فتُترك لتُرجع 503/500 بدل ابتلاعها في 401 مضلل.
 80:         try {
 81:             $payload = $this->handoff->consume($request->validated()['code']);
 82:         } catch (LockTimeoutException $exception) {
 83:             report($exception);
 84:             $payload = null;
 85:         }
 86:         $user = $payload ? User::query()->find($payload['user_id']) : null;
 87: 
 88:         if (! $user instanceof User || ! $user->is_active || $user->is_system || ! is_string($payload['credentials'] ?? null)) {
 89:             logger()->info('staff.handoff', ['ip' => $request->ip(), 'result' => 'rejected']);
 90: 
 91:             return response()->json(['message' => 'رابط الدخول غير صالح أو انتهت صلاحيته.'], 401);
 92:         }
 93: 
 94:         // تُحسم الوجهة (بما فيها فحص الأدوار/الفرع) قبل إصدار أي توكن حتى
 95:         // لا يتخلف توكن يتيم عند الرفض.
 96:         $user->load(['branch', 'roles.permissions', 'permissions']);
 97:         $redirect = $this->destinations->resolve($user);
 98: 
 99:         $token = app(StaffTokenService::class)->issue($user, $payload['credentials']);
100: 
101:         logger()->info('staff.handoff', ['user_id' => $user->id, 'ip' => $request->ip(), 'result' => 'success']);
102: 
103:         return response()->json([
104:             'data' => UserResource::make($user)->resolve($request),
105:             'token' => $token,
106:             'redirect' => $redirect,
107:         ]);
108:     }
109: 
110:     public function me(Request $request): JsonResponse
111:     {
112:         $actor = $request->user('sanctum');
113: 
114:         if ($actor instanceof User) {
115:             abort_unless($actor->is_active && ! $actor->is_system, 403);
116:             $actor->load(['branch', 'roles.permissions', 'permissions']);
117:             $redirect = $this->destinations->resolve($actor);
118: 
119:             return response()->json(['actor' => ['type' => 'staff', 'subtype' => $redirect['destination']],
120:                 'redirect' => $redirect,
121:                 'data' => UserResource::make($actor)->resolve($request)]);
122:         }
123: 
124:         if ($actor instanceof SupplierUser) {
125:             // H5: أعد فحص الشركة هنا أيضًا — إيقافها بعد إصدار التوكن يجب أن
126:             // يمنع الجلسة فورًا لا عند انتهاء التوكن.
127:             abort_unless($actor->is_active && $actor->supplier_id !== null
128:                 && $actor->supplier?->is_active === true, 403);
129:             $actor->load('supplier');
130:             $redirect = $this->destinations->resolve($actor);
131: 
132:             return response()->json(['actor' => ['type' => 'supplier', 'subtype' => $redirect['destination']],
133:                 'redirect' => $redirect,
134:                 'data' => SupplierUserResource::make($actor)->resolve($request)]);
135:         }
136: 
137:         if ($actor instanceof Customer) {
138:             abort_if($actor->status === CustomerStatus::Suspended, 403);
139:             $redirect = $this->destinations->resolve($actor);
140: 
141:             return response()->json([
142:                 // M1: subtype هو الـ destination دائمًا (كما في login)، ونوع
143:                 // العميل في حقل منفصل حتى لا يبني الفرونت الوجهة من me خطأً.
144:                 'actor' => ['type' => 'customer', 'subtype' => $redirect['destination'],
145:                     'customer_type' => $actor->type->value, 'status' => $actor->status->value],
146:                 'redirect' => $redirect,
147:                 'data' => CustomerResource::make($actor)->resolve($request)]);
148:         }
149: 
150:         abort(401);
151:     }
152: 
153:     public function logout(Request $request): Response
154:     {
155:         $request->user('sanctum')?->currentAccessToken()?->delete();
156: 
157:         return response()->noContent();
158:     }
159: 
160:     private function issueSupplierToken(SupplierUser $user): string
161:     {
162:         // L1: الحد غير ذري — دخولان متزامنان يتجاوزانه. القفل داخل transaction.
163:         return DB::transaction(function () use ($user): string {
164:             $user = SupplierUser::query()->lockForUpdate()->findOrFail($user->id);
165:             if (! $user->is_active || $user->supplier_id === null || $user->supplier?->is_active !== true) {
166:                 throw new BusinessException('بيانات الدخول غير صحيحة.', [], 401);
167:             }
168:             // M1: SANCTUM_EXPIRATION الفارغ يعني بلا انتهاء زمني — لا تمسح كل التوكنات.
169:             $expiry = config('sanctum.expiration');
170:             $user->tokens()->where(fn ($q) => $q->where('expires_at', '<=', now())
171:                 ->when($expiry, fn ($q) => $q->orWhere('created_at', '<=', now()->subMinutes((int) $expiry))))->delete();
172:             $limit = max(1, (int) config('auth.supplier_max_tokens', 5));
173:             $old = $user->tokens()->orderByDesc('id')->skip($limit - 1)->pluck('id');
174:             if ($old->isNotEmpty()) {
175:                 $user->tokens()->whereIn('id', $old)->delete();
176:             }
177: 
178:             return $user->createToken('supplier-token')->plainTextToken;
179:         });
180:     }
181: 
182:     /**
183:      * @param  array{app: string, path: string, destination: string}  $redirect
184:      * @param  array<string, mixed>  $data
185:      */
186:     private function respond(string $type, array $redirect, ?string $token, ?string $handoff, array $data, ?string $status, ?string $customerType = null, ?bool $cartMerged = null): JsonResponse
187:     {
188:         return response()->json(array_filter([
189:             'message' => 'تم تسجيل الدخول بنجاح',
190:             // M1: customer_type منفصل عن subtype (الوجهة) حتى لا يبني الفرونت
191:             // الوجهة من نوع العميل خطأً.
192:             'actor' => array_filter(['type' => $type, 'subtype' => $redirect['destination'], 'status' => $status,
193:                 'customer_type' => $customerType], fn ($v) => $v !== null),
194:             'redirect' => $redirect,
195:             'token' => $token,
196:             'handoff_code' => $handoff,
197:             'data' => $data,
198:             'cart_merged' => $cartMerged,
199:         ], fn ($v, $k) => $v !== null || $k === 'handoff_code' || $k === 'token', ARRAY_FILTER_USE_BOTH));
200:     }
201: } 1: <?php
