29:     public function categories(Request $request): JsonResponse
30:     {
31:         $roots = Category::query()
32:             ->whereNull('parent_id')
33:             ->where('is_active', true)
34:             ->with('media')
35:             ->withCount('activeProducts')
36:             ->with([
37:                 // L6: id tie-break keeps sibling order deterministic across pages.
38:                 'children' => fn ($q) => $q->where('is_active', true)->with('media')->withCount('activeProducts')->orderBy('sort_order')->orderBy('id')
39:                     ->with(['children' => fn ($q2) => $q2->where('is_active', true)->with('media')->withCount('activeProducts')->orderBy('sort_order')->orderBy('id')]),
40:             ])
41:             ->orderBy('sort_order')->orderBy('id')
42:             ->get();
43: 
44:         return response()->json(['data' => StoreCategoryResource::collection($roots)->resolve($request)]);
45:     }
46: 
47:     /**
48:      * F19: brands are a legacy surface — products no longer accept a brand_id
49:      * (prohibited in admin requests, forced to null in the service) and the
50:      * storefront never filters by brand. This endpoint is retained read-only
51:      * for old clients; do not build new features on it.
52:      */
53:     public function brands(Request $request): JsonResponse
54:     {
55:         $brands = Brand::query()
56:             ->with('media')
57:             ->where('is_active', true)
58:             ->orderBy('sort_order')
59:             ->orderBy('name_ar')
60:             ->get();
61: 
62:         return response()->json(['data' => StoreBrandResource::collection($brands)->resolve($request)]);
63:     }
