 11: use Illuminate\Database\Eloquent\Model;
 12: use Illuminate\Database\Eloquent\Relations\BelongsTo;
 13: use Illuminate\Database\Eloquent\Relations\HasMany;
 14: use Illuminate\Database\Eloquent\SoftDeletes;
 15: use Spatie\Image\Enums\Fit;
 16: use Spatie\MediaLibrary\HasMedia;
 17: use Spatie\MediaLibrary\InteractsWithMedia;
 18: use Spatie\MediaLibrary\MediaCollections\Models\Media;
 19: 
 20: class Category extends Model implements HasMedia
 21: {
 22:     /** @use HasFactory<CategoryFactory> */
 23:     use HasFactory, InteractsWithMedia, SoftDeletes;
 24: 
 25:     protected $fillable = ['parent_id', 'name_ar', 'name_en', 'slug', 'description_ar', 'description_en', 'sort_order', 'is_active'];
 26: 
 27:     protected $casts = ['is_active' => 'boolean'];
 28: 
 29:     public function parent(): BelongsTo
 30:     {
 31:         return $this->belongsTo(Category::class, 'parent_id');
 32:     }
 33: 
 34:     public function children(): HasMany
 35:     {
 36:         return $this->hasMany(Category::class, 'parent_id')->orderBy('sort_order')->orderBy('id');
 37:     }
 38: 
 39:     public function products(): HasMany
 40:     {
 41:         return $this->hasMany(Product::class);
 42:     }
 43: 
 44:     /** المنتجات المنشورة فقط — أساس عدّادات أقسام المتجر. */
 45:     public function activeProducts(): HasMany
 46:     {
 47:         return $this->hasMany(Product::class)->where('status', ProductStatus::Published)
 48:             ->whereIn('sales_channel', [SalesChannel::Retail, SalesChannel::Both]);
 49:     }
 50: 
 51:     public function registerMediaCollections(): void
 52:     {
 53:         $this->addMediaCollection('image')->singleFile()->useDisk('r2_public')->storeConversionsOnDisk('r2_public')
 54:             ->acceptsMimeTypes(['image/jpeg', 'image/png', 'image/webp']);
 55:     }
 56: 
 57:     // L5: category tiles render small thumbs — generate them once instead of
 58:     // serving up-to-6000px originals in storefront tiles.
 59:     public function registerMediaConversions(?Media $media = null): void
 60:     {
 61:         $this->addMediaConversion('thumb')->fit(Fit::Crop, 300, 300)->format('webp')
 62:             ->performOnCollections('image');
 63:         $this->addMediaConversion('medium')->fit(Fit::Contain, 800, 800)->format('webp')
 64:             ->performOnCollections('image');
 65:     }
 66: 
 67:     // بيرجّع IDs كل الأقسام اللي تحته على أي مستوى — مجموعة visited بتمنع اللف اللانهائي لو فيه دورة في البيانات
 68:     public function descendantIds(): array
 69:     {
 70:         $ids = [];
 71:         $seen = [$this->id => true];
 72:         $queue = [$this->id];
 73:         while ($queue) {
 74:             $children = Category::whereIn('parent_id', $queue)->pluck('id')->all();
 75:             $queue = [];
 76:             foreach ($children as $childId) {
 77:                 if (! isset($seen[$childId])) {
 78:                     $seen[$childId] = true;
 79:                     $ids[] = $childId;
 80:                     $queue[] = $childId;
 81:                 }
 82:             }
 83:         }
 84: 
 85:         return $ids;
 86:     }
 87: 
 88:     public function depth(): int
 89:     {
 90:         $depth = 1;
 91:         $seen = [$this->id => true];
 92:         $p = $this->parent;
 93:         while ($p) {
 94:             if (isset($seen[$p->id])) {
 95:                 throw new \RuntimeException('توجد دورة في شجرة الأقسام');
 96:             }
 97:             $seen[$p->id] = true;
 98:             $depth++;
 99:             $p = $p->parent;
100:         }
101: 
102:         return $depth;
103:     }
104: }  1: <?php
