  5: namespace App\Services;
  6: 
  7: use App\Enums\CustomerStatus;
  8: use App\Enums\CustomerType;
  9: use App\Exceptions\BusinessException;
 10: use App\Jobs\SendCustomerPasswordReset;
 11: use App\Models\Customer;
 12: use App\Models\CustomerAuditLog;
 13: use App\Notifications\Channels\CustomerSmsChannel;
 14: use App\Notifications\CustomerPasswordReset;
 15: use Illuminate\Support\Facades\DB;
 16: use Illuminate\Support\Facades\Hash;
 17: use Illuminate\Support\Str;
 18: 
 19: /**
 20:  * دورة مصادقة العملاء (متجر قطاعي + جملة): التسجيل، الدخول، واستعادة كلمة المرور.
 21:  * القيم الحساسة (type/status) تُفرض هنا برمجيًا ولا تأتي من الطلب أبدًا.
 22:  */
 23: class CustomerAuthService
 24: {
 25:     public static function dummyHash(): string
 26:     {
 27:         if (config('hashing.driver', 'bcrypt') === 'bcrypt') {
 28:             return sprintf('$2y$%02d$92IXUNpkjO0rOQ5byMi.Ye4oKoEa3Ro9llC/.og/at2uheWG/igi.', (int) config('hashing.bcrypt.rounds', 12));
 29:         }
 30:         static $hashes = [];
 31:         $key = json_encode(config('hashing'));
 32: 
 33:         return $hashes[$key] ??= Hash::make('not-a-customer-password');
 34:     }
 35: 
 36:     private function identifierKey(string $identifier): string
 37:     {
 38:         return hash_hmac('sha256', $identifier, (string) config('app.key'));
 39:     }
 40: 
 41:     /** تسجيل متجر قطاعي: نوع retail وحالة approved دائمًا. */
 42:     public function registerRetail(array $data): Customer
 43:     {
 44:         $verified = app(CustomerPhoneVerificationService::class)->consume($data);
 45: 
 46:         $customer = Customer::query()->create([
 47:             'name' => $data['name'],
 48:             'email' => $data['email'] ?? null,
 49:             'phone' => $data['phone'],
 50:             'password' => $data['password'],
 51:             'type' => CustomerType::Retail,
 52:             'status' => CustomerStatus::Approved,
 53:             'phone_verified_at' => $verified ? now() : null,
 54:             'approved_at' => now(),
 55:         ]);
 56:         CustomerAuditLog::record($customer, 'self_registered', null, ['channel' => 'store']);
 57: 
 58:         return $customer;
 59:     }
 60: 
 61:     /**
 62:      * دخول بالهاتف أو البريد. الحساب الموقوف يُرفض 403 بسبب الإيقاف؛
 63:      * أي حالة أخرى (بما فيها pending/rejected للجملة) تستطيع الدخول —
 64:      * بوابات النوع والحالة (wholesale.approved) تحكم ما بعد الدخول.
 65:      */
 66:     public function login(string $identifier, string $password): Customer
 67:     {
 68:         $emailLogin = str_contains($identifier, '@');
 69:         $identifier = $emailLogin ? mb_strtolower(trim($identifier)) : Customer::normalizePhone($identifier);
 70:         $dummyHash = self::dummyHash();
 71:         $customer = Customer::query()
 72:             ->when($emailLogin, fn ($q) => $q->whereNotNull('email_verified_at')->whereRaw('LOWER(email) = ?', [$identifier]), fn ($q) => $q->where('phone', $identifier))
 73:             ->first();
 74: 
 75:         $validPassword = Hash::check($password, $customer?->password ?? $dummyHash);
 76:         if ($customer === null || ! $validPassword) {
 77:             // M11: لا تكتب صف audit لمعرّف غير موجود (هجمات stuffing تتحول لكتابات
 78:             // غير محدودة)، واكتفِ بسجل info مع sampling. المعرّف يُحمى بـ HMAC
 79:             // بمفتاح التطبيق لأن sha256 وحده قابل للعكس على مساحة الهواتف.
 80:             if ($customer === null) {
 81:                 if (random_int(1, 10) === 1) {
 82:                     logger()->info('customer.login_failed', ['identifier_key' => $this->identifierKey($identifier)]);
 83:                 }
 84:             } else {
 85:                 defer(fn () => CustomerAuditLog::record($customer, 'login_failed', null, ['identifier_key' => $this->identifierKey($identifier)]))->always();
 86:             }
 87:             throw new BusinessException('بيانات الدخول غير صحيحة.', [], 401);
 88:         }
 89: 
 90:         if ($customer->status === CustomerStatus::Suspended) {
 91:             CustomerAuditLog::record($customer, 'login_failed', null, ['reason' => 'suspended']);
 92:             throw new BusinessException(
 93:                 'هذا الحساب موقوف.'.($customer->suspension_reason ? ' السبب: '.$customer->suspension_reason : ''),
 94:                 ['suspension_reason' => $customer->suspension_reason],
 95:                 403,
 96:             );
 97:         }
 98: 
 99:         if (Hash::needsRehash($customer->password)) {
100:             $customer->forceFill(['password' => $password])->save();
101:         }
102:         CustomerAuditLog::record($customer, 'login_succeeded', null);
103: 
104:         return $customer;
105:     }
106: 
107:     /**
108:      * استعادة كلمة المرور: رمز في password_reset_tokens + إشعار للعميل.
109:      * الرد واحد دائمًا (نجاح ظاهري) حتى لا يُستدل على وجود الحساب.
110:      */
111:     public function forgotPassword(?string $email, ?string $phone): void
112:     {
113:         if (! $email && ! $phone) {
114:             return;
115:         }
116: 
117:         SendCustomerPasswordReset::dispatch($email, $phone)
118:             ->onConnection(config('auth.customer_password_reset.connection', 'database'));
119:     }
