121:     public function sendPasswordReset(?string $email, ?string $phone): void
122:     {
123:         if (! $email && ! $phone) {
124:             return;
125:         }
126: 
127:         $customer = Customer::query()
128:             ->when($email, fn ($q) => $q->whereNotNull('email_verified_at')->whereRaw('LOWER(email) = ?', [mb_strtolower(trim($email))]),
129:                 fn ($q) => $q->where('phone', Customer::normalizePhone($phone)))
130:             ->first();
131: 
132:         if ($customer === null || $customer->status === CustomerStatus::Suspended) {
133:             return;
134:         }
135: 
136:         $plainToken = Str::random(64);
137:         $key = $customer->getEmailForPasswordReset();
138: 
139:         $stored = DB::transaction(function () use ($customer, $key, $plainToken, $email): bool {
140:             $current = Customer::query()->lockForUpdate()->find($customer->id);
141:             if ($current === null || $current->status === CustomerStatus::Suspended) {
142:                 return false;
143:             }
144:             if ($email && ($current->email_verified_at === null || $current->email !== mb_strtolower(trim($email)))) {
145:                 return false;
146:             }
147:             $existing = DB::table('password_reset_tokens')->where('email', $key)->first();
148:             if ($existing && now()->subSeconds(60)->lt($existing->created_at)) {
149:                 return false;
150:             }
151:             if (! app(CustomerMessageBudget::class)->claim('reset:customer:'.$customer->id, sms: ! $email)) {
152:                 return false;
153:             }
154:             DB::table('password_reset_tokens')->updateOrInsert(
155:                 ['email' => $key], ['token' => hash('sha256', $plainToken), 'created_at' => now()],
156:             );
157: 
158:             return true;
159:         });
160:         if (! $stored) {
161:             return;
162:         }
163: 
164:         try {
165:             $customer->notify(new CustomerPasswordReset($plainToken, $email ? 'mail' : CustomerSmsChannel::class));
166:         } catch (\Throwable $exception) {
167:             report($exception);
168:         }
169:     }
