171:     public function resetPassword(array $data): void
172:     {
173:         $dummyHash = self::dummyHash();
174:         DB::transaction(function () use ($data, $dummyHash): void {
175:             $customer = Customer::query()
176:                 ->when(! empty($data['email']), fn ($q) => $q->whereNotNull('email_verified_at')->whereRaw('LOWER(email) = ?', [mb_strtolower(trim($data['email']))]),
177:                     fn ($q) => $q->where('phone', $data['phone']))
178:                 ->lockForUpdate()->first();
179:             $key = $customer?->getEmailForPasswordReset();
180:             $row = DB::table('password_reset_tokens')->where('email', $key)->lockForUpdate()->first();
181:             $storedToken = $row?->token ?? '';
182:             $validToken = strlen($storedToken) === 64 ? hash_equals($storedToken, hash('sha256', $data['token']))
183:                 : Hash::check($data['token'], $storedToken ?: $dummyHash);
184:             if ($customer === null || $customer->status === CustomerStatus::Suspended || $row === null
185:                 || $row->created_at === null || now()->subMinutes(60)->gte($row->created_at)
186:                 || now()->lt($row->created_at) || ! $validToken) {
187:                 throw new BusinessException('رمز الاستعادة غير صالح أو انتهت صلاحيته.');
188:             }
189:             $customer->forceFill(['password' => $data['password'], 'remember_token' => Str::random(60)])->save();
190:             $customer->tokens()->delete();
191:             DB::table('password_reset_tokens')->where('email', $key)->delete();
192:             CustomerAuditLog::record($customer, 'password_reset', null);
193:         });
194:     }
