196:     /** إصدار توكن Sanctum باسم القناة (store-token / wholesale-token). */
197:     public function issueToken(Customer $customer, string $name): string
198:     {
199:         return DB::transaction(function () use ($customer, $name): string {
200:             $customer = Customer::query()->lockForUpdate()->findOrFail($customer->id);
201:             if ($customer->status === CustomerStatus::Suspended) {
202:                 throw new BusinessException('هذا الحساب موقوف.', [], 403);
203:             }
204: 
205:             $expiry = config('sanctum.expiration');
206:             $customer->tokens()->where(fn ($q) => $q->where('expires_at', '<=', now())
207:                 ->when($expiry, fn ($q) => $q->orWhere('created_at', '<=', now()->subMinutes((int) $expiry))))->delete();
208:             $limit = max(1, (int) config('auth.customer_max_tokens', 10));
209:             $old = $customer->tokens()->orderByDesc('id')->skip($limit - 1)->pluck('id');
210:             if ($old->isNotEmpty()) {
211:                 $customer->tokens()->whereIn('id', $old)->delete();
212:             }
213: 
214:             $token = $customer->createToken($name, ['*'], now()->addMinutes(max(1, (int) config('auth.customer_token_minutes', 1440))));
215:             CustomerAuditLog::record($customer, 'token_issued', null, ['token_id' => $token->accessToken->id, 'channel' => $name]);
216: 
217:             return $token->plainTextToken;
218:         });
219:     }
