  6: async function revokePreviousSession(nextToken?: string | null) {
  7:   const previous = useAuthStore.getState().token;
  8:   if (!previous || previous === nextToken) return;
  9:   try {
 10:     await createApiClient({ getToken: () => previous, onUnauthorized: () => {} })
 11:       .post('/api/v1/auth/logout', {}, { timeout: 10000 });
 12:   } catch { /* The previous session may already have expired. */ }
 13: }
