 15: export async function loginUnified(login: string, password: string, redirect?: string | null) {
 16:   const res = await authEndpoints.login({ login, password, redirect: redirect ?? undefined },
 17:     typeof window !== 'undefined' ? localStorage.getItem(CART_KEY) : null);
 18:   await revokePreviousSession(res.token);
 19: 
 20:   if (res.redirect.app === 'backoffice') {
 21:     // M9: جلسة عميل/مورد قائمة توكنها يبقى صالحًا 24 ساعة بعد clear المحلي —
 22:     // أبطلها في الخادم أولًا (best-effort) قبل مسح الجلسة المحلية.
 23:     useAuthStore.getState().clear();
 24:     // M7: الكود في الـ fragment لا في الـ query — الـ fragment لا يُرسل
 25:     // للخادم ولا يظهر في الـ Referer أو سجلات nginx.
 26:     const url = `${resolveServiceUrl(process.env.NEXT_PUBLIC_BACKOFFICE_URL ?? 'http://localhost:5173')}/auth/callback#code=${encodeURIComponent(res.handoff_code!)}`;
 27:     window.location.assign(url);
 28:     return null;
 29:   }
 30: 
 31:   useAuthStore.getState().setSession({
 32:     token: res.token!, actorType: res.actor.type as 'customer' | 'supplier',
 33:     destination: res.actor.subtype, home: res.redirect.path, user: res.data,
 34:   });
 35:   // M10: الدمج قد يفشل في الخادم (cart_merged=false) — أبقِ cart_session
 36:   // ليُعاد دمجه لاحقًا بدل حذفه مع توكن يتيم جديد.
 37:   if (res.actor.type === 'customer' && res.cart_merged !== false) localStorage.removeItem(CART_KEY);
 38:   return res.redirect.path;
 39: }
