33:             'expected_total' => ['nullable', 'numeric', 'min:0'],
34:             // طرق الدفع من الإعدادات فقط — طريقة بلا بوابة مربوطة لا تُقبل (H9)
35:             'payment_method' => ['required', Rule::in($this->allowedPaymentMethods())],
36:         ];
37:     }
38: 
39:     /** @return array<int, string> */
40:     private function allowedPaymentMethods(): array
41:     {
42:         $configured = array_values(array_filter((array) config('store.payment_methods', ['cod'])));
43:         $walletEnabled = in_array('wallet', $configured, true);
44:         $methods = array_values(array_filter($configured, fn ($method) => $method !== 'wallet'));
45: 
46:         // المحفظة من الإعدادات فقط، ولعملاء معتمدين. إيقافها يتم بحذفها من STORE_PAYMENT_METHODS.
47:         $user = auth('sanctum')->user();
48:         if ($walletEnabled && $user instanceof Customer && $user->status === CustomerStatus::Approved) {
49:             $methods[] = 'wallet';
50:         }
51:         if ($user instanceof Customer
52:             && $user->status === CustomerStatus::Approved
53:             && in_array($user->type, [CustomerType::Wholesale, CustomerType::Distributor], true)) {
54:             $methods[] = 'credit';
55:         }
56: 
57:         return array_values(array_unique($methods));
