 78:     public static function normalizePhone(string $phone): string
 79:     {
 80:         $phone = strtr(trim($phone), array_combine(
 81:             preg_split('//u', '٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹', -1, PREG_SPLIT_NO_EMPTY),
 82:             str_split('01234567890123456789'),
 83:         ));
 84:         $phone = preg_replace('/[\s().-]+/u', '', $phone);
 85:         if (str_starts_with($phone, '+20')) {
 86:             return '0'.substr($phone, 3);
 87:         }
 88:         if (str_starts_with($phone, '0020')) {
 89:             return '0'.substr($phone, 4);
 90:         }
 91: 
 92:         return $phone;
 93:     }
