  5: namespace App\Services\Auth;
  6: 
  7: use App\Enums\CustomerStatus;
  8: use App\Exceptions\BusinessException;
  9: use App\Models\Customer;
 10: use App\Models\CustomerAuditLog;
 11: use App\Models\SupplierUser;
 12: use App\Models\User;
 13: use App\Services\CustomerAuthService;
 14: use Illuminate\Support\Facades\Hash;
 15: use Illuminate\Support\Facades\RateLimiter;
 16: use Symfony\Component\HttpKernel\Exception\TooManyRequestsHttpException;
 17: 
 18: final class UnifiedAuthService
 19: {
 20:     public function __construct(private readonly CustomerAuthService $customerAuth) {}
 21: 
 22:     public function attempt(string $login, string $password): User|SupplierUser|Customer
 23:     {
 24:         $identifier = str_contains($login, '@') ? mb_strtolower(trim($login)) : Customer::normalizePhone($login);
 25:         $key = 'unified-login:failures:'.hash_hmac('sha256', $identifier, (string) config('app.key'));
 26:         $ipKey = 'unified-login:ip-failures:'.hash_hmac('sha256', (string) request()->ip(), (string) config('app.key'));
 27:         $pairKey = $key.':ip:'.hash('sha256', (string) request()->ip()).':hour';
 28:         $dayKey = $key.':day';
 29:         $hourKey = $key.':hour';
 30:         $staff = str_contains($identifier, '@') ? User::query()->whereRaw('LOWER(email) = ?', [$identifier])->first() : null;
 31:         $dayLimit = max(1, (int) config('auth.unified_login_failures_day', 100));
 32:         $hourLimit = max(1, (int) config('auth.unified_login_identifier_failures_hour', 30));
 33:         $pairLimit = max(1, (int) config('auth.unified_login_failures_hour', 10));
 34:         $ipLimit = max(1, (int) config('auth.unified_login_ip_failures_hour', 1000));
 35:         if (RateLimiter::tooManyAttempts($pairKey, $pairLimit)) {
 36:             throw new TooManyRequestsHttpException(RateLimiter::availableIn($pairKey), 'محاولات دخول كثيرة؛ حاول لاحقًا.');
 37:         }
 38:         foreach ([$hourKey => $hourLimit, $dayKey => $dayLimit] as $identityKey => $limit) {
 39:             if (RateLimiter::tooManyAttempts($identityKey, $limit)) {
 40:                 throw new TooManyRequestsHttpException(RateLimiter::availableIn($identityKey), 'محاولات دخول كثيرة؛ حاول لاحقًا.');
 41:             }
 42:         }
 43:         $broadLimitReached = RateLimiter::tooManyAttempts($ipKey, $ipLimit);
 44:         try {
 45:             $actor = $this->resolve($identifier, $password, $staff);
 46:         } catch (BusinessException $exception) {
 47:             if ($exception->status === 401) {
 48:                 RateLimiter::hit($pairKey, 3600);
 49:                 RateLimiter::hit($hourKey, 3600);
 50:                 if (RateLimiter::hit($ipKey, 3600) === $ipLimit) {
 51:                     app(AuthenticationAlerts::class)->report('ip_failures', $staff?->id);
 52:                 }
 53:                 if (RateLimiter::hit($dayKey, 86400) === $dayLimit) {
 54:                     app(AuthenticationAlerts::class)->report('identifier_failures', $staff?->id);
 55:                 }
 56:                 // Broad quotas must not lock out valid credentials behind NAT or CGNAT.
 57:                 if ($broadLimitReached) {
 58:                     throw new TooManyRequestsHttpException(60, 'محاولات دخول كثيرة؛ حاول لاحقًا.');
 59:                 }
 60:             }
 61:             throw $exception;
 62:         }
 63:         RateLimiter::clear($pairKey);
 64: 
 65:         return $actor;
 66:     }
 67: 
 68:     private function resolve(string $login, string $password, ?User $staff = null): User|SupplierUser|Customer
 69:     {
 70:         $login = trim($login);
 71: 
 72:         if (str_contains($login, '@')) {
 73:             $email = mb_strtolower($login);
 74: 
 75:             // H3: bcrypt واحدة ثابتة لكل محاولة بالبريد — نجلب المرشحين من
 76:             // الجداول الثلاثة (استعلامات indexed رخيصة)، ثم نفحص مرشحًا واحدًا
 77:             // بالأولوية (staff ثم supplier ثم customer) أو dummy hash عند غياب
 78:             // الجميع. الفحص الإضافي يحدث فقط في حالة البريد المشترك الشاذة.
 79:             $supplierUser = null; // Supplier accounts are historical; dealers use Customer accounts.
 80:             $customer = Customer::query()
 81:                 ->whereNotNull('email_verified_at')
 82:                 ->whereRaw('LOWER(email) = ?', [$email])
 83:                 ->first();
 84: 
 85:             // L4: رصد أي بريد مشترك بين جدولين — بما فيها العملاء.
 86:             $present = array_values(array_filter([$staff, $supplierUser, $customer]));
 87:             if (count($present) >= 2) {
 88:                 logger()->warning('auth.shared_email', ['identifier_key' => hash_hmac('sha256', $email, (string) config('app.key'))]);
 89:             }
 90: 
 91:             if ($present === []) {
 92:                 Hash::check($password, CustomerAuthService::dummyHash());
 93:                 logger()->info('unified.login', ['result' => 'wrong_password']);
 94: 
 95:                 throw new BusinessException('بيانات الدخول غير صحيحة.', [], 401);
 96:             }
 97: 
 98:             $matched = null;
 99:             foreach ($present as $candidate) {
100:                 if (! Hash::check($password, $candidate->password)) {
101:                     continue;
102:                 }
103:                 if ($candidate instanceof User && (! $candidate->is_active || $candidate->is_system)) {
104:                     logger()->info('staff.login', ['user_id' => $candidate->id, 'ip' => request()->ip(), 'result' => 'inactive']);
105: 
106:                     continue;
107:                 }
108:                 if ($candidate instanceof SupplierUser && (! $candidate->is_active || $candidate->supplier_id === null
109:                     || $candidate->supplier?->is_active !== true)) {
