176:     private function rehashIfNeeded(User|SupplierUser $model, string $password): void
177:     {
178:         if (Hash::needsRehash($model->password)) {
179:             $original = $model->password;
180:             $replacement = Hash::make($password);
181:             // A rehash must never overwrite an administrator's concurrent password reset.
182:             if ($model->newQuery()->whereKey($model->id)->where('password', $original)->update(['password' => $replacement]) !== 1) {
183:                 throw new BusinessException('بيانات الدخول غير صحيحة.', [], 401);
184:             }
185:             // Keep the exact credential snapshot just verified; a later reset invalidates its handoff.
186:             $model->forceFill(['password' => $replacement])->syncOriginalAttribute('password');
187:         }
