 56:             'city' => ['id' => $city->id, 'name_ar' => $city->name_ar, 'name_en' => $city->name_en],
 57:             'cart_total' => $totals['total'],
 58:             'options' => [[
 59:                 'key' => 'standard',
 60:                 'label' => 'شحن قياسي',
 61:                 'cost' => $cost,
 62:                 'cod_fee' => $quote['cod_fee'],
