43:             'price' => $display['price'] ?? null,
44:             'default_variant_id' => $display['variant_id'] ?? null,
45:             'old_price' => $display !== null && $display['compare_at'] !== null && $display['compare_at'] > $display['price']
46:                 ? $display['compare_at'] : null,
47:             'discount_percentage' => $display['discount_percentage'] ?? null,
48:             'is_featured' => (bool) $this->is_featured,
49:             // F19: لا نكشف أرقام المبيعات الدقيقة للعامة — الواجهة لا
50:             // تستخدمها (toCardVM يتجاهلها).
51:             'in_stock' => $available > 0,
52:             'is_new' => $this->published_at !== null
53:                 && $this->published_at->gte(now()->subDays((int) config('storefront.new_days', 30))),
54:             'badge_en' => $this->badge_en,
55:             'badge_ar' => $this->badge_ar,
56:             'colors' => $this->relationLoaded('variants')
57:                 ? $this->variants
58:                     ->filter(fn ($v) => filled($v->color_name_en) || filled($v->color_hex))
59:                     ->unique(fn ($v) => mb_strtolower((string) $v->color_name_en).'|'.$v->color_hex)
60:                     ->map(fn ($v) => ['name_en' => $v->color_name_en, 'name_ar' => $v->color_name_ar, 'hex' => $v->color_hex])
61:                     ->values()->all()
62:                 : [],
63:         ];
64:     }
65: }  1: 'use client';
  2: import { resolveServiceUrl } from '@alfarid/api-client';
  3: import { useBranding, BrandLogo } from '@alfarid/ui/branding';
  4: import React, { useState, useEffect, useRef, useCallback } from 'react';
  5: import { useRouter, useSearchParams } from 'next/navigation';
  6: import '../../styles/luxuryAuth.css';
  7: import { BIRKIN_IMG_DATA } from '../../assets/birkinHalftone';
  8: import { useAuthStore } from '@/store/auth.store';
  9: import { loginUnified } from '@/services/auth.service';
 10: import { AccountForm, type AuthView } from './AccountForm';
 11: import { createSessionNonce } from './session-nonce';
 12: 
 13: export const LoginScreen: React.FC<{ initialView?: AuthView }> = ({ initialView = 'login' }) => {
 14:   const { branding } = useBranding();
 15:   const [view, setView] = useState<AuthView>(initialView);
 16:   const formRef = useRef<HTMLDivElement>(null);
 17:   const router = useRouter();
 18:   const params = useSearchParams();
 19:   const [lang, setLang] = useState<'en' | 'ar'>('ar');
 20:   const gridStep = 7;
 21:   const [showPassword, setShowPassword] = useState(false);
 22: 
 23:   // Form states
 24:   const [login, setLogin] = useState('');
 25:   const [password, setPassword] = useState('');
 26:   const [isSubmitting, setIsSubmitting] = useState(false);
 27:   const [isReady, setIsReady] = useState(false);
 28:   const [staffCheckPending, setStaffCheckPending] = useState(initialView === 'login');
 29:   const [errors, setErrors] = useState<Record<string, string[]>>({});
 30:   const [formError, setFormError] = useState('');
 31: 
 32:   useEffect(() => {
 33:     setIsReady(true);
 34:     formRef.current?.querySelector('h1')?.focus({ preventScroll: true });
 35:     setErrors({});
 36:     setFormError('');
 37:   }, [view]);
 38: 
 39:   const home = useAuthStore((s) => s.home);
 40:   const token = useAuthStore((s) => s.token);
 41: 
 42:   useEffect(() => {
 43:     if (view !== 'login' || token) {
 44:       setStaffCheckPending(false);
 45:       return;
 46:     }
 47:     const office = new URL(resolveServiceUrl(process.env.NEXT_PUBLIC_BACKOFFICE_URL ?? 'http://localhost:5173'));
 48:     const nonce = createSessionNonce();
 49:     if (!nonce) {
 50:       setStaffCheckPending(false);
 51:       return;
 52:     }
 53:     const frame = document.createElement('iframe');
 54:     frame.style.cssText = 'position:fixed;top:0;left:0;width:1px;height:1px;opacity:0;pointer-events:none;border:0';
 55:     frame.setAttribute('aria-hidden', 'true');
 56:     frame.tabIndex = -1;
 57:     frame.title = 'Session verification';
 58:     frame.src = new URL(`/auth/session#nonce=${encodeURIComponent(nonce)}`, office).href;
 59:     setStaffCheckPending(true);
 60:     const receive = (event: MessageEvent) => {
 61:       if (
 62:         event.origin !== office.origin ||
 63:         event.source !== frame.contentWindow ||
 64:         event.data?.type !== 'alfarid:staff-session' ||
 65:         event.data?.nonce !== nonce
 66:       )
 67:         return;
 68:       if (event.data.authenticated === true) window.location.replace(new URL('/dashboard', office).href);
 69:       else setStaffCheckPending(false);
 70:     };
 71:     window.addEventListener('message', receive);
 72:     document.body.appendChild(frame);
 73:     const timer = window.setTimeout(() => setStaffCheckPending(false), 5000);
 74:     return () => {
 75:       window.clearTimeout(timer);
 76:       window.removeEventListener('message', receive);
 77:       frame.remove();
 78:     };
 79:   }, [view, token]);
 80: 
 81:   // لو المستخدم داخل بالفعل، روح لصفحته الرئيسية
 82:   useEffect(() => {
 83:     if (token && home) router.replace(home);
 84:   }, [token, home, router]);
 85: 
 86:   // Canvas refs
 87:   const canvasRef = useRef<HTMLCanvasElement | null>(null);
 88:   const birkinPixelsRef = useRef<Uint8ClampedArray | null>(null);
 89:   const renderCanvasRef = useRef<() => void>(() => {});
 90:   const mousePosRef = useRef({ x: -1000, y: -1000, isHovering: false });
 91: 
 92:   const W = 560;
 93:   const H = 640;
 94: 
 95:   // Translations
 96:   const t = {
 97:     en: {
 98:       signInTitle: 'Sign In',
 99:       signInSub: `Sign in to your ${branding.name} account`,
100:       loginLabel: 'Email or mobile number',
101:       loginPlaceholder: 'Enter your email or mobile number',
102:       wholesaleRegister: 'Register as a wholesale trader',
103:       handoffExpired: 'The login link has expired, please sign in again.',
104:       passwordLabel: 'Password',
105:       passwordPlaceholder: 'Enter your password',
106:       forgotPassword: 'Forgot Password?',
107:       signInBtn: 'Sign In',
108:       createAccount: 'Create an Account',
109:     },
110:     ar: {
111:       signInTitle: 'تسجيل الدخول',
112:       signInSub: `سجّل الدخول إلى حسابك في ${branding.name}`,
113:       loginLabel: 'البريد الإلكتروني أو رقم الموبايل',
114:       loginPlaceholder: 'أدخل بريدك الإلكتروني أو رقم موبايلك',
115:       wholesaleRegister: 'تسجيل كتاجر جملة',
116:       handoffExpired: 'انتهت صلاحية رابط الدخول، سجّل الدخول مرة أخرى',
117:       passwordLabel: 'كلمة المرور',
118:       passwordPlaceholder: 'أدخل كلمة المرور',
119:       forgotPassword: 'نسيت كلمة المرور؟',
120:       signInBtn: 'تسجيل الدخول',
121:       createAccount: 'إنشاء حساب جديد',
122:     },
123:   }[lang];
124: 
125:   // Canvas drawing routine
126:   const renderCanvas = useCallback(() => {
127:     const canvas = canvasRef.current;
128:     if (!canvas) return;
129:     const ctx = canvas.getContext('2d');
130:     if (!ctx) return;
131: 
132:     ctx.fillStyle = '#ffffff';
133:     ctx.fillRect(0, 0, W, H);
134: 
135:     const activePixels = birkinPixelsRef.current;
136:     if (!activePixels) return;
137: 
138:     const step = gridStep;
139:     const half = step / 2;
140:     const { x: mx, y: my, isHovering: isHover } = mousePosRef.current;
141: 
142:     ctx.fillStyle = '#09090b';
143: 
144:     for (let y = Math.floor(half); y < H; y += step) {
145:       for (let x = Math.floor(half); x < W; x += step) {
146:         const idx = (y * W + x) * 4;
147:         const luma = activePixels[idx] / 255.0;
148:         const dark = 1.0 - luma;
149:         if (dark < 0.06) continue;
150: 
151:         let drawX = x;
152:         let drawY = y;
153:         let scaleBoost = 1.0;
154: 
155:         if (isHover) {
156:           const dx = x - mx;
157:           const dy = y - my;
158:           const dist = Math.sqrt(dx * dx + dy * dy);
159:           if (dist < 110) {
160:             const factor = 1.0 - dist / 110.0;
161:             drawX += (dx / (dist + 1)) * factor * 2.2;
162:             drawY += (dy / (dist + 1)) * factor * 2.2;
163:             scaleBoost = 1.0 + factor * 0.16;
164:           }
165:         }
166: 
167:         const r = Math.pow(dark, 0.92) * (step * 0.68) * scaleBoost;
168:         if (r < 0.45) continue;
169: 
170:         // Diamond dot
171:         ctx.beginPath();
172:         ctx.moveTo(drawX, drawY - r);
173:         ctx.lineTo(drawX + r, drawY);
174:         ctx.lineTo(drawX, drawY + r);
175:         ctx.lineTo(drawX - r, drawY);
176:         ctx.closePath();
177:         ctx.fill();
178: 
179:         // White micro center dot
180:         if (dark > 0.76 && r > 2.4) {
181:           const ir = (dark - 0.74) * (step * 0.3);
182:           if (ir >= 0.7) {
183:             ctx.save();
184:             ctx.fillStyle = '#ffffff';
185:             ctx.beginPath();
186:             ctx.arc(drawX, drawY, ir, 0, Math.PI * 2);
187:             ctx.fill();
188:             ctx.restore();
189:           }
190:         }
191:       }
192:     }
193:   }, []);
194: 
195:   useEffect(() => {
196:     renderCanvasRef.current = renderCanvas;
197:     renderCanvas();
198:   }, [renderCanvas]);
199: 
200:   // Extract pixel buffers on mount
201:   useEffect(() => {
202:     const offCanvas = document.createElement('canvas');
203:     offCanvas.width = W;
204:     offCanvas.height = H;
205:     const offCtx = offCanvas.getContext('2d', { willReadFrequently: true });
206:     if (!offCtx) return;
207: 
208:     const extract = (img: HTMLImageElement) => {
209:       offCtx.fillStyle = '#ffffff';
210:       offCtx.fillRect(0, 0, W, H);
211:       offCtx.drawImage(img, 0, 0, W, H);
212:       return offCtx.getImageData(0, 0, W, H).data;
213:     };
214: 
215:     const bImg = new Image();
216:     bImg.src = BIRKIN_IMG_DATA;
217:     bImg.onload = () => {
218:       birkinPixelsRef.current = extract(bImg);
219:       renderCanvasRef.current();
220:     };
221: 
222:     return () => {
223:       bImg.onload = null;
224:     };
225:   }, []);
226: 
227:   // Pointer tracking
228:   const handlePointerMove = (clientX: number, clientY: number) => {
229:     if (window.matchMedia('(prefers-reduced-motion: reduce)').matches || !window.matchMedia('(hover: hover) and (pointer: fine)').matches) return;
230:     const canvas = canvasRef.current;
231:     if (!canvas) return;
232:     const rect = canvas.getBoundingClientRect();
233:     mousePosRef.current = {
234:       x: ((clientX - rect.left) / rect.width) * W,
235:       y: ((clientY - rect.top) / rect.height) * H,
236:       isHovering: true,
237:     };
238:     requestAnimationFrame(renderCanvas);
239:   };
240: 
241:   const handlePointerLeave = () => {
242:     mousePosRef.current.isHovering = false;
243:     requestAnimationFrame(renderCanvas);
244:   };
245: 
246:   // Login handler
247:   const handleSignIn = async (e: React.FormEvent) => {
248:     e.preventDefault();
249:     if (!isReady || staffCheckPending || isSubmitting) return;
250:     setIsSubmitting(true);
251:     setErrors({});
252:     setFormError('');
253:     try {
254:       const path = await loginUnified(login, password, params.get('redirect'));
255:       if (path) router.replace(path);
256:     } catch (err: any) {
257:       const status = err?.response?.status;
258:       const msg = err?.response?.data?.message;
259:       if (status === 422) setErrors(err.response.data.errors ?? {});
260:       else if (status === 401) setFormError(lang === 'ar' ? 'بيانات الدخول غير صحيحة.' : 'Invalid credentials.');
261:       else if (status === 403) setFormError(msg ?? 'غير مسموح.');
262:       else if (status === 429) {
263:         const s = err.response.headers['retry-after'] ?? 60;
264:         setFormError(lang === 'ar' ? `محاولات كثيرة، حاول بعد ${s} ثانية.` : `Too many attempts, retry in ${s}s.`);
265:       } else setFormError(lang === 'ar' ? 'تعذر الاتصال بالخادم.' : 'Server unreachable.');
266:     } finally {
267:       setIsSubmitting(false);
268:     }
269:   };
270: 
271:   return (
272:     <div className="luxury-auth-page" dir="ltr" data-auth-view={view}>
273:       <main className="luxury-auth-main">
274:         <div className="auth-card">
275:           {/* ================= LEFT COLUMN: AUTHENTICATION ================= */}
276:           <section
277:             id="leftColumn"
278:             dir={lang === 'ar' ? 'rtl' : 'ltr'}
279:             className="luxury-left-col"
280:           >
281:             {/* Top Brand Mark + Language Toggle */}
282:             <div className="luxury-top-bar">
283:               <button
284:                 type="button"
285:                 className="luxury-brand-btn"
286:                 title={branding.name}
287:                 disabled={!isReady || isSubmitting}
288:                 onClick={() => setView('login')}
289:               >
290:                 <BrandLogo className="w-[22px] h-[22px]" fallback={<svg
291:                   width="22"
292:                   height="22"
293:                   viewBox="0 0 24 24"
294:                   fill="none"
295:                   xmlns="http://www.w3.org/2000/svg"
296:                   aria-hidden="true"
297:                 >
298:                   <polygon points="4,10 10,4 10,13 4,19" fill="#09090b" />
299:                   <polygon points="11,11 17,5 17,14 11,20" fill="#09090b" />
300:                 </svg>} />
301:                 <span className="luxury-brand-tag">
302:                   {branding.name}
303:                 </span>
304:               </button>
305: 
306:               <button
307:                 type="button"
308:                 onClick={() => setLang(lang === 'en' ? 'ar' : 'en')}
309:                 className="luxury-lang-btn"
310:                 disabled={!isReady || isSubmitting}
311:                 lang={lang === 'en' ? 'ar' : 'en'}
312:               >
313:                 {lang === 'en' ? 'العربية' : 'English'}
314:               </button>
315:             </div>
316: 
317:             {/* SIGN IN FORM */}
318:             <div className="luxury-form-wrap" ref={formRef}>
319:               {view === 'login' ? (
320:                 <>
321:                   <h1 className="luxury-title" tabIndex={-1}>
322:                     {t.signInTitle}
323:                   </h1>
324:                   <p className="luxury-sub">
325:                     {t.signInSub}
326:                   </p>
327: 
328:                   {params.get('error') === 'handoff' && (
329:                     <p className="luxury-form-error" role="alert">
330:                       {t.handoffExpired}
331:                     </p>
332:                   )}
333: 
334:                   {/* Form */}
335:                   <form method="post" onSubmit={handleSignIn} className="luxury-form">
336:                     <div>
337:                       <label className="luxury-field-label" htmlFor="login">
338:                         {t.loginLabel}
339:                         <span className="luxury-req-mark" aria-hidden="true">*</span>
340:                       </label>
341:                       <input
342:                         id="login"
343:                         name="login"
344:                         type="text"
345:                         inputMode="email"
346:                         autoComplete="username"
347:                         enterKeyHint="next"
348:                         required
349:                         value={login}
350:                         onChange={(e) => setLogin(e.target.value)}
351:                         placeholder={t.loginPlaceholder}
352:                         className="pill-input"
353:                         dir="ltr"
354:                         aria-invalid={!!errors.login?.[0]}
355:                         aria-describedby={errors.login?.[0] ? 'login-error' : undefined}
356:                       />
357:                       {errors.login?.[0] && (
358:                         <p id="login-error" className="luxury-field-error" role="alert">
359:                           {errors.login[0]}
360:                         </p>
361:                       )}
362:                     </div>
363: 
364:                     <div>
365:                       <label className="luxury-field-label" htmlFor="password">
366:                         {t.passwordLabel}
367:                         <span className="luxury-req-mark" aria-hidden="true">*</span>
368:                       </label>
369:                       <div className="luxury-pwd-wrap">
370:                         <input
371:                           id="password"
372:                           name="password"
373:                           type={showPassword ? 'text' : 'password'}
374:                           autoComplete="current-password"
375:                           enterKeyHint="done"
376:                           required
377:                           value={password}
378:                           onChange={(e) => setPassword(e.target.value)}
379:                           placeholder={t.passwordPlaceholder}
380:                           className="pill-input pr-pwd"
381:                           aria-invalid={!!errors.password?.[0]}
382:                           aria-describedby={errors.password?.[0] ? 'password-error' : undefined}
383:                         />
384:                         <button
385:                           type="button"
386:                           onClick={() => setShowPassword(!showPassword)}
387:                           className="luxury-eye-btn"
388:                           aria-label={
389:                             lang === 'ar'
390:                               ? showPassword
391:                                 ? 'إخفاء كلمة المرور'
392:                                 : 'إظهار كلمة المرور'
393:                               : showPassword
394:                                 ? 'Hide password'
395:                                 : 'Show password'
396:                           }
397:                           aria-pressed={showPassword}
398:                         >
399:                           <svg
400:                             width="16"
401:                             height="16"
402:                             viewBox="0 0 24 24"
403:                             fill="none"
404:                             stroke="currentColor"
405:                             strokeWidth="1.8"
406:                             strokeLinecap="round"
407:                             strokeLinejoin="round"
408:                           >
409:                             {showPassword ? (
410:                               <>
411:                                 <path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24" />
412:                                 <line x1="1" y1="1" x2="23" y2="23" />
413:                               </>
414:                             ) : (
415:                               <>
416:                                 <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z" />
417:                                 <circle cx="12" cy="12" r="3" />
418:                               </>
419:                             )}
420:                           </svg>
421:                         </button>
422:                       </div>
423:                       {errors.password?.[0] && (
424:                         <p id="password-error" className="luxury-field-error" role="alert">
425:                           {errors.password[0]}
426:                         </p>
427:                       )}
428:                     </div>
429: 
430:                     {formError && (
431:                       <p className="luxury-form-error" role="alert">
432:                         {formError}
433:                       </p>
434:                     )}
435: 
436:                     <div style={{ paddingTop: '4px' }}>
437:                       <button
438:                         type="submit"
439:                         disabled={!isReady || staffCheckPending || isSubmitting}
440:                         className="pill-btn-primary"
441:                       >
442:                         {isSubmitting ? (
443:                           <span>{lang === 'ar' ? 'جاري التحقق...' : 'Signing in...'}</span>
444:                         ) : (
445:                           <span>{t.signInBtn}</span>
446:                         )}
447:                       </button>
448:                     </div>
449:                   </form>
450: 
451:                   {/* Bottom links in Thumb Reach Zone */}
452:                   <div className="luxury-bottom-switch">
453:                     <button
454:                       type="button"
455:                       disabled={!isReady || isSubmitting}
456:                       onClick={() => setView('forgot-password')}
457:                       className="luxury-switch-link"
458:                     >
459:                       {t.forgotPassword}
460:                     </button>
461:                     <span className="luxury-link-sep">·</span>
462:                     <button
463:                       type="button"
464:                       disabled={!isReady || isSubmitting}
465:                       onClick={() => setView('register')}
466:                       className="luxury-switch-link"
467:                     >
468:                       {t.createAccount}
469:                     </button>
470:                     <span className="luxury-link-sep">·</span>
471:                     <button
472:                       type="button"
473:                       disabled={!isReady || isSubmitting}
474:                       onClick={() => setView('wholesale-register')}
475:                       className="luxury-switch-link"
476:                     >
477:                       {t.wholesaleRegister}
478:                     </button>
479:                   </div>
480:                 </>
481:               ) : (
482:                 <AccountForm
483:                   key={view}
484:                   view={view}
485:                   lang={lang}
486:                   onChangeView={setView}
487:                   initialIdentifier={params.get('email') ?? params.get('phone') ?? login}
488:                   initialToken={params.get('token') ?? ''}
489:                 />
490:               )}
491:             </div>
492:           </section>
493: 
494:           {/* ================= RIGHT COLUMN: LUXURY HANDBAG HALFTONE ARTWORK ================= */}
495:           <section
496:             className="luxury-right-col"
497:             aria-label={lang === 'ar' ? 'حقيبة بيركن بتقنية الهالفتون' : 'Birkin Halftone artwork'}
498:           >
499:             <canvas
500:               ref={canvasRef}
501:               width={W}
502:               height={H}
503:               aria-hidden="true"
504:               onMouseMove={(e) => handlePointerMove(e.clientX, e.clientY)}
505:               onMouseLeave={handlePointerLeave}
506:               onTouchMove={(e) => {
507:                 if (e.touches && e.touches[0]) {
508:                   handlePointerMove(e.touches[0].clientX, e.touches[0].clientY);
509:                 }
510:               }}
511:             />
512:           </section>
513:         </div>
514:       </main>
515:     </div>
516:   );
517: };
