519: export default LoginScreen;  1: export * from './inventory';
  2: 
  3: export interface ApiResponse<T = any> {
  4:   success?: boolean;
  5:   message?: string;
  6:   data: T;
  7:   meta?: {
  8:     current_page?: number;
  9:     last_page?: number;
 10:     per_page?: number;
 11:     total?: number;
 12:     from?: number;
 13:     to?: number;
 14:   };
 15: }
 16: 
 17: export interface PaginatedResponse<T = any> {
 18:   data: T[];
 19:   current_page: number;
 20:   last_page: number;
 21:   per_page: number;
 22:   total: number;
 23:   from?: number;
 24:   to?: number;
 25: }
 26: 
 27: export interface ApiErrorResponse {
 28:   message: string;
 29:   errors?: Record<string, string[]>;
 30:   status_code?: number;
 31: }
 32: 
 33: export interface UserPermissions {
 34:   id: number;
 35:   name: string;
 36:   email: string;
 37:   roles: string[];
 38:   permissions: string[];
 39: }
 40: 
 41: export interface AdminCategory {
 42:   id: number;
 43:   parent_id: number | null;
 44:   name_ar: string;
 45:   name_en: string;
 46:   slug: string;
 47:   description_ar: string | null;
 48:   description_en: string | null;
 49:   sort_order: number;
