  5: namespace App\Services;
  6: 
  7: use App\Enums\OrderStatus;
  8: use App\Exceptions\BusinessException;
  9: use App\Models\Cart;
 10: use App\Models\Coupon;
 11: use App\Models\CouponUsage;
 12: use App\Models\Customer;
 13: use App\Models\Order;
 14: use Illuminate\Support\Facades\DB;
 15: use Illuminate\Support\Facades\RateLimiter;
 16: 
 17: /**
 18:  * التحقق من الكوبونات وربطها بالسلة وحساب خصمها وتسجيل استخدامها.
 19:  * الفحوص: التفعيل، النافذة الزمنية، الحد الكلي للاستخدام، حد العميل
 20:  * الواحد (usage_limit_per_customer — افتراضي 1)، والحد الأدنى للسلة.
 21:  * الخصم النسبي: min(subtotal × value/100, max_discount_amount).
 22:  * كوبون free_shipping خصمه المالي على البضاعة صفر — أثره إلغاء الشحن
 23:  * عند إتمام الشراء (يُسجل مبلغ الشحن المُعفى في سجل الاستخدام).
 24:  */
 25: class CouponService
 26: {
 27:     // رسالة موحّدة لعدم صلاحية الكود (F-24): «غير موجود» و«موجود لكن غير
 28:     // قابل للاستخدام» يجب ألا يتيحا تمييز وجود الكود بالتخمين
 29:     private const NOT_REDEEMABLE = 'كود الخصم غير صحيح أو غير متاح أو انتهت صلاحيته أو استُنفد حد استخدامه.';
 30: 
 31:     public function validateAndApply(Cart $cart, string $code, float $subtotal, ?Customer $customer = null): float
 32:     {
 33:         $coupon = $this->findRedeemable($code, $subtotal, $customer);
 34:         $this->enforceRateLimit($coupon, 'apply');
 35: 
 36:         $cart->update(['coupon_id' => $coupon->id]);
 37: 
 38:         return $this->discountFor($coupon, $subtotal);
 39:     }
 40: 
 41:     /**
 42:      * حد معدّل لكل (كوبون + IP) (H3): بديل آمن عن السقف العالمي لطلبات
 43:      * الزوار المعلّقة الذي كان مهاجم واحد يُعطّل به الحملة على كل الزوار.
 44:      * يُستدعى عند التطبيق وعند إتمام الشراء.
 45:      */
 46:     public function enforceRateLimit(Coupon $coupon, string $action = 'apply'): void
 47:     {
 48:         $max = (int) config('store.coupon_apply_per_minute', 20);
 49:         if ($max <= 0) {
 50:             return;
 51:         }
 52: 
 53:         $key = 'coupon:'.$action.':'.$coupon->id.':'.(request()->ip() ?? 'unknown');
 54:         if (RateLimiter::tooManyAttempts($key, $max)) {
 55:             throw new BusinessException(self::NOT_REDEEMABLE, [], 429);
 56:         }
 57:         RateLimiter::hit($key, 60);
 58:     }
 59: 
 60:     /** يتحقق من كوبون مرتبط بسلة (عند إتمام الشراء) ويرجعه أو يرمي استثناءً. */
 61:     public function redeemableById(int $couponId, float $subtotal, ?Customer $customer = null, ?string $guestPhone = null): Coupon
 62:     {
 63:         $coupon = Coupon::query()->find($couponId);
 64:         if ($coupon === null) {
 65:             throw new BusinessException(self::NOT_REDEEMABLE);
 66:         }
 67:         $this->assertRedeemable($coupon, $subtotal, $customer, $guestPhone);
 68: 
 69:         return $coupon;
 70:     }
 71: 
 72:     /** خصم البضاعة: النسبي بسقف، والثابت بحد الإجمالي، والشحن المجاني صفر هنا. */
 73:     public function discountFor(Coupon $coupon, float $subtotal): float
 74:     {
 75:         if ($subtotal <= 0 || $coupon->type === 'free_shipping') {
 76:             return 0.0;
 77:         }
 78: 
 79:         $discount = $coupon->type === 'percentage'
 80:             ? $subtotal * (float) $coupon->value / 100
 81:             : (float) $coupon->value;
 82: 
 83:         if ($coupon->max_discount_amount !== null) {
 84:             $discount = min($discount, (float) $coupon->max_discount_amount);
 85:         }
 86: 
 87:         return round(min($discount, $subtotal), 2);
 88:     }
 89: 
 90:     /**
 91:      * تسجيل استخدام فعلي عند إتمام الطلب + تحديث العداد الكلي ذرّيًا (F4).
 92:      * قفل استشاري على (الكوبون + هوية المستخدم) يمنع سباق الحد الفردي،
 93:      * والزيادة الشرطية على العداد الكلي تمنع تجاوز usage_limit حتى بلا
 94:      * قفل صف الكوبون على مسار الشراء (أُزيل القفل المسبق من OrderService).
 95:      */
 96:     public function recordUsage(Coupon $coupon, Order $order, ?Customer $customer, float $discountAmount): CouponUsage
 97:     {
 98:         $guestPhoneNormalized = $customer === null && $order->guest_phone !== null
 99:             ? Customer::normalizePhone($order->guest_phone)
100:             : null;
101: 
102:         $identity = $customer !== null
103:             ? 'customer:'.$customer->id
104:             : 'phone:'.($guestPhoneNormalized ?? 'anonymous');
105:         DB::statement('SELECT pg_advisory_xact_lock(hashtext(?))', ['coupon-usage:'.$coupon->id.':'.$identity]);
106: 
107:         // إعادة التحقق الفردي تحت القفل: استخدامان متزامنان لنفس الهوية
108:         // يتسلسلان فيرى الثاني استخدام الأول
109:         $this->assertPerIdentityAllowed($coupon, $customer, $guestPhoneNormalized);
110: 
111:         $incremented = Coupon::query()
112:             ->whereKey($coupon->id)
113:             ->where(fn ($q) => $q->whereNull('usage_limit')->orWhereColumn('used_count', '<', 'usage_limit'))
114:             ->increment('used_count');
115:         if ($incremented === 0) {
116:             throw new BusinessException(self::NOT_REDEEMABLE);
117:         }
118: 
119:         return CouponUsage::create([
120:             'coupon_id' => $coupon->id,
121:             'customer_id' => $customer?->id,
122:             'order_id' => $order->id,
123:             'discount_amount' => $discountAmount,
124:             // هاتف الزائر الموحد يُخزَّن مع الاستخدام لفحص الحد لاحقًا في SQL (F-04)
125:             'guest_phone_normalized' => $guestPhoneNormalized,
126:         ]);
127:     }
128: 
129:     private function findRedeemable(string $code, float $subtotal, ?Customer $customer): Coupon
130:     {
131:         $coupon = Coupon::query()->where('code', strtoupper(trim($code)))->first();
132:         if ($coupon === null) {
133:             throw new BusinessException(self::NOT_REDEEMABLE);
134:         }
135:         $this->assertRedeemable($coupon, $subtotal, $customer);
136: 
137:         return $coupon;
138:     }
139: 
140:     private function assertRedeemable(Coupon $coupon, float $subtotal, ?Customer $customer, ?string $guestPhone = null): void
141:     {
142:         if (! $coupon->isRedeemableNow()) {
143:             throw new BusinessException(self::NOT_REDEEMABLE);
144:         }
145:         // رسالة موحّدة (F20): لا تُفصح عن سبب الرفض فيُستخدم لتمييز السياسات
146:         if ($coupon->min_order_amount !== null && $subtotal < (float) $coupon->min_order_amount) {
147:             throw new BusinessException(self::NOT_REDEEMABLE);
148:         }
149: 
150:         $guestPhoneNormalized = ($guestPhone !== null && trim($guestPhone) !== '')
151:             ? Customer::normalizePhone($guestPhone)
152:             : null;
153: 
154:         // (H3) أُزيل السقف العالمي لطلبات الزوار المعلّقة: كان مهاجم واحد
155:         // ينشئ حدًا من الطلبات الوهمية فيعطّل الحملة على كل زائر شرعي. الحماية
156:         // الآن: حد لكل هوية (أدناه) + حد معدّل لكل كوبون/IP + تقصير مهلة
157:         // المعلّق — حماية أضعف ضد تدوير الأرقام عبر IPs لكنها لا تعطّل الحملة.
158:         $this->assertPerIdentityAllowed($coupon, $customer, $guestPhoneNormalized);
159:     }
160: 
161:     /**
162:      * حد الاستخدام لكل هوية (عميل/رقم زائر) — الطلبات الملغاة لا تحتسب.
163:      * limit <= 0 يعني بلا حد فردي.
164:      */
165:     private function assertPerIdentityAllowed(Coupon $coupon, ?Customer $customer, ?string $guestPhoneNormalized): void
166:     {
167:         $limit = (int) $coupon->usage_limit_per_customer;
168:         if ($limit <= 0) {
169:             return;
170:         }
171: 
172:         if ($customer !== null) {
173:             $usedByCustomer = $coupon->usages()
174:                 ->where('customer_id', $customer->id)
175:                 ->whereHas('order', fn ($q) => $q->where('status', '!=', OrderStatus::Cancelled->value))
176:                 ->count();
177:             if ($usedByCustomer >= $limit) {
178:                 throw new BusinessException(self::NOT_REDEEMABLE);
179:             }
180: 
181:             return;
182:         }
183: 
184:         if ($guestPhoneNormalized !== null) {
185:             // هوية الزائر هي رقم هاتفه الموحد — تبديل cart_token لا يتجاوز
186:             // الحد (H3)، والعدّ في SQL على العمود المفهرس (F-04)
187:             $usedByPhone = $coupon->usages()
188:                 ->where('guest_phone_normalized', $guestPhoneNormalized)
189:                 ->whereHas('order', fn ($q) => $q->where('status', '!=', OrderStatus::Cancelled->value))
190:                 ->count();
191:             if ($usedByPhone >= $limit) {
192:                 throw new BusinessException(self::NOT_REDEEMABLE);
193:             }
194:         }
195:     }
