 24: /**
 25:  * كتالوج المتجر للقراءة: استعلامات التصفح والفلترة وحساب المتاح أونلاين.
 26:  * المتاح أونلاين = مجموع available (on_hand − reserved − damaged) في الفروع
 27:  * النشطة فقط، بحساب SQL مجمّع (بلا تحميل صفوف في الذاكرة).
 28:  * «منتج نشط» في المتجر = منشور (published).
 29:  */
 30: class StoreCatalogService
 31: {
 32:     public const HOME_CACHE_KEY = 'store_home_data:v2';
 33: 
 34:     /** L4: per-request memo so facets/index resolve the category only once. */
 35:     private array $categoryMemo = [];
 36: 
 37:     private array $descendantMemo = [];
 38: 
 39:     public function __construct(private readonly PricingService $pricing) {}
 40: 
 41:     // ------------------------------------------------------------------ متاح
 42: 
 43:     /**
 44:      * شرط "الموقع القابل للبيع" الوحيد في الكتالوج: الفرع نشط، والموقع إما
 45:      * معدوم أو نشط من نوع قابل للبيع — receiving (لم تصل للرف بعد) وdamaged
 46:      * (تالفة لا تُشحن) مستبعدان معًا (F5).
 47:      */
 48:     private function sellableLocationRule(object $query): void
 49:     {
 50:         $query->where('branches.is_active', true)
 51:             ->where(fn ($q) => $q->whereNull('stock_levels.location_id')
 52:                 ->orWhere(fn ($l) => $l->where('locations.is_active', true)->whereNotIn('locations.type', ['receiving', 'damaged'])));
 53:     }
 54: 
 55:     /** EXISTS صف قابل للبيع لمنتج: نفس قاعدة المواقع القابلة للبيع (F5). */
 56:     private function sellableExists(object $sub): void
 57:     {
 58:         $sub->select(DB::raw(1))
 59:             ->from('stock_levels')
 60:             ->join('product_variants', 'product_variants.id', '=', 'stock_levels.product_variant_id')
 61:             ->join('branches', 'branches.id', '=', 'stock_levels.branch_id')
 62:             ->leftJoin('locations', 'locations.id', '=', 'stock_levels.location_id');
 63:         $this->sellableLocationRule($sub);
 64:         $sub->where('product_variants.is_active', true)
 65:             ->whereNull('product_variants.deleted_at')
 66:             ->whereColumn('product_variants.product_id', 'products.id')
 67:             ->where('stock_levels.available', '>', 0);
 68:     }
 69: 
 70:     /** إرفاق store_available بأي استعلام منتجات: مجموع متاح كل متغيراته في الفروع النشطة. */
 71:     public function withStoreAvailability(Builder $query): Builder
 72:     {
 73:         // L9: sellable stock only — active branches, active sellable locations
 74:         // (receiving bins are not on the shelf yet, damaged bins are not shippable).
 75:         $sub = DB::table('stock_levels')
 76:             ->join('product_variants', 'product_variants.id', '=', 'stock_levels.product_variant_id')
 77:             ->join('branches', 'branches.id', '=', 'stock_levels.branch_id')
 78:             ->leftJoin('locations', 'locations.id', '=', 'stock_levels.location_id');
 79:         $this->sellableLocationRule($sub);
 80:         $sub->where('product_variants.is_active', true)
 81:             ->whereNull('product_variants.deleted_at')
 82:             ->whereColumn('product_variants.product_id', 'products.id')
 83:             ->selectRaw('COALESCE(SUM(stock_levels.available), 0)');
 84: 
 85:         return $query->select('products.*')->selectSub($sub, 'store_available');
 86:     }
 87: 
 88:     /**
 89:      * خريطة متاح لمتغيرات بعينها في استعلام واحد مجمّع.
 90:      *
 91:      * @param  list<int>  $variantIds
 92:      * @return array<int, float>
 93:      */
 94:     public function availabilityMap(array $variantIds): array
 95:     {
 96:         if ($variantIds === []) {
 97:             return [];
 98:         }
 99: 
100:         // L9: same sellable-stock rule as withStoreAvailability.
101:         $query = StockLevel::query()
102:             ->join('branches', 'branches.id', '=', 'stock_levels.branch_id')
103:             ->leftJoin('locations', 'locations.id', '=', 'stock_levels.location_id');
104:         $this->sellableLocationRule($query);
105: 
106:         return $query
107:             ->whereIn('stock_levels.product_variant_id', $variantIds)
108:             ->groupBy('stock_levels.product_variant_id')
109:             ->selectRaw('stock_levels.product_variant_id, COALESCE(SUM(stock_levels.available), 0) as total')
110:             ->pluck('total', 'product_variant_id')
111:             ->map(fn ($v) => (float) $v)
112:             ->all();
113:     }
114: 
115:     // ------------------------------------------------------------------ أساس
116: 
117:     /** استعلام المنتجات المنشورة بعلاقات البطاقة والمتاح المجمّع. */
118:     public function publishedQuery(): Builder
119:     {
120:         $query = Product::query()
121:             ->where('status', ProductStatus::Published)
122:             ->whereIn('sales_channel', [SalesChannel::Retail, SalesChannel::Both])
123:             ->whereHas('category', fn ($q) => $q->where('is_active', true)
124:                 ->where(fn ($path) => $path->whereNull('parent_id')
125:                     ->orWhereHas('parent', fn ($parent) => $parent->where('is_active', true)
126:                         ->where(fn ($path) => $path->whereNull('parent_id')
127:                             ->orWhereHas('parent', fn ($ancestor) => $ancestor->where('is_active', true)->whereNull('parent_id'))))))
128:             ->with([
129:                 'category', 'media',
130:                 'variants' => fn ($q) => $this->withVariantAvailability($this->pricing->withStorePrice($q->getQuery(), $this->customer()))
131:                     ->where('is_active', true)->with('media')->orderBy('sort_order')->orderBy('id'),
132:             ]);
133: 
134:         return $this->withStoreAvailability($query);
135:     }
136: 
137:     private function withVariantAvailability(Builder $query): Builder
138:     {
139:         $stock = DB::table('stock_levels')
140:             ->join('branches', 'branches.id', '=', 'stock_levels.branch_id')
141:             ->leftJoin('locations', 'locations.id', '=', 'stock_levels.location_id');
142:         $this->sellableLocationRule($stock);
143: 
144:         return $query->selectSub($stock->whereColumn('stock_levels.product_variant_id', 'product_variants.id')
145:             ->selectRaw('COALESCE(SUM(stock_levels.available), 0)'), 'store_available');
146:     }
147: 
148:     // ------------------------------------------------------------------ فلاتر
149: 
150:     /**
151:      * تطبيق فلاتر قائمة المنتجات (ProductFilterRequest) على الاستعلام.
152:      *
153:      * @param  array<string, mixed>  $filters
154:      */
155:     public function applyFilters(Builder $query, array $filters): Builder
156:     {
157:         if (! empty($filters['category'])) {
158:             $category = $this->resolveCategory($filters['category']);
159:             if ($category !== null) {
160:                 $query->whereIn('products.category_id', [$category->id, ...$this->cachedDescendantIds($category)]);
161:             } else {
162:                 $query->whereRaw('1 = 0'); // قسم غير موجود = نتيجة فارغة لا خطأ
163:             }
164:         }
165: 
166:         if (! empty($filters['color'])) {
167:             $color = $filters['color'];
168:             $query->whereHas('variants', fn ($q) => $q->where('is_active', true)
169:                 ->where(fn ($inner) => $inner
170:                     ->whereRaw('LOWER(color_name_en) = LOWER(?)', [$color])
171:                     ->orWhere('color_name_ar', $color)));
172:         }
173: 
174:         if (isset($filters['price_min']) || isset($filters['price_max']) || in_array($filters['sort'] ?? null, ['price_asc', 'price_desc'], true)) {
175:             $query->leftJoinLateral($this->minimumPriceQuery(), 'catalog_price');
176:             if (isset($filters['price_min'])) {
177:                 $query->where('catalog_price.minimum_price', '>=', $filters['price_min']);
178:             }
179:             if (isset($filters['price_max'])) {
180:                 $query->where('catalog_price.minimum_price', '<=', $filters['price_max']);
181:             }
182:         }
183: 
184:         // stock_levels_valid_balances enforces available >= 0 in PostgreSQL,
185:         // so a positive row is equivalent to a positive sum on the card.
186:         if (! empty($filters['in_stock'])) {
187:             $query->whereExists(fn ($sub) => $this->sellableExists($sub));
188:         }
189: 
190:         if (! empty($filters['occasions'])) {
191:             $query->where(function (Builder $q) use ($filters) {
192:                 foreach ($filters['occasions'] as $occasion) {
193:                     $q->orWhereJsonContains('products.occasions', $occasion);
194:                 }
195:             });
196:         }
197: 
198:         if (! empty($filters['search'])) {
199:             $term = SearchTerm::pattern(mb_strtolower(trim($filters['search'])));
200:             $query->where(fn (Builder $q) => $q
201:                 ->whereRaw('LOWER(products.name_en) LIKE ?', [$term])
202:                 ->orWhereRaw('LOWER(products.name_ar) LIKE ?', [$term])
203:                 ->orWhereHas('variants', fn ($v) => $v->where('is_active', true)->whereRaw('LOWER(sku) LIKE ?', [$term])));
204:         }
205: 
206:         return $this->applySort($query, $filters['sort'] ?? 'featured');
207:     }
208: 
209:     public function applySort(Builder $query, string $sort): Builder
210:     {
211:         if (in_array($sort, ['price_asc', 'price_desc'], true)) {
212:             return $query->orderByRaw('catalog_price.minimum_price '.($sort === 'price_asc' ? 'ASC' : 'DESC').' NULLS LAST')
213:                 ->orderBy('products.id');
214:         }
215: 
216:         return match ($sort) {
217:             'featured' => $query->orderByDesc('products.is_featured')
218:                 ->orderByDesc('products.sales_count')
219:                 ->orderByDesc('products.created_at')
220:                 ->orderByDesc('products.id'),
221:             'name' => $query->orderByRaw("COALESCE(NULLIF(products.name_en, ''), products.name_ar) ASC")
222:                 ->orderByDesc('products.id'),
223:             'best_selling' => $query->orderByDesc('products.sales_count')->orderByDesc('products.id'),
224:             default => $query->orderByDesc('products.created_at')->orderByDesc('products.id'),
225:         };
226:     }
227: 
228:     private function resolveCategory(int|string $value): ?Category
229:     {
230:         // L4: one lookup per distinct value per request.
231:         $key = 'c:'.((string) $value);
232:         if (array_key_exists($key, $this->categoryMemo)) {
233:             return $this->categoryMemo[$key];
234:         }
235:         $category = Category::query()->where('is_active', true)->where('slug', $value)->first();
236: 
237:         return $this->categoryMemo[$key] = $category ?? (ctype_digit((string) $value) && strlen((string) $value) <= 18
238:             ? Category::query()->where('is_active', true)->find((int) $value) : null);
239:     }
240: 
241:     /** L4: descendant ids memoized per category per request. */
242:     private function cachedDescendantIds(Category $category): array
243:     {
244:         return $this->descendantMemo[$category->id] ??= $category->descendantIds();
245:     }
246: 
247:     // ------------------------------------------------------------------ أسعار العرض
248: 
249:     /**
250:      * F23: معادلة الخصم الوحيدة في المتجر — تُستخدم في البطاقة والتفاصيل
251:      * معًا بدل تكرارها. (الصيغة الصحيحة: التقريب بعد الضرب في 100.)
252:      */
253:     public static function discountPercentage(float $unitPrice, float $basis): ?int
254:     {
255:         if ($basis <= $unitPrice) {
256:             return null;
257:         }
258:         $percentage = (int) round((1 - $unitPrice / $basis) * 100);
259: 
260:         return $percentage >= 1 ? $percentage : null;
261:     }
262: 
263:     /**
264:      * سعر عرض بطاقة المنتج: أرخص متغير نشط قابل للتسعير عبر PricingService
265:      * (متغير بلا سعر ولا قائمة يُتخطى بدل كسر القائمة كلها).
266:      *
267:      * @return array{price: float, base_price: float, compare_at: float|null, discount_percentage: int|null, variant_id: int}|null
268:      */
269:     public function displayPrice(Product $product, ?Customer $customer, ?array $availability = null): ?array
270:     {
271:         $variants = $product->relationLoaded('variants')
272:             ? $product->variants
273:             : $product->variants()->where('is_active', true)->orderBy('sort_order')->get();
274: 
275:         // F18: السعر الظاهر والمتغير الافتراضي يفضّلان متغيرًا متوفرًا —
276:         // الإضافة السريعة للسلة من البطاقة يجب ألا تستهدف صنفًا نافدًا.
277:         // بلا خريطة توفر يُستخدم الأرخص كما قبل.
278:         $availability ??= $variants->every(fn ($variant) => array_key_exists('store_available', $variant->getAttributes()))
279:             ? $variants->mapWithKeys(fn ($variant) => [$variant->id => (float) $variant->store_available])->all()
280:             : $this->availabilityMap($variants->pluck('id')->all());
281: 
282:         $best = null;
283:         $bestInStock = null;
284:         foreach ($variants as $variant) {
285:             try {
286:                 $resolved = $this->variantPrice($variant, $customer);
287:             } catch (BusinessException) {
288:                 continue;
289:             }
290: 
291:             $price = (float) $resolved['unit_price'];
292:             $compareAt = $variant->compare_at_price !== null ? (float) $variant->compare_at_price : null;
293:             $basis = max((float) $compareAt, (float) $resolved['base_price']);
294:             $discount = self::discountPercentage($price, $basis);
295: 
296:             $display = [
297:                 'price' => $price,
298:                 'base_price' => (float) $resolved['base_price'],
299:                 'compare_at' => $discount !== null ? $basis : null,
300:                 'discount_percentage' => $discount,
301:                 'variant_id' => $variant->id,
302:             ];
303:             if ($best === null || $price < $best['price']) {
304:                 $best = $display;
305:             }
306:             $inStock = $availability === null || ($availability[$variant->id] ?? 0) > 0;
307:             if ($inStock && ($bestInStock === null || $price < $bestInStock['price'])) {
308:                 $bestInStock = $display;
309:             }
310:         }
311: 
312:         return $bestInStock ?? $best;
313:     }
314: 
315:     public function customer(): ?Customer
316:     {
317:         $user = auth('sanctum')->user();
318: 
319:         return $user instanceof Customer && $user->status === CustomerStatus::Approved ? $user : null;
320:     }
321: 
322:     public function variantPrice(ProductVariant $variant, ?Customer $customer): array
323:     {
324:         if (! array_key_exists('store_price', $variant->getAttributes())) {
325:             return $this->pricing->resolve($variant, $customer, 1);
326:         }
327:         if ($variant->store_price === null) {
328:             throw new BusinessException('الصنف غير مُسعَّر.');
329:         }
330: 
331:         return ['unit_price' => (float) $variant->store_price, 'base_price' => (float) ($variant->getAttributes()['store_base_price'] ?? $this->pricing->basePriceForCustomer($variant, $customer) ?? $variant->store_price)];
332:     }
333: 
334:     private function minimumPriceQuery(): \Illuminate\Database\Query\Builder
335:     {
336:         $customer = $this->customer();
337:         if (! $this->pricing->catalogContext($customer)['public_retail']) {
338:             return $this->liveMinimumPriceQuery($customer);
339:         }
340:         $live = $this->liveMinimumPriceQuery(null);
341: 
342:         // A missing/expired snapshot remains correct before the first warm-up
343:         // or if workers stop. PostgreSQL evaluates only the selected CASE arm.
344:         return DB::query()->selectRaw('CASE WHEN products.catalog_price_refreshed_at > ? THEN products.catalog_min_retail_price ELSE ('.$live->toSql().') END AS minimum_price',
345:             [now()->subMinutes(10), ...$live->getBindings()]);
346:     }
347: 
348:     public function liveMinimumPriceQuery(?Customer $customer): \Illuminate\Database\Query\Builder
349:     {
350:         $variants = $this->withVariantAvailability($this->pricing->withStorePrice(ProductVariant::query(), $customer))
351:             ->where('is_active', true);
352: 
353:         return DB::query()->fromSub($variants, 'priced_variants')
354:             ->selectRaw('COALESCE(MIN(priced_variants.store_price) FILTER (WHERE priced_variants.store_available > 0), MIN(priced_variants.store_price)) AS minimum_price')
355:             ->whereColumn('priced_variants.product_id', 'products.id');
356:     }
357: 
358:     // ------------------------------------------------------------------ فلاتر الواجهة
359: 
360:     /** الـ facets بتتجاهل color والسعر عشان الاختيارات ما تختفيش لما المستخدم يختار واحدة منها */
361:     public function facets(array $filters): array
362:     {
363:         if (! empty($filters['search']) || (string) config('cache.default') === 'array') {
364:             return [...$this->computeStructuralFacets($filters), 'price_ranges' => $this->computePriceRanges($filters)];
365:         }
366:         $key = $this->facetsCacheKey($filters);
367:         $context = $this->pricing->catalogContext($this->customer());
368: 
369:         return [...$this->cachedFacetsPart($key.':structure', fn () => $this->computeStructuralFacets($filters)),
370:             'price_ranges' => $this->cachedFacetsPart($key.':prices:'.hash('sha256', $context['key']), fn () => $this->computePriceRanges($filters))];
371:     }
372: 
373:     private function cachedFacetsPart(string $key, \Closure $load): mixed
374:     {
375:         $flexible = fn () => Cache::flexible($key, [60, 600], $load, ['seconds' => 120]);
376:         if (Cache::has($key)) {
377:             return $flexible();
378:         }
379:         try {
380:             return Cache::lock($key.':build', 120)->block(5, $flexible);
381:         } catch (LockTimeoutException) {
382:             throw new BusinessException('جاري تحديث الفلاتر؛ أعد المحاولة بعد لحظات.', [], 503);
383:         }
384:     }
385: 
386:     /**
387:      * H2: normalize the category to its id so slug/id spellings of the same
388:      * category share one cache entry instead of exploding the key space.
389:      */
390:     private function facetsCacheKey(array $filters): string
391:     {
392:         $base = Arr::only($filters, ['category', 'search', 'occasions', 'in_stock']);
393:         if (! empty($base['category'])) {
394:             $category = $this->resolveCategory($base['category']);
395:             $base['category'] = $category !== null ? 'id:'.$category->id : 'missing';
396:         }
397:         if (isset($base['search'])) {
398:             $base['search'] = mb_strtolower(trim((string) $base['search']));
399:         }
400:         if (isset($base['occasions'])) {
401:             sort($base['occasions']);
402:         }
403:         $base['in_stock'] = ! empty($base['in_stock']);
404:         ksort($base);
405: 
406:         return 'store:facets:v1:'.hash('sha256', json_encode($base, JSON_UNESCAPED_UNICODE));
407:     }
408: 
409:     /** @param array<string, mixed> $filters */
410:     private function computeStructuralFacets(array $filters): array
411:     {
412:         $base = Arr::only($filters, ['category', 'search', 'occasions', 'in_stock']);
413:         $scope = fn (array $extra = []) => $this
414:             ->applyFilters($this->publishedQuery()->withoutEagerLoads(), [...$base, ...$extra])
415:             ->reorder();
416: 
417:         $colors = DB::table('product_variants')
418:             ->whereIn('product_id', $scope()->select('products.id'))
419:             ->where('is_active', true)->whereNull('deleted_at')
420:             ->whereNotNull('color_name_en')->where('color_name_en', '<>', '')
421:             ->groupByRaw('LOWER(color_name_en)')
422:             ->selectRaw('LOWER(color_name_en) AS id, MIN(color_name_en) AS name_en, MIN(color_name_ar) AS name_ar, MIN(color_hex) AS hex, COUNT(DISTINCT product_id) AS count')
423:             ->orderByDesc('count')->orderBy('id')->limit(24)->get()
424:             ->map(fn ($c) => [...(array) $c, 'count' => (int) $c->count]);
425: 
426:         // F13: عدّادات المناسبات في استعلام واحد بدل استعلام لكل مناسبة.
427:         $occasionBase = $this->applyFilters($this->publishedQuery()->withoutEagerLoads(),
428:             Arr::except($base, 'occasions'))->reorder()->select('products.id', 'products.occasions');
429:         $occasionCounts = DB::query()->fromSub($occasionBase->toBase(), 'occasion_scope')
430:             ->selectRaw(collect(Occasion::cases())->map(fn (Occasion $o) => sprintf(
431:                 "COUNT(*) FILTER (WHERE occasion_scope.occasions @> '%s') AS %s",
432:                 json_encode([$o->value]), 'occ_'.$o->value
433:             ))->implode(', '))
434:             ->first();
435:         $occasions = collect(Occasion::cases())->map(fn (Occasion $o) => [
436:             'id' => $o->value,
437:             'count' => (int) ($occasionCounts->{'occ_'.$o->value} ?? 0),
438:         ])->values();
439: 
440:         return [
441:             'total' => $scope()->count('products.id'),
442:             'colors' => $colors,
443:             'occasions' => $occasions,
444:         ];
445:     }
446: 
447:     private function computePriceRanges(array $filters): \Illuminate\Support\Collection
448:     {
449:         $scope = $this->applyFilters($this->publishedQuery()->withoutEagerLoads(), Arr::only($filters, ['category', 'search', 'occasions', 'in_stock']))
450:             ->reorder()->select('products.id')->leftJoinLateral($this->minimumPriceQuery(), 'catalog_price')->addSelect('catalog_price.minimum_price');
451:         $query = DB::query()->fromSub($scope->toBase(), 'price_scope');
452:         foreach (array_values(config('storefront.price_ranges')) as $index => $range) {
453:             $bounds = [];
454:             $bindings = [];
455:             foreach (['min' => '>=', 'max' => '<='] as $bound => $operator) {
456:                 if ($range[$bound] !== null) {
457:                     $bounds[] = 'minimum_price '.$operator.' ?';
458:                     $bindings[] = $range[$bound];
459:                 }
460:             }
461:             $query->selectRaw('COUNT(*) FILTER (WHERE '.($bounds === [] ? 'minimum_price IS NOT NULL' : implode(' AND ', $bounds)).') AS range_'.$index, $bindings);
462:         }
463:         $counts = $query->first();
464: 
465:         return collect(config('storefront.price_ranges'))->values()->map(fn (array $range, int $index) => [
466:             ...$range, 'count' => (int) $counts->{'range_'.$index},
467:         ]);
468:     }
469: 
470:     public function showcaseIds(): array
471:     {
472:         $limit = (int) config('storefront.showcase_limit', 6);
473:         $load = function () use ($limit): array {
474:             $featured = $this->applySort($this->publishedQuery()->withoutEagerLoads()->where('products.is_featured', true), 'featured')
475:                 ->limit($limit)->pluck('products.id')->all();
476:             $fill = count($featured) < $limit
477:                 ? $this->applySort($this->publishedQuery()->withoutEagerLoads()->whereNotIn('products.id', $featured), 'best_selling')
478:                     ->limit($limit - count($featured))->pluck('products.id')->all() : [];
479: 
480:             return [...$featured, ...$fill];
481:         };
482: 
483:         return (string) config('cache.default') === 'array' ? $load()
484:             : Cache::flexible('store:showcase:ids:'.$limit, [300, 1800], $load, ['seconds' => 120]);
485:     }
486: 
487:     // ------------------------------------------------------------------ الرئيسية والتشابه
488: 
489:     /** معرّفات أقسام الصفحة الرئيسية (تُخزَّن مؤقتًا في المتحكم — الأسعار لا تُخزَّن أبدًا). */
490:     public function homeSectionIds(): array
491:     {
492:         $latest = $this->publishedQuery()->reorder()->orderByDesc('products.created_at')->orderByDesc('products.id')->limit(12)->pluck('products.id')->all();
493:         $best = $this->publishedQuery()->reorder()->orderByDesc('products.sales_count')->orderByDesc('products.id')->limit(12)->pluck('products.id')->all();
494: 
495:         $discounted = $this->publishedQuery()->reorder()
496:             ->where(fn ($q) => $q
497:                 ->whereHas('variants', fn ($v) => $v->where('is_active', true)
498:                     ->whereNotNull('retail_price')
499:                     ->whereNotNull('compare_at_price')
500:                     ->whereColumn('compare_at_price', '>', 'base_price'))
501:                 ->orWhereHas('variants', fn ($v) => $v->where('is_active', true)
502:                     ->whereExists(fn ($sub) => $sub->select(DB::raw(1))
503:                         ->from('price_list_items')
504:                         ->join('price_lists', 'price_lists.id', '=', 'price_list_items.price_list_id')
505:                         ->whereColumn('price_list_items.product_variant_id', 'product_variants.id')
506:                         ->where('price_lists.is_active', true)
507:                         ->where('price_lists.type', 'retail')
508:                         ->whereNull('price_lists.branch_id')
509:                         ->where('price_list_items.min_qty', '<=', 1)
510:                         ->where(fn ($w) => $w->whereNull('price_lists.starts_at')->orWhere('price_lists.starts_at', '<=', now()))
511:                         ->where(fn ($w) => $w->whereNull('price_lists.ends_at')->orWhere('price_lists.ends_at', '>=', now()))
512:                         ->where(fn ($w) => $w->whereNull('price_list_items.starts_at')->orWhere('price_list_items.starts_at', '<=', now()))
513:                         ->where(fn ($w) => $w->whereNull('price_list_items.ends_at')->orWhere('price_list_items.ends_at', '>=', now()))
514:                         ->whereColumn('price_list_items.price', '<', 'product_variants.base_price'))))
515:             ->orderByDesc('products.sales_count')->orderByDesc('products.id')
516:             ->limit(12)->pluck('products.id')->all();
517: 
518:         return [
519:             'latest_ids' => $latest,
520:             'best_seller_ids' => $best,
521:             'discounted_ids' => $discounted,
522:         ];
523:     }
