525:     /**
526:      * منتجات مشابهة: نفس القسم الفرعي، والمتوفر أولًا.
527:      *
528:      * @return Collection<int, Product>
529:      */
530:     public function similar(Product $product): Collection
531:     {
532:         // F12: مرحلتان — 40 مرشحًا حسب sales_count (مفهرس) دون EXISTS ثقيل،
533:         // ثم "المتوفر أولًا" في PHP عبر store_available، ثم تحميل كامل لـ 8 فقط.
534:         $candidates = $this->publishedQuery()->withoutEagerLoads()
535:             ->where('products.id', '!=', $product->id)
536:             ->where('products.category_id', $product->category_id)
537:             ->reorder()
538:             ->orderByDesc('products.sales_count')
539:             ->orderByDesc('products.id')
540:             ->limit(40)
541:             ->get();
542: 
543:         $orderedIds = $candidates
544:             ->sort(fn ($a, $b) => [((float) $b->store_available > 0 ? 1 : 0), (int) $b->sales_count, (int) $b->id]
545:                 <=> [((float) $a->store_available > 0 ? 1 : 0), (int) $a->sales_count, (int) $a->id])
546:             ->take(8)
547:             ->pluck('id')
548:             ->all();
549: 
550:         $full = $orderedIds === []
551:             ? new Collection
552:             : $this->publishedQuery()
553:                 ->whereIn('products.id', $orderedIds)
554:                 ->get()
555:                 ->keyBy('id');
556: 
557:         // Eloquent Collection بالترتيب المحسوب (المتوفر أولًا ثم الأعلى مبيعًا).
558:         return new Collection(collect($orderedIds)
559:             ->map(fn ($id) => $full->get($id))
560:             ->filter()
561:             ->all());
562:     }
