 20: /**
 21:  * سلة التسوق للزائر والعميل المسجل.
 22:  * - الزائر: سلة مربوطة بـ cart_token (يُرسل في هيدر X-Cart-Session).
 23:  * - العميل: سلة مربوطة بحسابه؛ وعند تسجيل الدخول تُدمج سلة الزائر فيها.
 24:  * الأسعار دائمًا لحظية من PricingService (لا تُخزّن في السلة أبدًا).
 25:  */
 26: class CartService
 27: {
 28:     public const MAX_REQUEST_QTY = 10000;
 29: 
 30:     public function __construct(
 31:         protected PricingService $pricing,
 32:         protected StoreCatalogService $catalog,
 33:         protected CouponService $coupons,
 34:     ) {}
 35: 
 36:     /**
 37:      * سلة الزائر/العميل الحالية.
 38:      * - التوكن غير الـ UUID يُتجاهل تمامًا (M2)؛ وتوكن أي سلة جديدة
 39:      *   يُولّد على الخادم دائمًا (Cart::booted) ولا يُقبل مقترح العميل.
 40:      * - بوضع القراءة ($create=false) لا يُحفظ أي صف: تُرجع سلة فارغة
 41:      *   افتراضية حتى لا تملأ الزواحف جدول carts (M3).
 42:      * لو وُجدت سلة زائر بالتوكن وعميل مسجل، تُدمج فيها أولًا.
 43:      */
 44:     public function resolveCart(?Customer $customer, ?string $guestToken, bool $create = true): Cart
 45:     {
 46:         $guestToken = $guestToken !== null && Str::isUuid($guestToken) ? $guestToken : null;
 47: 
 48:         if ($customer !== null) {
 49:             $cart = $create
 50:                 ? $this->accountCart($customer)
 51:                 : (Cart::query()->where('customer_id', $customer->id)->first() ?? new Cart(['customer_id' => $customer->id]));
 52:             if ($create && $guestToken !== null && $guestToken !== $cart->cart_token) {
 53:                 $this->mergeGuestCart($customer, $guestToken);
 54:                 $cart = $cart->fresh();
 55:             }
 56: 
 57:             return $cart->loadMissing('items');
 58:         }
 59: 
 60:         $cart = $guestToken !== null
 61:             ? Cart::query()->where('cart_token', $guestToken)->whereNull('customer_id')->first()
 62:             : null;
 63:         if ($cart !== null) {
 64:             return $cart->loadMissing('items');
 65:         }
 66: 
 67:         return ($create ? Cart::create([]) : new Cart)->loadMissing('items');
 68:     }
 69: 
 70:     /**
 71:      * سلة حساب العميل الوحيدة — القيد الفريد على customer_id يحسم السباق (M6).
 72:      * createOrFirst يغلّف الإدراج في savepoint داخل المعاملات (F-10):
 73:      * firstOrCreate العادي إذا فشل إدراجه هنا — والدمج كله داخل transaction
 74:      * خارجية — ترك المعاملة aborted (25P02) فخرج 500 رغم الـ catch.
 75:      */
 76:     private function accountCart(Customer $customer): Cart
 77:     {
 78:         return Cart::query()->where('customer_id', $customer->id)->first()
 79:             ?? Cart::query()->createOrFirst(['customer_id' => $customer->id]);
 80:     }
 81: 
 82:     /** دمج سلة زائر (بالتوكن) في سلة حساب العميل — تُستدعى عند تسجيل الدخول. */
 83:     public function mergeGuestCart(Customer $customer, ?string $guestToken): void
 84:     {
 85:         $guestToken = $guestToken !== null && Str::isUuid($guestToken) ? $guestToken : null;
 86:         if ($guestToken === null) {
 87:             return;
 88:         }
 89: 
 90:         // كل الدمج داخل transaction واحدة وسلة الزائر مقفولة: طلبات متوازية
 91:         // بعد تسجيل الدخول بنفس التوكن لا تضاعف الكميات (M6)
 92:         DB::transaction(function () use ($customer, $guestToken): void {
 93:             $guest = Cart::query()->where('cart_token', $guestToken)->whereNull('customer_id')
 94:                 ->lockForUpdate()->first();
 95:             if ($guest === null) {
 96:                 return;
 97:             }
 98:             if (! $guest->items()->exists()) {
 99:                 $guest->delete();
100: 
101:                 return;
102:             }
103: 
104:             $account = Cart::query()->lockForUpdate()->findOrFail($this->accountCart($customer)->id);
105:             // الدمج يحترم سقوف السلة (M2): بغير ذلك بضع سلال زائر بحد البنود
106:             // تُنتج سلة حساب بمئات البنود فتُلغي حماية F15
107:             $maxLines = (int) config('store.max_cart_lines', 50);
108:             $lineCap = $this->lineQtyCap($customer);
109:             $accountQty = $account->items()->pluck('qty', 'product_variant_id')
110:                 ->map(fn ($qty): float => (float) $qty)->all();
111:             $accountLines = count($accountQty);
112: 
113:             foreach ($guest->items as $item) {
114:                 $variantId = (int) $item->product_variant_id;
115:                 $existingQty = $accountQty[$variantId] ?? null;
116:                 $isNew = $existingQty === null;
117: 
118:                 // بنود جديدة فوق السقف تُتجاهل (لا تُفشل تسجيل الدخول)
119:                 if ($isNew && $maxLines > 0 && $accountLines >= $maxLines) {
120:                     continue;
121:                 }
122: 
123:                 $qty = (float) $item->qty;
124:                 if ($lineCap > 0) {
125:                     $allowed = $lineCap - (float) ($existingQty ?? 0);
126:                     if ($allowed <= 0) {
127:                         continue;
128:                     }
129:                     $qty = min($qty, $allowed);
130:                 }
131: 
132:                 // UPSERT ذرّي: دمج متزامن لا يصطدم بقيد التفرد (F-09)
133:                 CartItem::query()->upsert(
134:                     [[
135:                         'cart_id' => $account->id,
136:                         'product_variant_id' => $variantId,
137:                         'qty' => $qty,
138:                         'created_at' => now(),
139:                         'updated_at' => now(),
140:                     ]],
141:                     ['cart_id', 'product_variant_id'],
142:                     ['qty' => DB::raw('cart_items.qty + EXCLUDED.qty'), 'updated_at' => now()],
143:                 );
144: 
145:                 $accountQty[$variantId] = (float) ($existingQty ?? 0) + $qty;
146:                 if ($isNew) {
147:                     $accountLines++;
148:                 }
149:             }
150:             if ($account->coupon_id === null && $guest->coupon_id !== null) {
151:                 $account->update(['coupon_id' => $guest->coupon_id]);
152:             }
153:             $guest->items()->delete();
154:             $guest->delete();
155:         });
156:     }
