158:     public function addItem(Cart $cart, ?Customer $customer, int $variantId, float $qty): Cart
159:     {
160:         $this->assertWholeQuantity($qty);
161: 
162:         return DB::transaction(function () use ($cart, $customer, $variantId, $qty): Cart {
163:             // قفل صف السلة (F19): إضافتان متزامنتان تتسلسلان فلا تُحسب
164:             // الكمية على قراءة قديمة ولا يُتجاوز سقف البنود
165:             if (! $cart->exists) {
166:                 $cart = $customer !== null ? $this->accountCart($customer) : Cart::create([]);
167:             }
168:             $cart = Cart::query()->lockForUpdate()->findOrFail($cart->id);
169: 
170:             $variant = $this->purchasableVariant($variantId);
171:             $existing = $cart->items()->where('product_variant_id', $variantId)->first();
172: 
173:             // سقف أصناف السلة (F15): سلة بآلاف البنود تُثقل التسعير وكل عرض
174:             if ($existing === null) {
175:                 $maxLines = (int) config('store.max_cart_lines', 50);
176:                 if ($maxLines > 0 && $cart->items()->count() >= $maxLines) {
177:                     throw new BusinessException("بلغت سلة التسوق سقف الأصناف ({$maxLines})؛ احذف صنفًا قبل الإضافة.");
178:                 }
179:             }
180: 
181:             $targetQty = ($existing !== null ? (float) $existing->qty : 0) + $qty;
182:             $this->assertLineQty($customer, $targetQty);
183:             $this->assertAvailable($variantId, $targetQty);
184:             $this->assertPriced($variant, $customer, $targetQty);
185: 
186:             // كتابة ذرّية UPSERT (F-09): نقرتان متزامنتان على «أضف للسلة»
187:             // كانتا تصطدمان بقيد التفرد عند الإدراج الثاني فتخرج 500 —
188:             // ON CONFLICT تجمع الكمية على الصف نفسه. القراءة أعلاه تبقى
189:             // للتحقق من حد التوفر فقط
190:             CartItem::query()->upsert(
191:                 [[
192:                     'cart_id' => $cart->id,
193:                     'product_variant_id' => $variantId,
194:                     'qty' => $qty,
195:                     'created_at' => now(),
196:                     'updated_at' => now(),
197:                 ]],
198:                 ['cart_id', 'product_variant_id'],
199:                 ['qty' => DB::raw('cart_items.qty + EXCLUDED.qty'), 'updated_at' => now()],
200:             );
201: 
202:             return $cart->fresh('items');
203:         });
204:     }
