206:     public function updateItemQty(Cart $cart, ?Customer $customer, int $variantId, float $qty, ?int $itemId = null): Cart
207:     {
208:         $this->assertWholeQuantity($qty, allowZero: true);
209:         if ($qty <= 0) {
210:             return $this->removeItem($cart, $variantId);
211:         }
212: 
213:         return DB::transaction(function () use ($cart, $customer, $variantId, $qty, $itemId): Cart {
214:             // قفل صف السلة (F19) بنفس منطق addItem
215:             $cart = Cart::query()->lockForUpdate()->findOrFail($cart->id);
216:             $variant = $this->purchasableVariant($variantId);
217:             $this->assertLineQty($customer, $qty);
218:             $this->assertAvailable($variantId, $qty);
219:             $this->assertPriced($variant, $customer, $qty);
220: 
221:             $item = $cart->items()->where('product_variant_id', $variantId)
222:                 ->when($itemId !== null, fn ($query) => $query->whereKey($itemId))->firstOrFail();
223:             $item->update(['qty' => $qty]);
224: 
225:             return $cart->fresh('items');
226:         });
227:     }
