229:     public function removeItem(Cart $cart, int $variantId): Cart
230:     {
231:         return DB::transaction(function () use ($cart, $variantId): Cart {
232:             $cart = Cart::query()->lockForUpdate()->findOrFail($cart->id);
233:             $cart->items()->where('product_variant_id', $variantId)->delete();
234: 
235:             return $cart->fresh('items');
236:         });
237:     }
