249:     /**
250:      * بنود السلة بأسعار لحظية من PricingService.
251:      * بند غير قابل للتسعير يرجع بـ unit_price = null (العرض يتجاوزه،
252:      * وإتمام الشراء يرفضه — يتحقق المستدعي).
253:      *
254:      * @return array<int, array{variant: ProductVariant, qty: float, unit_price: float|null, base_price: float|null, line_discount: float, line_total: float}>
255:      */
256:     public function pricedLines(Cart $cart, ?Customer $customer): array
257:     {
258:         $cart->loadMissing('items.variant.product');
259:         $purchasableIds = $this->retailVariants()->whereIn('id', $cart->items->pluck('product_variant_id'))->pluck('id')->all();
260:         $context = $this->pricing->contextFor($customer, $cart->items->pluck('product_variant_id')->all());
261:         $lines = [];
262:         foreach ($cart->items as $item) {
263:             $variant = $item->variant;
264:             if ($variant === null) {
265:                 continue;
266:             }
267:             // L1: soft-deleted or deactivated variants stay in the response as
268:             // unavailable lines so the shopper can remove them.
269:             if (! in_array($variant->id, $purchasableIds, true)) {
270:                 $lines[] = [
271:                     'item_id' => $item->id,
272:                     'variant' => $variant,
273:                     'qty' => (float) $item->qty,
274:                     'unit_price' => null,
275:                     'base_price' => null,
276:                     'line_discount' => 0.0,
277:                     'line_total' => 0.0,
278:                 ];
279: 
280:                 continue;
281:             }
282:             $qty = (float) $item->qty;
283:             try {
284:                 $resolved = $this->pricing->resolve($variant, $customer, $qty, ctx: $context);
285:                 $unit = (float) $resolved['unit_price'];
286:                 $base = (float) $resolved['base_price'];
287:                 $lines[] = [
288:                     'item_id' => $item->id,
289:                     'variant' => $variant,
290:                     'qty' => $qty,
291:                     'unit_price' => $unit,
292:                     'base_price' => $base,
293:                     // F20: سعر مخصص أعلى من الأساسي لا يصنع خصمًا سالبًا في السطر.
294:                     'line_discount' => max(0.0, BigDecimal::of((string) $base)->minus((string) $unit)->multipliedBy((string) $qty)->toScale(2, RoundingMode::HalfUp)->toFloat()),
295:                     'line_total' => BigDecimal::of((string) $unit)->multipliedBy((string) $qty)->toScale(2, RoundingMode::HalfUp)->toFloat(),
296:                 ];
297:             } catch (BusinessException) {
298:                 $lines[] = [
299:                     'item_id' => $item->id,
300:                     'variant' => $variant,
301:                     'qty' => $qty,
302:                     'unit_price' => null,
303:                     'base_price' => null,
304:                     'line_discount' => 0.0,
305:                     'line_total' => 0.0,
306:                 ];
307:             }
308:         }
309: 
310:         return $lines;
311:     }
312: 
313:     /**
314:      * ملخص السلة المالي بالأسعار اللحظية.
315:      *
316:      * @return array{subtotal: float, pricing_discount: float, items_total: float, coupon_discount: float, total: float, coupon_code: string|null}
317:      */
318:     /**
319:      * @param  array<int, array<string, mixed>>|null  $lines  بنود محسوبة مسبقًا
320:      *                                                        لتجنب إعادة التسعير (M15)
321:      */
322:     public function totals(Cart $cart, ?Customer $customer, ?array $lines = null): array
323:     {
324:         $lines ??= $this->pricedLines($cart, $customer);
325:         $subtotalDecimal = BigDecimal::zero();
326:         $itemsDecimal = BigDecimal::zero();
327:         foreach ($lines as $line) {
328:             if ($line['unit_price'] === null) {
329:                 continue;
330:             }
331:             // كل سطر يُقرَّب أولًا ثم تُجمع القيم المقرّبة (M17)
332:             $lineSubtotal = BigDecimal::of((string) $line['base_price'])->multipliedBy((string) $line['qty'])->toScale(2, RoundingMode::HalfUp);
333:             $subtotalDecimal = $subtotalDecimal->plus($lineSubtotal->isLessThan((string) $line['line_total']) ? (string) $line['line_total'] : $lineSubtotal);
334:             $itemsDecimal = $itemsDecimal->plus((string) $line['line_total']);
335:         }
336:         $subtotal = $subtotalDecimal->toFloat();
337:         $itemsTotal = $itemsDecimal->toFloat();
338: 
339:         // الخصم السعري = الفرق بين الإجماليين المقرّبين، لا مجموع فروق
340:         // السطور المقرّبة (F-26) حتى لا يظهر فرق قرش بين العرض والمحصّل.
341:         // ‏(L6) سعر مخصص أعلى من الأساسي لا يصنع خصمًا سالبًا: يُرفع المرجع
342:         // لسعر البيع الفعلي، فلا يزيد الخصم السالب الإجمالي المحصّل.
343:         if ($subtotal < $itemsTotal) {
344:             $subtotal = $itemsTotal;
345:             $pricingDiscount = 0.0;
346:         } else {
347:             $pricingDiscount = $subtotalDecimal->minus($itemsDecimal)->toScale(2, RoundingMode::HalfUp)->toFloat();
348:         }
349: 
350:         $couponDiscount = 0.0;
351:         $couponCode = null;
352:         if ($cart->coupon_id !== null && $itemsTotal > 0) {
353:             try {
354:                 $coupon = $this->coupons->redeemableById((int) $cart->coupon_id, $itemsTotal, $customer);
355:                 $couponDiscount = $this->coupons->discountFor($coupon, $itemsTotal);
356:                 $couponCode = $coupon->code;
357:             } catch (BusinessException) {
358:                 // كوبون لم يعد صالحًا: يُعرض الملخص بدونه (إتمام الشراء سيعيد التحقق)
359:             }
360:         }
361: 
362:         return [
363:             'subtotal' => round($subtotal, 2),
364:             'pricing_discount' => round($pricingDiscount, 2),
365:             'items_total' => round($itemsTotal, 2),
366:             'coupon_discount' => $couponDiscount,
367:             'total' => $itemsDecimal->minus((string) $couponDiscount)->toScale(2, RoundingMode::HalfUp)->toFloat(),
368:             'coupon_code' => $couponCode,
369:         ];
370:     }
371: 
372:     /**
373:      * إعادة التحقق من قابلية البيع لكل بند لحظة الشراء بشكل مجمّع (M14):
374:      * متغير معطّل أو منتج غير منشور/محذوف ناعمًا بعد الإضافة يوقف الطلب.
375:      *
376:      * @param  array<int, array{variant: ProductVariant, qty: float}>  $lines
377:      */
378:     public function assertLinesPurchasable(array $lines): void
379:     {
380:         foreach ($lines as $line) {
381:             $this->assertWholeQuantity((float) $line['qty']);
382:         }
383:         $ids = array_map(fn (array $line): int => (int) $line['variant']->id, $lines);
384:         // H1: one batched refresh; the purchasability rule is the storefront
385:         // published rule (retail channel + active category path), not just
386:         // is_active/Published/trashed.
387:         $variants = $this->retailVariants()->whereIn('id', $ids)->pluck('id')->all();
388:         foreach ($lines as $line) {
389:             $variant = $line['variant'];
390:             if (! in_array($variant->id, $variants, true)) {
391:                 throw new BusinessException("الصنف ({$variant->sku}) لم يعد متاحًا للبيع؛ أزله من السلة وأعد المحاولة.");
392:             }
393:         }
394:     }
395: 
396:     /**
397:      * إعادة التحقق من توفر بنود مُسعّرة لحظة الشراء.
398:      *
399:      * @param  array<int, array{variant: ProductVariant, qty: float}>  $lines
400:      */
401:     public function assertLinesAvailable(array $lines): void
402:     {
403:         $ids = array_map(fn (array $line): int => (int) $line['variant']->id, $lines);
404:         $map = $this->catalog->availabilityMap($ids);
405:         foreach ($lines as $line) {
406:             if (($map[$line['variant']->id] ?? 0) < $line['qty']) {
407:                 throw new BusinessException("الكمية المتاحة من الصنف ({$line['variant']->sku}) لم تعد كافية لإتمام الطلب.");
408:             }
409:         }
410:     }
