412:     /**
413:      * تمثيل السلة للعرض: البنود بأسعار ومتاح لحظي + الملخص المالي.
414:      *
415:      * @return array<string, mixed>
416:      */
417:     public function present(Cart $cart, ?Customer $customer): array
418:     {
419:         $lines = $this->pricedLines($cart, $customer);
420:         $ids = array_map(fn (array $line): int => (int) $line['variant']->id, $lines);
421:         $availability = $this->catalog->availabilityMap($ids);
422: 
423:         $items = [];
424:         foreach ($lines as $line) {
425:             $variant = $line['variant'];
426:             $exact = (float) ($availability[$variant->id] ?? 0);
427:             // L2: never expose the exact branch-wide balance; shoppers only
428:             // need the purchasable ceiling. Unpriced lines report zero.
429:             $maxQty = $line['unit_price'] === null ? 0.0 : $this->maxPurchasableQty($exact, $customer);
430:             $items[] = [
431:                 'id' => $line['item_id'],
432:                 'product_variant_id' => $variant->id,
433:                 'product_id' => $variant->product_id,
434:                 'product_name' => $variant->product?->name_ar,
435:                 'sku' => $variant->sku,
436:                 'qty' => $line['qty'],
437:                 'unit_price' => $line['unit_price'],
438:                 'base_price' => $line['base_price'],
439:                 'line_discount' => $line['line_discount'],
440:                 'line_total' => $line['line_total'],
441:                 'available' => $maxQty,
442:                 'max_qty' => $maxQty,
443:                 'priced' => $line['unit_price'] !== null,
444:             ];
445:         }
446: 
447:         return [
448:             'id' => $cart->id,
449:             'cart_token' => $cart->cart_token,
450:             'customer_id' => $cart->customer_id,
451:             'items' => $items,
452:             'totals' => $this->totals($cart, $customer, $lines),
453:         ];
454:     }
455: 
456:     private function purchasableVariant(int $variantId): ProductVariant
457:     {
458:         // H1: the single source of truth is the storefront published rule.
459:         $variant = $this->retailVariants()->with('product')->find($variantId);
460:         if ($variant === null) {
461:             throw new BusinessException('الصنف غير متاح للشراء.');
462:         }
463: 
464:         return $variant;
465:     }
466: 
467:     /** Use the catalog's visibility query for every retail purchase check. */
468:     private function retailVariants(): Builder
469:     {
470:         return ProductVariant::query()->where('is_active', true)
471:             ->whereIn('product_id', $this->catalog->publishedQuery()->withoutEagerLoads()->select('products.id'));
472:     }
473: 
474:     /** سقف كمية البند الواحد (H2): للزوار، وللمسجّلين غير الجملة سقف تجزئة. */
475:     private function assertLineQty(?Customer $customer, float $qty): void
476:     {
477:         $cap = $this->lineQtyCap($customer);
478:         if ($cap > 0 && $qty > $cap) {
479:             throw new BusinessException($customer === null
480:                 ? "سقف كمية البند الواحد للزوار ({$cap}) — سجّل الدخول للكميات الأكبر."
481:                 : "سقف كمية البند الواحد ({$cap}) — للكميات الأكبر تواصل مع مسار الجملة.");
482:         }
483:     }
484: 
485:     /** سقف كمية السطر الفعّال للهوية: 0 = بلا سقف (عملاء الجملة المعتمدون). */
486:     public function lineQtyCap(?Customer $customer): float
487:     {
488:         if ($customer === null) {
489:             return (float) config('store.guest_max_line_qty', 10);
490:         }
491:         if ($customer->status === CustomerStatus::Approved
492:             && in_array($customer->type, [CustomerType::Wholesale, CustomerType::Distributor], true)) {
493:             return 0.0;
494:         }
495: 
496:         return (float) config('store.retail_max_line_qty', 50);
497:     }
498: 
499:     /** The displayed ceiling also respects the cart API's per-request bound. */
500:     public function maxPurchasableQty(float $available, ?Customer $customer): float
501:     {
502:         $cap = $this->lineQtyCap($customer);
503: 
504:         return max(0.0, min($available, self::MAX_REQUEST_QTY, $cap > 0 ? $cap : self::MAX_REQUEST_QTY));
505:     }
506: 
507:     public function assertWholeQuantity(float $qty, bool $allowZero = false): void
508:     {
509:         if (! is_finite($qty) || floor($qty) !== $qty || $qty < ($allowZero ? 0 : 1)) {
510:             throw new BusinessException('الكمية يجب أن تكون عددًا صحيحًا من القطع.');
511:         }
512:     }
513: 
514:     private function assertAvailable(int $variantId, float $qty): void
515:     {
516:         $available = $this->catalog->availabilityMap([$variantId])[$variantId] ?? 0;
517:         if ($available < $qty) {
518:             throw new BusinessException('الكمية المطلوبة غير متاحة حاليًا لهذا الصنف.');
519:         }
520:     }
521: 
522:     private function assertPriced(ProductVariant $variant, ?Customer $customer, float $qty): void
523:     {
524:         $this->pricing->resolve($variant, $customer, $qty); // يرمي BusinessException عند غياب السعر
525:     }
