144: function categoryFormData(p: CategoryPayload, spoofPut = false): FormData {
145:   const fd = new FormData();
146:   if (spoofPut) fd.append('_method', 'PUT');
147:   const put = (key: string, v: unknown) => {
148:     if (v === undefined) return;                       // مش هيتبعت
149:     if (v === null) return fd.append(key, '');         // Laravel يحوّلها null
150:     if (typeof v === 'boolean') return fd.append(key, v ? '1' : '0'); // مهم: مش "true"
151:     if (v instanceof Blob) return fd.append(key, v);
152:     fd.append(key, String(v));
153:   };
154:   put('parent_id', p.parent_id);
155:   put('name_ar', p.name_ar);
156:   put('name_en', p.name_en);
157:   put('slug', p.slug);
158:   put('description_ar', p.description_ar);
159:   put('description_en', p.description_en);
160:   put('sort_order', p.sort_order);
161:   put('is_active', p.is_active);
162:   if (p.image) put('image', p.image);
163:   if (p.remove_image) put('remove_image', true);
164:   return fd;
165: }
