 63:     /**
 64:      * تحويل سلة إلى طلب جديد بحالة pending.
 65:      *
 66:      * @param  array{recipient_name?: string|null, recipient_phone?: string|null, recipient_email?: string|null, city_id?: int|null, shipping_address_line?: string|null, shipping_notes?: string|null, payment_method?: string|null, channel?: string}  $data
