360:             )));
361:             if ($orderedItemIds !== []) {
362:                 $cart->items()->whereIn('id', $orderedItemIds)->delete();
363:             }
364:             $cart->update(['coupon_id' => null]);
365: 
366:             $created = $order->fresh(['items', 'statusHistories']);
367:             OrderCreated::dispatch($created);
368: 
369:             if ($phoneDayKey !== null) {
370:                 DB::afterCommit(fn () => RateLimiter::hit($phoneDayKey, 24 * 3600));
371:             }
372: 
373:             return $created;
374:         });
375: 
376:         return $created;
377:     }
