379:     /**
380:      * بوابة الحالة الوحيدة. $expectedFrom (F-11): حالات مصدر يفترضها
381:      * المستدعي على نسخته غير المقفولة — تُفحص بعد إعادة القراءة بالقفل،
382:      * فسباق (عميل يلغي × أدمن يجهّز) لا يمر من فحص قديم.
383:      * $returnEffects (المرحلة 9): عند false ينتقل الطلب إلى Returned بلا
384:      * إعادة مخزون وبلا علم استرداد — مسار RMA سوّى المخزون عند الاستلام
385:      * الفعلي والمال عند رد المبلغ، فتكرار الأثر هنا ازدواج.
386:      *
387:      * @param  array<int, OrderStatus>|null  $expectedFrom
388:      */
389:     public function changeStatus(Order $order, OrderStatus|string $toStatus, ?Model $actor = null, ?string $notes = null, ?array $expectedFrom = null, bool $returnEffects = true): Order
390:     {
391:         $to = $toStatus instanceof OrderStatus ? $toStatus : OrderStatus::from($toStatus);
392: 
393:         return DB::transaction(function () use ($order, $to, $actor, $notes, $expectedFrom, $returnEffects): Order {
394:             // إعادة قراءة الطلب بقفل صف: النسخة الممرَّرة قد تكون قديمة،
395:             // وكل الانتقالات على نفس الطلب يجب أن تتسلسل (C1)
396:             $order = Order::query()->lockForUpdate()->findOrFail($order->id);
397:             $from = $order->status;
398: 
399:             if ($expectedFrom !== null && ! in_array($from, $expectedFrom, true)) {
400:                 throw new BusinessException("تغيّرت حالة الطلب أثناء العملية (أصبحت {$from->value})؛ أعد المحاولة.");
401:             }
402: 
403:             if ($from === $to) {
404:                 return $order;
405:             }
406: 
407:             if (! in_array($to->value, self::TRANSITIONS[$from->value] ?? [], true)) {
408:                 throw new BusinessException("انتقال حالة غير مسموح: من ({$from->value}) إلى ({$to->value}).");
409:             }
410: 
411:             $actorId = $this->inventoryActorId($actor);
412: 
413:             if ($to === OrderStatus::Returned && $returnEffects && $order->channel === 'pos') {
414:                 throw new BusinessException('استخدم مرتجع POS لتسوية المخزون والنقدية معًا.');
415:             }
416: 
417:             if ($to === OrderStatus::Returned && $returnEffects
418:                 && ReturnRequest::query()->where('order_id', $order->id)->whereNotIn('status', [
419:                     ReturnStatus::Rejected->value, ReturnStatus::Cancelled->value,
420:                 ])->exists()) {
421:                 throw new BusinessException('للطلب مرتجعات قائمة؛ أكمل الاستلام والاسترداد من إدارة المرتجعات لمنع تكرار المخزون.');
422:             }
423: 
424:             // آثار المخزون بحسب الانتقال
425:             $extraNote = null;
426:             if ($to === OrderStatus::Shipped) {
427:                 $this->shipOrder($order, $actorId);
428:             } elseif ($to === OrderStatus::Cancelled
429:                 && in_array($from, [OrderStatus::Pending, OrderStatus::Confirmed, OrderStatus::Processing], true)) {
430:                 // الحجز صار من لحظة الإنشاء (F-01) فيُفك من Pending أيضًا
431:                 $this->releaseReservations($order, $actorId, 'إلغاء الطلب');
432:             } elseif ($to === OrderStatus::Returned
433:                 && in_array($from, [OrderStatus::Shipped, OrderStatus::Delivered], true)
434:                 && $returnEffects) {
435:                 // إعادة البضاعة المشحونة للمخزون بحركات sale_return (M13) —
436:                 // تُتخطى في مسار RMA لأن الاستلام الفعلي سوّاها بالفعل (مرحلة 9)
437:                 if (! $this->returnSalesToStock($order, $actorId)) {
438:                     $extraNote = 'لا توجد حركات بيع مسجلة؛ يتطلب المرتجع استلامًا يدويًا في المستودع.';
439:                 }
440:             }
441: 
442:             if ($to === OrderStatus::Cancelled) {
443:                 // عكس استخدام الكوبون حتى لا يُحرم العميل منه بإلغاء (M13)
444:                 $this->reverseCouponUsage($order);
445:                 if ($order->payment_status === 'paid') {
446:                     $order->update(['requires_refund' => true]);
447:                 }
448:             }
449: 
450:             // مرتجع لطلب مدفوع يحتاج استردادًا أيضًا، لا الإلغاء فقط (F-14) —
451:             // في مسار RMA الاسترداد اكتمل داخل طلب المرتجع نفسه فلا علم هنا
452:             if ($to === OrderStatus::Returned && $order->payment_status === 'paid' && $returnEffects) {
453:                 $order->update(['requires_refund' => true]);
454:             }
455: 
456:             if ($order->payment_method === 'wallet' && $order->payment_status === 'paid'
457:                 && ($to === OrderStatus::Cancelled || ($to === OrderStatus::Returned && $returnEffects))) {
458:                 $payment = CustomerWalletTransaction::query()->where('reference_type', 'order')->where('reference_id', $order->id)
459:                     ->where('type', 'checkout_payment')->first();
460:                 if ($payment !== null) {
461:                     app(WalletService::class)->record($payment->customer_id, -(float) $payment->amount,
462:                         'order_reversal', 'order', $order->id, $actorId);
463:                     $order->update(['payment_status' => 'refunded', 'requires_refund' => false]);
464:                 }
465:             }
466: 
467:             $order->update(['status' => $to]);
468: 
469:             // تسوية COD عند التسليم من أي مسار (أدمن يدوي أو ويب هوك) —
470:             // الأثر هنا في بوابة الحالة لا في ويب هوك الشحن فقط (F-14)
471:             if ($to === OrderStatus::Delivered
472:                 && $order->payment_method === 'cod'
473:                 && $order->payment_status !== 'paid') {
474:                 $order->update(['payment_status' => 'paid']);
475:             }
476: 
477:             // notes عمود varchar(500): ملاحظة الأدمن (حتى 500) مع الملحق قد
478:             // تتجاوزه فتنفجر بحركة إرجاع بلا حركات بيع — تُقصّ على 500 (F-28)
479:             $historyNotes = trim(($notes ?? '').($extraNote !== null ? ' — '.$extraNote : '')) ?: $notes;
480: 
481:             $order->statusHistories()->create([
482:                 'from_status' => $from,
483:                 'to_status' => $to,
484:                 'changed_by_type' => $actor?->getMorphClass(),
485:                 'changed_by_id' => $actor?->getKey(),
486:                 'notes' => $historyNotes !== null ? mb_substr($historyNotes, 0, 500) : null,
487:             ]);
488: 
489:             // التوزيع ناقص إن غاب فرع الطلب أو بقي بند بلا فرع: الاعتماد على
490:             // allocated_branch_id وحده يفشل عندما تُوزَّع البنود في فروع
491:             // مختلفة فيبقى حقل الطلب فارغًا (F1)
492:             if ($to === OrderStatus::Confirmed && ! $this->isAllocated($order)) {
493:                 $this->allocationService->allocate($order, performedBy: $actorId);
494:             }
495: 
496:             return $order->fresh(['items', 'statusHistories']);
497:         });
498:     }
