500:     /**
501:      * كفاية التوزيع: يكفي أن يكون لفرع الطلب قيمة أو أن يكون كل بند موزّعًا
502:      * فعليًا في فرع ما (F1) — التوزيع الجزئي (بند بلا فرع) يُعيد الاستدعاء.
503:      */
504:     private function isAllocated(Order $order): bool
505:     {
506:         if ($order->allocated_branch_id !== null) {
507:             return true;
508:         }
509: 
510:         $distribution = $order->items()
511:             ->selectRaw('COUNT(*) AS total, COUNT(allocated_branch_id) AS allocated')
512:             ->first();
513: 
514:         if ($distribution === null || (int) $distribution->total === 0) {
515:             return false;
516:         }
517: 
518:         return (int) $distribution->total === (int) $distribution->allocated;
519:     }
