521:     /** عميل جملة/توزيع معتمد — يُستثنى من سقوف التجزئة (H2). */
522:     private function isWholesaleApproved(?Customer $customer): bool
523:     {
524:         return $customer !== null
525:             && $customer->status === CustomerStatus::Approved
526:             && in_array($customer->type, [CustomerType::Wholesale, CustomerType::Distributor], true);
527:     }
