529:     /**
530:      * توزيع مبلغ على أوزان بطريقة «أكبر باقٍ» بعدد صحيح من القروش (L5):
531:      * مجموع الحصص يساوي المبلغ بالضبط، ولا حصة سالبة بسبب التقريب.
532:      *
533:      * @param  array<int, float>  $weights
534:      * @return array<int, float>
535:      */
536:     private function distributeLargestRemainder(float $total, array $weights): array
537:     {
538:         $count = count($weights);
539:         if ($count === 0) {
540:             return [];
541:         }
542:         $totalCents = (int) round($total * 100);
543:         $weightSum = array_sum($weights);
544:         if ($totalCents <= 0 || $weightSum <= 0) {
545:             return array_fill(0, $count, 0.0);
546:         }
547: 
548:         $floorCents = [];
549:         $remainders = [];
550:         $assigned = 0;
551:         foreach ($weights as $i => $weight) {
552:             $exact = $totalCents * ((float) $weight / $weightSum);
553:             $floor = (int) floor($exact);
554:             $floorCents[$i] = $floor;
555:             $remainders[$i] = $exact - $floor;
556:             $assigned += $floor;
557:         }
558: 
559:         $left = $totalCents - $assigned;
560:         arsort($remainders);
561:         foreach (array_keys($remainders) as $i) {
562:             if ($left <= 0) {
563:                 break;
564:             }
565:             $floorCents[$i]++;
566:             $left--;
567:         }
568: 
569:         ksort($floorCents);
570: 
571:         return array_map(fn (int $cents): float => $cents / 100, $floorCents);
572:     }
