574:     /**
575:      * الشحن: الحجز القائم الصافي لكل (متغير، فرع، موقع) — فك الحجز من reserved
576:      * وخصم فعلي sale من on_hand على نفس صف الرصيد (C3).
577:      * التجميع من الدفتر نفسه يجعل تكرار الشحن/الفك آمنًا: لا يُفك أي حجز مرتين.
578:      */
579:     private function shipOrder(Order $order, ?int $actorId): void
580:     {
581:         $net = $this->netReservations($order);
582:         if ($net->isEmpty()) {
583:             throw new BusinessException('لا توجد حجوزات مخزون لهذا الطلب؛ لا يمكن الشحن قبل التأكيد والتوزيع.');
584:         }
585: 
586:         $levels = $this->inventoryService->lockLevels($net->map(fn (array $row): array => [
587:             'product_variant_id' => $row['product_variant_id'],
588:             'branch_id' => $row['branch_id'],
589:             'location_id' => $row['location_id'],
590:         ])->all());
591: 
592:         $costs = ProductVariant::withTrashed()->whereIn('id', $net->pluck('product_variant_id'))->pluck('cost_price', 'id');
593:         foreach ($net as $row) {
594:             $base = [
595:                 'product_variant_id' => $row['product_variant_id'],
596:                 'branch_id' => $row['branch_id'],
597:                 'location_id' => $row['location_id'],
598:                 'reference_type' => Order::class,
599:                 'reference_id' => $order->id,
600:                 'created_by' => $actorId,
601:             ];
602:             $level = $levels->get($this->inventoryService->levelKey($row));
603:             $this->inventoryService->recordMovement([...$base,
604:                 'type' => StockMovementType::ReleaseReserve,
605:                 'affected_bucket' => StockBucket::Reserved,
606:                 'quantity' => -1 * (float) $row['net_qty'],
607:                 'notes' => "فك حجز عند شحن الطلب {$order->order_number}",
608:             ], $level);
609:             $this->inventoryService->recordMovement([...$base,
610:                 'type' => StockMovementType::Sale,
611:                 'unit_cost' => $costs[$row['product_variant_id']] ?? null,
612:                 'affected_bucket' => StockBucket::OnHand,
613:                 'quantity' => -1 * (float) $row['net_qty'],
614:                 'notes' => "بيع عند شحن الطلب {$order->order_number}",
615:             ], $level);
616:         }
617: 
618:         foreach ($order->items as $item) {
619:             $item->variant?->product?->increment('sales_count', (int) round((float) $item->qty));
620:         }
621:     }
