623:     /** إلغاء طلب مُحجوز: فك الحجز القائم الصافي فقط فتعود الكميات متاحة للبيع (C3). */
624:     private function releaseReservations(Order $order, ?int $actorId, string $reason): void
625:     {
626:         $net = $this->netReservations($order);
627:         if ($net->isEmpty()) {
628:             return;
629:         }
630: 
631:         $levels = $this->inventoryService->lockLevels($net->map(fn (array $row): array => [
632:             'product_variant_id' => $row['product_variant_id'],
633:             'branch_id' => $row['branch_id'],
634:             'location_id' => $row['location_id'],
635:         ])->all());
636: 
637:         foreach ($net as $row) {
638:             $this->inventoryService->recordMovement([
639:                 'product_variant_id' => $row['product_variant_id'],
640:                 'branch_id' => $row['branch_id'],
641:                 'location_id' => $row['location_id'],
642:                 'type' => StockMovementType::ReleaseReserve,
643:                 'affected_bucket' => StockBucket::Reserved,
644:                 'quantity' => -1 * (float) $row['net_qty'],
645:                 'reference_type' => Order::class,
646:                 'reference_id' => $order->id,
647:                 'created_by' => $actorId,
648:                 'notes' => "{$reason} {$order->order_number}",
649:             ], $levels->get($this->inventoryService->levelKey($row)));
650:         }
651:     }
