653:     /**
654:      * إعادة بضاعة طلب مشحون/مُسلَّم إلى المخزون: صافي البيع القائم
655:      * (المبيع ناقص sale_return المرتبط بالطلب) لكل مفتاح (C3/H7).
656:      * ترجع false إذا لم يوجد صافي بيع (يحتاج استلامًا يدويًا).
657:      */
658:     private function returnSalesToStock(Order $order, ?int $actorId): bool
659:     {
660:         $net = StockMovement::query()
661:             ->whereIn('reference_type', array_unique([$order->getMorphClass(), Order::class]))
662:             ->where('reference_id', $order->id)
663:             ->whereIn('type', [StockMovementType::Sale->value, StockMovementType::SaleReturn->value])
664:             ->groupBy('product_variant_id', 'branch_id', 'location_id')
665:             ->selectRaw('product_variant_id, branch_id, location_id, SUM(quantity) AS net_qty, MAX(unit_cost) FILTER (WHERE type = \'sale\') AS sale_unit_cost')
666:             ->get()
667:             // Sale سالبة وSaleReturn موجبة: الصافي السالب هو البيع القائم.
668:             ->map(fn ($row): array => [
669:                 'product_variant_id' => (int) $row->product_variant_id,
670:                 'branch_id' => (int) $row->branch_id,
671:                 'location_id' => $row->location_id === null ? null : (int) $row->location_id,
672:                 'net_qty' => (float) $row->net_qty,
673:                 'sale_unit_cost' => $row->sale_unit_cost,
674:             ])
675:             ->filter(fn (array $row): bool => $row['net_qty'] < -1e-9)
676:             ->sortBy(fn (array $row): string => $row['branch_id'].':'.$row['location_id'].':'.$row['product_variant_id'])
677:             ->values();
678: 
679:         if ($net->isEmpty()) {
680:             return false;
681:         }
682: 
683:         $levels = $this->inventoryService->lockLevels($net->map(fn (array $row): array => [
684:             'product_variant_id' => $row['product_variant_id'],
685:             'branch_id' => $row['branch_id'],
686:             'location_id' => $row['location_id'],
687:         ])->all());
688: 
689:         foreach ($net as $row) {
690:             $this->inventoryService->recordMovement([
691:                 'product_variant_id' => $row['product_variant_id'],
692:                 'branch_id' => $row['branch_id'],
693:                 'location_id' => $row['location_id'],
694:                 'type' => StockMovementType::SaleReturn,
695:                 'affected_bucket' => StockBucket::OnHand,
696:                 'quantity' => -1 * (float) $row['net_qty'],
697:                 'unit_cost' => $row['sale_unit_cost'],
698:                 'reference_type' => Order::class,
699:                 'reference_id' => $order->id,
700:                 'created_by' => $actorId,
701:                 'notes' => "مرتجع مبيعات للطلب {$order->order_number}",
702:             ], $levels->get($this->inventoryService->levelKey($row)));
703:         }
704: 
705:         foreach ($order->items as $item) {
706:             if ($item->variant?->product_id) {
707:                 Product::query()->whereKey($item->variant->product_id)
708:                     ->update(['sales_count' => DB::raw('GREATEST(sales_count - '.(int) round((float) $item->qty).', 0)')]);
709:             }
710:         }
711: 
712:         return true;
713:     }
