715:     /**
716:      * الحجز القائم الصافي لكل (متغير، فرع، موقع): مجموع Reserve ناقص ما فُك
717:      * بـ ReleaseReserve لنفس الطلب (C3). الصفوف تُقفل مرتبة عبر lockLevels
718:      * قبل التنفيذ في المستدعي.
719:      *
720:      * @return Collection<int, array{product_variant_id: int, branch_id: int, location_id: int|null, net_qty: float}>
721:      */
722:     private function netReservations(Order $order): Collection
723:     {
724:         return StockMovement::query()
725:             ->whereIn('reference_type', array_unique([$order->getMorphClass(), Order::class]))
726:             ->where('reference_id', $order->id)
727:             ->whereIn('type', [StockMovementType::Reserve->value, StockMovementType::ReleaseReserve->value])
728:             ->groupBy('product_variant_id', 'branch_id', 'location_id')
729:             ->selectRaw('product_variant_id, branch_id, location_id, SUM(quantity) AS net_qty')
730:             ->get()
731:             ->map(fn ($row): array => [
732:                 'product_variant_id' => (int) $row->product_variant_id,
733:                 'branch_id' => (int) $row->branch_id,
734:                 'location_id' => $row->location_id === null ? null : (int) $row->location_id,
735:                 'net_qty' => (float) $row->net_qty,
736:             ])
737:             ->filter(fn (array $row): bool => $row['net_qty'] > 1e-9)
738:             ->sortBy(fn (array $row): string => $row['branch_id'].':'.$row['location_id'].':'.$row['product_variant_id'])
739:             ->values();
740:     }
