742:     /** عكس تسجيل استخدام الكوبون عند إلغاء الطلب: حذف السجل وإنقاص العدّاد (M13). */
743:     private function reverseCouponUsage(Order $order): void
744:     {
745:         foreach (CouponUsage::query()->where('order_id', $order->id)->get() as $usage) {
746:             Coupon::query()->whereKey($usage->coupon_id)->where('used_count', '>', 0)->decrement('used_count');
747:             $usage->delete();
748:         }
749:     }
