751:     /** حركات الحجز الأصلية للطلب من الدفتر (مصدر الحقيقة لمواضع الحجز ومواقعه). */
752:     private function reserveMovements(Order $order): Collection
753:     {
754:         return StockMovement::query()
755:             ->whereIn('reference_type', array_unique([$order->getMorphClass(), Order::class]))
756:             ->where('reference_id', $order->id)
757:             ->where('type', StockMovementType::Reserve)
758:             ->orderBy('id')
759:             ->get();
760:     }
