762:     // التخزين على مستوى الـ instance لا static (F-27): في Octane/العمال
763:     // طويلة العمر كانت قيمة static تبقى عالقة بين الطلبات وبين الاختبارات
764:     private ?int $systemActorId = null;
765: 
766:     private bool $systemActorResolved = false;
767: 
768:     /**
769:      * منفّذ حركات المخزون: الموظف الفاعل نفسه؛ وعند غيابه (عميل/ويب هوك)
770:      * يُنسب التنفيذ لمستخدم النظام المخصص (M19) — لا لأول Super Admin،
771:      * حتى يبقى سجل التدقيق صادقًا. يُحسم مرة واحدة لكل نسخة خدمة.
772:      */
773:     private function inventoryActorId(?Model $actor): ?int
774:     {
775:         if ($actor instanceof User) {
776:             return (int) $actor->getKey();
777:         }
778: 
779:         if (! $this->systemActorResolved) {
780:             $this->systemActorResolved = true;
781:             $systemId = User::query()
782:                 ->where('is_system', true)
783:                 ->value('id');
784:             $this->systemActorId = $systemId !== null ? (int) $systemId : null;
785:         }
786:         if ($this->systemActorId !== null) {
787:             return $this->systemActorId;
788:         }
789: 
790:         throw new \LogicException('The System audit identity is missing; run the system-user migration before processing automated order effects.');
791:     }
